import type { BankQuestion } from "@/lib/bank";

/** Planning, Budget and Fiscal Policy (Indian Economy): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eco-planning-budget-1","question":"India’s First Five-Year Plan (1951–56) was based mainly on which growth model?","options":["Mahalanobis model","Harrod–Domar model","Lewis two-sector model","Rostow model"],"answer":1,"explanation":"The First Plan used the Harrod–Domar model, linking growth to the savings rate and capital–output ratio, and gave priority to agriculture and irrigation. The Mahalanobis model came with the Second Plan.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"भारत की प्रथम पंचवर्षीय योजना (1951–56) मुख्य रूप से किस वृद्धि मॉडल पर आधारित थी?","optionsHi":["महालनोबिस मॉडल","हैरोड–डोमर मॉडल","लुईस द्वि-क्षेत्रक मॉडल","रोस्टोव मॉडल"],"explanationHi":"प्रथम योजना हैरोड–डोमर मॉडल पर आधारित थी, जो वृद्धि को बचत दर और पूंजी–उत्पाद अनुपात से जोड़ता है; इसमें कृषि और सिंचाई को प्राथमिकता दी गई। महालनोबिस मॉडल द्वितीय योजना के साथ आया।"},
  {"id":"eco-planning-budget-2","question":"In the Constitution of India, the Union Budget is called the:","options":["Annual Appropriation Account","Economic Survey","Finance Bill","Annual Financial Statement"],"answer":3,"explanation":"Article 112 requires the President to lay an “Annual Financial Statement” before Parliament each year; the word “budget” does not appear in the Constitution.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"भारत के संविधान में केंद्रीय बजट को क्या कहा गया है?","optionsHi":["वार्षिक विनियोग लेखा","आर्थिक सर्वेक्षण","वित्त विधेयक","वार्षिक वित्तीय विवरण"],"explanationHi":"अनुच्छेद 112 के अनुसार राष्ट्रपति प्रत्येक वर्ष संसद के समक्ष “वार्षिक वित्तीय विवरण” रखवाते हैं; संविधान में “बजट” शब्द का प्रयोग नहीं हुआ है।"},
  {"id":"eco-planning-budget-3","question":"Who is the ex-officio Chairperson of NITI Aayog?","options":["The President","The Prime Minister","The Vice-Chairperson of NITI Aayog","The Union Finance Minister"],"answer":1,"explanation":"The Prime Minister chairs NITI Aayog; the Vice-Chairperson, appointed by the PM, runs it day to day.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"नीति आयोग का पदेन अध्यक्ष कौन होता है?","optionsHi":["राष्ट्रपति","प्रधानमंत्री","नीति आयोग का उपाध्यक्ष","केंद्रीय वित्त मंत्री"],"explanationHi":"नीति आयोग की अध्यक्षता प्रधानमंत्री करते हैं; प्रधानमंत्री द्वारा नियुक्त उपाध्यक्ष आयोग का दैनिक कार्य संभालता है।"},
  {"id":"eco-planning-budget-4","question":"GST in India is best described as a:","options":["Origin-based production tax","Destination-based consumption tax","Tax on the net worth of business firms","Direct tax on business income"],"answer":1,"explanation":"GST is collected at each stage with input tax credit, and the revenue goes to the state where the goods or services are finally consumed, so it is a destination-based tax on consumption.","difficulty":"easy","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"भारत में GST को सबसे उपयुक्त रूप से क्या कहा जा सकता है?","optionsHi":["मूल-आधारित उत्पादन कर","गंतव्य-आधारित उपभोग कर","व्यावसायिक फर्मों की निवल संपत्ति पर कर","व्यावसायिक आय पर प्रत्यक्ष कर"],"explanationHi":"GST प्रत्येक चरण पर इनपुट टैक्स क्रेडिट के साथ वसूला जाता है और राजस्व उस राज्य को मिलता है जहाँ वस्तुओं या सेवाओं का अंतिम उपभोग होता है, इसलिए यह उपभोग पर गंतव्य-आधारित कर है।"},
  {"id":"eco-planning-budget-5","question":"Who presented independent India’s first Union Budget, on 26 November 1947?","options":["R.K. Shanmukham Chetty","Liaquat Ali Khan","John Mathai","Chintaman Dwarkanath Deshmukh"],"answer":0,"explanation":"R.K. Shanmukham Chetty, the first Finance Minister, presented it. John Mathai presented the first budget of the Republic (1950); Liaquat Ali Khan presented the 1946 interim government budget.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"26 नवंबर 1947 को स्वतंत्र भारत का पहला केंद्रीय बजट किसने प्रस्तुत किया?","optionsHi":["आर.के. षणमुखम चेट्टी","लियाकत अली खान","जॉन मथाई","चिंतामन द्वारकानाथ देशमुख"],"explanationHi":"प्रथम वित्त मंत्री आर.के. षणमुखम चेट्टी ने इसे प्रस्तुत किया। जॉन मथाई ने गणराज्य का पहला बजट (1950) प्रस्तुत किया; लियाकत अली खान ने 1946 की अंतरिम सरकार का बजट प्रस्तुत किया था।"},
  {"id":"eco-planning-budget-6","question":"Under GST, which tax is levied on an inter-state supply of goods or services?","options":["SGST alone","IGST","UTGST","CGST and SGST together"],"answer":1,"explanation":"Inter-state supplies (and imports) attract Integrated GST, collected by the Centre and shared with the destination state. Intra-state supplies attract CGST plus SGST (or UTGST).","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"GST के अंतर्गत वस्तुओं या सेवाओं की अंतर-राज्यीय आपूर्ति पर कौन-सा कर लगता है?","optionsHi":["केवल SGST","IGST","UTGST","CGST और SGST दोनों साथ-साथ"],"explanationHi":"अंतर-राज्यीय आपूर्ति (और आयात) पर एकीकृत GST (IGST) लगता है, जिसे केंद्र वसूलता है और गंतव्य राज्य के साथ साझा करता है। अंतः-राज्यीय आपूर्ति पर CGST के साथ SGST (या UTGST) लगता है।"},
  {"id":"eco-planning-budget-7","question":"Which Five-Year Plan had the theme “Towards Faster and More Inclusive Growth”?","options":["Ninth Plan (1997–2002)","Twelfth Plan (2012–17)","Eleventh Plan (2007–12)","Seventh Plan (1985–1990)"],"answer":2,"explanation":"The Eleventh Plan aimed at faster and more inclusive growth. The Twelfth Plan added one word: “Faster, More Inclusive and Sustainable Growth”.","difficulty":"moderate","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"किस पंचवर्षीय योजना का विषय “तीव्र एवं अधिक समावेशी विकास की ओर” था?","optionsHi":["नौवीं योजना (1997–2002)","बारहवीं योजना (2012–17)","ग्यारहवीं योजना (2007–12)","सातवीं योजना (1985–1990)"],"explanationHi":"ग्यारहवीं योजना का लक्ष्य तीव्र और अधिक समावेशी विकास था। बारहवीं योजना में एक शब्द और जुड़ा: “तीव्र, अधिक समावेशी और सतत विकास”।"},
  {"id":"eco-planning-budget-8","question":"“No tax shall be levied or collected except by authority of law” is laid down in which Article of the Constitution?","options":["Article 300A","Article 280","Article 265","Article 112"],"answer":2,"explanation":"Article 265 bars any tax without a law passed by the legislature. Article 112 is the Annual Financial Statement and Article 280 the Finance Commission.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"“कानून के प्राधिकार के बिना कोई कर न लगाया जाएगा और न वसूला जाएगा” – यह संविधान के किस अनुच्छेद में उल्लिखित है?","optionsHi":["अनुच्छेद 300A","अनुच्छेद 280","अनुच्छेद 265","अनुच्छेद 112"],"explanationHi":"अनुच्छेद 265 विधायिका द्वारा पारित कानून के बिना किसी भी कर के आरोपण पर रोक लगाता है। अनुच्छेद 112 वार्षिक वित्तीय विवरण से और अनुच्छेद 280 वित्त आयोग से संबंधित है।"},
  {"id":"eco-planning-budget-9","question":"Effective revenue deficit, first used in the Union Budget 2011–12, is:","options":["Revenue deficit minus interest payments on all past public debt","Fiscal deficit minus revenue deficit","Fiscal deficit minus interest payments on past borrowing","Revenue deficit minus grants for creation of capital assets"],"answer":3,"explanation":"Effective revenue deficit removes from the revenue deficit the grants (mainly to states) that are spent on building capital assets. Fiscal deficit minus interest payments is the primary deficit.","difficulty":"moderate","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"प्रभावी राजस्व घाटा, जिसका प्रयोग पहली बार केंद्रीय बजट 2011–12 में हुआ, क्या है?","optionsHi":["राजस्व घाटा घटा पिछले सभी सार्वजनिक ऋण पर ब्याज भुगतान","राजकोषीय घाटा घटा राजस्व घाटा","राजकोषीय घाटा घटा पिछले उधार पर ब्याज भुगतान","राजस्व घाटा घटा पूंजीगत परिसंपत्तियों के सृजन हेतु अनुदान"],"explanationHi":"प्रभावी राजस्व घाटा, राजस्व घाटे में से उन अनुदानों (मुख्यतः राज्यों को दिए गए) को घटाकर निकाला जाता है जो पूंजीगत परिसंपत्तियों के निर्माण पर खर्च होते हैं। राजकोषीय घाटे में से ब्याज भुगतान घटाने पर प्राथमिक घाटा प्राप्त होता है।"},
  {"id":"eco-planning-budget-10","question":"Which of the following is “charged” on the Consolidated Fund of India and so is not put to the vote of Lok Sabha?","options":["Salaries and allowances of Union ministers","Salaries of members of Lok Sabha","Expenditure on defence and internal security","Emoluments and allowances of the President"],"answer":3,"explanation":"Under Article 112(3), the President’s emoluments, salaries of the Speaker, judges of the Supreme Court, CAG and others are charged expenditure: discussed but not voted. Ministers’ salaries and defence spending are voted.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन भारत की संचित निधि पर “भारित” है और इसलिए लोकसभा में मतदान के लिए नहीं रखा जाता?","optionsHi":["केंद्रीय मंत्रियों के वेतन और भत्ते","लोकसभा सदस्यों के वेतन","रक्षा और आंतरिक सुरक्षा पर व्यय","राष्ट्रपति की उपलब्धियाँ और भत्ते"],"explanationHi":"अनुच्छेद 112(3) के अंतर्गत राष्ट्रपति की उपलब्धियाँ, अध्यक्ष, उच्चतम न्यायालय के न्यायाधीशों, CAG आदि के वेतन भारित व्यय हैं: इन पर चर्चा हो सकती है, मतदान नहीं। मंत्रियों के वेतन और रक्षा व्यय पर मतदान होता है।"},
  {"id":"eco-planning-budget-11","question":"The Planning Commission of India was set up in March 1950 by:","options":["An Ordinance issued by the President","A resolution of the Union Cabinet","A Constitutional Amendment","An Act of Parliament"],"answer":1,"explanation":"The Planning Commission was neither constitutional nor statutory; it was created by a Cabinet resolution. NITI Aayog was likewise set up by a Cabinet resolution in 2015.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"भारत में योजना आयोग की स्थापना मार्च 1950 में किसके द्वारा की गई थी?","optionsHi":["राष्ट्रपति द्वारा जारी अध्यादेश","केंद्रीय मंत्रिमंडल का एक संकल्प","संविधान संशोधन","संसद का अधिनियम"],"explanationHi":"योजना आयोग न तो संवैधानिक था और न ही सांविधिक; इसकी स्थापना मंत्रिमंडल के संकल्प से हुई थी। नीति आयोग भी 2015 में इसी प्रकार मंत्रिमंडल के संकल्प से बना।"},
  {"id":"eco-planning-budget-12","question":"Who chairs the GST Council?","options":["The Prime Minister","A state Finance Minister chosen by rotation","The Union Finance Minister","The Union Revenue Secretary"],"answer":2,"explanation":"Under Article 279A the Union Finance Minister is the Chairperson; the Union Minister of State for Finance and the Finance Ministers of all states are members.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"GST परिषद की अध्यक्षता कौन करता है?","optionsHi":["प्रधानमंत्री","रोटेशन से चुना गया कोई राज्य वित्त मंत्री","केंद्रीय वित्त मंत्री","केंद्रीय राजस्व सचिव"],"explanationHi":"अनुच्छेद 279A के अंतर्गत केंद्रीय वित्त मंत्री अध्यक्ष होता है; केंद्रीय वित्त राज्य मंत्री और सभी राज्यों के वित्त मंत्री सदस्य होते हैं।"},
  {"id":"eco-planning-budget-13","question":"The “Rolling Plan” of 1978–80 was introduced by:","options":["The Congress government of Rajiv Gandhi","The Janata Party government of Morarji Desai","The Congress (I) government of Indira Gandhi","The National Front government of V.P. Singh"],"answer":1,"explanation":"The Janata government ended the Fifth Plan a year early in 1978 and adopted a rolling plan, an idea associated with Gunnar Myrdal. The Congress returned in 1980 and started a fresh Sixth Plan.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"1978–80 की “रोलिंग योजना” किसके द्वारा शुरू की गई थी?","optionsHi":["राजीव गांधी की कांग्रेस सरकार","मोरारजी देसाई की जनता पार्टी सरकार","इंदिरा गांधी की कांग्रेस (I) सरकार","वी.पी. सिंह की राष्ट्रीय मोर्चा सरकार"],"explanationHi":"जनता सरकार ने 1978 में पाँचवीं योजना को एक वर्ष पहले ही समाप्त कर रोलिंग योजना अपनाई, जिसका विचार गुन्नार मिर्डल से जुड़ा है। 1980 में कांग्रेस लौटी और नई छठी योजना शुरू की।"},
  {"id":"eco-planning-budget-14","question":"Which Five-Year Plan was terminated a year ahead of schedule, in 1978?","options":["Fourth Plan","Sixth Plan","Third Plan","Fifth Plan"],"answer":3,"explanation":"The Fifth Plan (1974–79), with its focus on poverty removal and self-reliance, was ended in 1978 by the new Janata government, which brought in the rolling plan.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"कौन-सी पंचवर्षीय योजना 1978 में निर्धारित समय से एक वर्ष पूर्व समाप्त कर दी गई थी?","optionsHi":["चौथी योजना","छठी योजना","तीसरी योजना","पाँचवीं योजना"],"explanationHi":"गरीबी उन्मूलन और आत्मनिर्भरता पर केंद्रित पाँचवीं योजना (1974–79) को 1978 में नई जनता सरकार ने समाप्त कर दिया और रोलिंग योजना लागू की।"},
  {"id":"eco-planning-budget-15","question":"The first Five-Year Plan launched after the 1991 reforms, which moved India towards indicative planning, was the:","options":["Eighth Plan (1992–97)","Tenth Plan (2002–07)","Seventh Plan (1985–90)","Ninth Plan (1997–2002)"],"answer":0,"explanation":"After two annual plans (1990–92), the Eighth Plan began in 1992 with human resource development as its focus and the state’s role shifting from direct control to indicative planning.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"1991 के सुधारों के बाद शुरू हुई पहली पंचवर्षीय योजना, जिसने भारत को सांकेतिक योजना की ओर मोड़ा, कौन-सी थी?","optionsHi":["आठवीं योजना (1992–97)","दसवीं योजना (2002–07)","सातवीं योजना (1985–90)","नौवीं योजना (1997–2002)"],"explanationHi":"दो वार्षिक योजनाओं (1990–92) के बाद आठवीं योजना 1992 में शुरू हुई, जिसका केंद्र मानव संसाधन विकास था और राज्य की भूमिका प्रत्यक्ष नियंत्रण से सांकेतिक योजना की ओर बदल गई।"},
  {"id":"eco-planning-budget-16","question":"A Gender Budget Statement was first included in the Union Budget in:","options":["2005–06","2014–15","1991–92","2000–01"],"answer":0,"explanation":"Gender budgeting began with the Union Budget 2005–06, showing allocations for schemes that benefit women.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"केंद्रीय बजट में लैंगिक बजट विवरण पहली बार किस वर्ष शामिल किया गया?","optionsHi":["2005–06","2014–15","1991–92","2000–01"],"explanationHi":"लैंगिक बजटिंग की शुरुआत केंद्रीय बजट 2005–06 से हुई, जिसमें महिलाओं को लाभ पहुँचाने वाली योजनाओं के आवंटन दिखाए गए।"},
  {"id":"eco-planning-budget-17","question":"The Railway Budget was merged with the Union (General) Budget with effect from the Budget of:","options":["2014–15","2015–16","2017–18","2019–20"],"answer":2,"explanation":"The 92-year-old practice of a separate Railway Budget ended with the Budget for 2017–18, presented on 1 February 2017, the same year the presentation date moved to 1 February.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"रेल बजट को केंद्रीय (आम) बजट में किस बजट से प्रभावी रूप से मिला दिया गया?","optionsHi":["2014–15","2015–16","2017–18","2019–20"],"explanationHi":"अलग रेल बजट की 92 वर्ष पुरानी परंपरा 2017–18 के बजट के साथ समाप्त हुई, जो 1 फरवरी 2017 को प्रस्तुत हुआ; उसी वर्ष प्रस्तुति की तारीख भी 1 फरवरी कर दी गई।"},
  {"id":"eco-planning-budget-18","question":"The separation of the Railway Budget from the General Budget in 1924 followed the recommendation of the:","options":["Acworth Committee","Royal Commission on Agriculture","Simon Commission","Hilton Young Commission"],"answer":0,"explanation":"The Acworth Committee (1920–21) recommended separating railway finances; the separation came in 1924. The Hilton Young Commission led to the RBI.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"1924 में रेल बजट को आम बजट से अलग करना किसकी सिफारिश के बाद हुआ?","optionsHi":["एकवर्थ समिति","कृषि पर रॉयल आयोग","साइमन आयोग","हिल्टन यंग आयोग"],"explanationHi":"एकवर्थ समिति (1920–21) ने रेल वित्त को अलग करने की सिफारिश की थी; यह पृथक्करण 1924 में हुआ। हिल्टन यंग आयोग के कारण RBI की स्थापना हुई।"},
  {"id":"eco-planning-budget-19","question":"In the GST Council, what weightage does the vote of the Central Government carry?","options":["One-third of the total votes cast","One-fourth of the total votes cast","Half of the total votes cast","Two-thirds of the total votes cast"],"answer":0,"explanation":"The Centre has one-third weight and all states together two-thirds; a decision needs at least three-fourths of the weighted votes, so neither side can pass a proposal alone.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"GST परिषद में केंद्र सरकार के मत का भारांक (वेटेज) कितना होता है?","optionsHi":["डाले गए कुल मतों का एक-तिहाई","डाले गए कुल मतों का एक-चौथाई","डाले गए कुल मतों का आधा","डाले गए कुल मतों का दो-तिहाई"],"explanationHi":"केंद्र का भारांक एक-तिहाई और सभी राज्यों का मिलाकर दो-तिहाई होता है; किसी निर्णय के लिए भारित मतों का कम से कम तीन-चौथाई आवश्यक है, इसलिए कोई भी पक्ष अकेले प्रस्ताव पारित नहीं करा सकता।"},
  {"id":"eco-planning-budget-20","question":"A government’s total expenditure is ₹50 lakh crore, revenue receipts ₹35 lakh crore, non-debt capital receipts ₹3 lakh crore and interest payments ₹5 lakh crore. Its primary deficit is:","options":["₹15 lakh crore","₹10 lakh crore","₹7 lakh crore","₹12 lakh crore"],"answer":2,"explanation":"Fiscal deficit = 50 − (35 + 3) = ₹12 lakh crore. Primary deficit = fiscal deficit − interest = 12 − 5 = ₹7 lakh crore. ₹12 lakh crore is the fiscal deficit, not the primary deficit.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"किसी सरकार का कुल व्यय ₹50 लाख करोड़, राजस्व प्राप्तियाँ ₹35 लाख करोड़, गैर-ऋण पूंजीगत प्राप्तियाँ ₹3 लाख करोड़ और ब्याज भुगतान ₹5 लाख करोड़ है। उसका प्राथमिक घाटा कितना है?","optionsHi":["₹15 लाख करोड़","₹10 लाख करोड़","₹7 लाख करोड़","₹12 लाख करोड़"],"explanationHi":"राजकोषीय घाटा = 50 − (35 + 3) = ₹12 लाख करोड़। प्राथमिक घाटा = राजकोषीय घाटा − ब्याज = 12 − 5 = ₹7 लाख करोड़। ₹12 लाख करोड़ राजकोषीय घाटा है, प्राथमिक घाटा नहीं।"},
  {"id":"eco-planning-budget-21","question":"Revenue receipts are ₹30 lakh crore and revenue expenditure ₹38 lakh crore, of which ₹3 lakh crore is grants for the creation of capital assets. The effective revenue deficit is:","options":["₹8 lakh crore","₹11 lakh crore","₹3 lakh crore","₹5 lakh crore"],"answer":3,"explanation":"Revenue deficit = 38 − 30 = ₹8 lakh crore. Effective revenue deficit = 8 − 3 = ₹5 lakh crore. Adding the grants (₹11 lakh crore) is the usual slip.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"राजस्व प्राप्तियाँ ₹30 लाख करोड़ और राजस्व व्यय ₹38 लाख करोड़ हैं, जिसमें से ₹3 लाख करोड़ पूंजीगत परिसंपत्तियों के सृजन हेतु अनुदान हैं। प्रभावी राजस्व घाटा कितना है?","optionsHi":["₹8 लाख करोड़","₹11 लाख करोड़","₹3 लाख करोड़","₹5 लाख करोड़"],"explanationHi":"राजस्व घाटा = 38 − 30 = ₹8 लाख करोड़। प्रभावी राजस्व घाटा = 8 − 3 = ₹5 लाख करोड़। अनुदान को जोड़ देना (₹11 लाख करोड़) सामान्य भूल है।"},
  {"id":"eco-planning-budget-22","question":"When GST was introduced in 2017, states were guaranteed compensation for loss of revenue for a period of:","options":["Seven years","Ten years","Three years","Five years"],"answer":3,"explanation":"The GST (Compensation to States) Act, 2017 promised compensation for five years (to June 2022), assuming 14% annual growth in revenue, funded by a compensation cess on goods such as tobacco and luxury cars.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"2017 में GST लागू होने पर राज्यों को राजस्व हानि की क्षतिपूर्ति कितने समय के लिए गारंटीकृत की गई थी?","optionsHi":["सात वर्ष","दस वर्ष","तीन वर्ष","पाँच वर्ष"],"explanationHi":"GST (राज्यों को क्षतिपूर्ति) अधिनियम, 2017 में राजस्व में 14% वार्षिक वृद्धि मानते हुए पाँच वर्ष (जून 2022 तक) क्षतिपूर्ति का वादा किया गया था, जिसे तंबाकू और लक्ज़री कारों जैसी वस्तुओं पर लगाए गए क्षतिपूर्ति उपकर से पूरा किया गया।"},
  {"id":"eco-planning-budget-23","question":"The Contingency Fund of India is placed at the disposal of the:","options":["Comptroller and Auditor General","Union Finance Minister","President","Parliament"],"answer":2,"explanation":"Under Article 267, the Contingency Fund is at the disposal of the President, who can make advances from it for unforeseen expenditure pending authorisation by Parliament. It is operated by the Finance Ministry on the President’s behalf.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भारत की आकस्मिकता निधि किसके निपटान में रखी जाती है?","optionsHi":["नियंत्रक एवं महालेखा परीक्षक","केंद्रीय वित्त मंत्री","राष्ट्रपति","संसद"],"explanationHi":"अनुच्छेद 267 के अंतर्गत आकस्मिकता निधि राष्ट्रपति के निपटान में होती है, जो संसद की मंजूरी लंबित रहने तक अप्रत्याशित व्यय के लिए इससे अग्रिम दे सकते हैं। इसका संचालन राष्ट्रपति की ओर से वित्त मंत्रालय करता है।"},
  {"id":"eco-planning-budget-24","question":"The FRBM Review Committee, which in 2017 recommended a general government debt-to-GDP target of 60%, was chaired by:","options":["N.K. Singh","C. Rangarajan","Urjit Patel","Bimal Jalan"],"answer":0,"explanation":"The N.K. Singh committee proposed debt as the main fiscal anchor: 60% of GDP for general government (40% Centre, 20% states) and a 3% fiscal deficit for the Centre.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"FRBM समीक्षा समिति, जिसने 2017 में सामान्य सरकारी ऋण-GDP लक्ष्य 60% रखने की सिफारिश की, किसकी अध्यक्षता में थी?","optionsHi":["एन.के. सिंह","सी. रंगराजन","उर्जित पटेल","बिमल जालान"],"explanationHi":"एन.के. सिंह समिति ने ऋण को मुख्य राजकोषीय आधार बनाने का प्रस्ताव दिया: सामान्य सरकार के लिए GDP का 60% (केंद्र 40%, राज्य 20%) और केंद्र के लिए 3% राजकोषीय घाटा।"},
  {"id":"eco-planning-budget-25","question":"Match the Five-Year Plan with its main emphasis: 1. First Plan  2. Second Plan  3. Fifth Plan  4. Eighth Plan; a. Removal of poverty and self-reliance  b. Rapid industrialisation with heavy industry  c. Human resource development after the reforms  d. Agriculture and irrigation","options":["1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c","1-d, 2-b, 3-c, 4-a","1-a, 2-b, 3-d, 4-c"],"answer":0,"explanation":"First Plan: agriculture and irrigation; Second: heavy industry (Mahalanobis); Fifth: Garibi Hatao and self-reliance; Eighth: human resource development in the post-1991 economy.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"पंचवर्षीय योजना का उसके मुख्य बल से मिलान कीजिए: 1. प्रथम योजना  2. द्वितीय योजना  3. पाँचवीं योजना  4. आठवीं योजना; a. गरीबी उन्मूलन और आत्मनिर्भरता  b. भारी उद्योग के साथ तीव्र औद्योगीकरण  c. सुधारों के बाद मानव संसाधन विकास  d. कृषि और सिंचाई","optionsHi":["1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c","1-d, 2-b, 3-c, 4-a","1-a, 2-b, 3-d, 4-c"],"explanationHi":"प्रथम योजना: कृषि और सिंचाई; द्वितीय: भारी उद्योग (महालनोबिस); पाँचवीं: गरीबी हटाओ और आत्मनिर्भरता; आठवीं: 1991 के बाद की अर्थव्यवस्था में मानव संसाधन विकास।"},
  {"id":"eco-planning-budget-26","question":"How many of these statements about NITI Aayog are correct? I. It was set up on 1 January 2015 by a Cabinet resolution. II. It is a constitutional body. III. Its Governing Council includes the Chief Ministers of all states. IV. It allocates plan funds to states.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. NITI Aayog is neither constitutional nor statutory (II wrong), and unlike the Planning Commission it has no power to allocate funds; devolution is now via the Finance Commission and ministries (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"नीति आयोग के बारे में इनमें से कितने कथन सही हैं? I. इसकी स्थापना 1 जनवरी 2015 को मंत्रिमंडल के संकल्प द्वारा हुई। II. यह एक संवैधानिक निकाय है। III. इसकी शासी परिषद में सभी राज्यों के मुख्यमंत्री शामिल हैं। IV. यह राज्यों को योजना निधि आवंटित करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। नीति आयोग न संवैधानिक है, न सांविधिक (II गलत), और योजना आयोग के विपरीत इसके पास निधि आवंटन की शक्ति नहीं है; अब हस्तांतरण वित्त आयोग और मंत्रालयों के माध्यम से होता है (IV गलत)।"},
  {"id":"eco-planning-budget-27","question":"Assertion (A): The fiscal deficit shows the total borrowing requirement of the government in a year. Reason (R): Fiscal deficit equals total expenditure minus the sum of revenue receipts and non-debt capital receipts.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true. The gap between what the government spends and what it receives without borrowing can be filled only by borrowing, so the formula in R is exactly why the fiscal deficit measures borrowing.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"अभिकथन (A): राजकोषीय घाटा किसी वर्ष में सरकार की कुल उधारी आवश्यकता को दर्शाता है। कारण (R): राजकोषीय घाटा कुल व्यय में से राजस्व प्राप्तियों और गैर-ऋण पूंजीगत प्राप्तियों के योग को घटाने पर प्राप्त होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं। सरकार जो खर्च करती है और बिना उधार के जो पाती है, उसके बीच का अंतर उधारी से ही पूरा हो सकता है, इसलिए R का सूत्र ही बताता है कि राजकोषीय घाटा उधारी को क्यों मापता है।"},
  {"id":"eco-planning-budget-28","question":"How many of these statements are correct? I. Alcoholic liquor for human consumption is kept out of GST by the Constitution itself. II. GST on petrol, diesel, crude oil, natural gas and ATF can be levied from a date recommended by the GST Council. III. Electricity is taxed under GST. IV. The 101st Amendment inserted Article 246A, giving the Centre and states concurrent power to levy GST.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Article 366(12A) excludes alcoholic liquor; the five petroleum products are within GST in law but await a Council recommendation; Article 246A gives simultaneous taxing power. Electricity is outside GST (III wrong).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कितने कथन सही हैं? I. मानव उपभोग हेतु मादक शराब को संविधान ने स्वयं GST से बाहर रखा है। II. पेट्रोल, डीजल, कच्चे तेल, प्राकृतिक गैस और ATF पर GST, GST परिषद द्वारा अनुशंसित तिथि से लगाया जा सकता है। III. बिजली पर GST लगता है। IV. 101वें संशोधन ने अनुच्छेद 246A जोड़ा, जो केंद्र और राज्यों को GST लगाने की समवर्ती शक्ति देता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। अनुच्छेद 366(12A) मादक शराब को बाहर रखता है; पाँच पेट्रोलियम उत्पाद कानून में GST के अंतर्गत हैं पर परिषद की सिफारिश की प्रतीक्षा में हैं; अनुच्छेद 246A एक साथ कर लगाने की शक्ति देता है। बिजली GST से बाहर है (III गलत)।"},
  {"id":"eco-planning-budget-29","question":"Which of the following is NOT a capital receipt of the Government of India?","options":["Recovery of loans given to states","Interest received on loans given to states","Proceeds from disinvestment","Market borrowings"],"answer":1,"explanation":"Interest received is income that creates no liability and does not reduce assets, so it is a revenue receipt. Disinvestment and loan recoveries reduce assets and borrowings create liabilities, so they are capital receipts.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"निम्नलिखित में से कौन-सी भारत सरकार की पूंजीगत प्राप्ति नहीं है?","optionsHi":["राज्यों को दिए गए ऋणों की वसूली","राज्यों को दिए गए ऋणों पर प्राप्त ब्याज","विनिवेश से प्राप्तियाँ","बाज़ार से उधार"],"explanationHi":"प्राप्त ब्याज ऐसी आय है जो कोई दायित्व नहीं बनाती और परिसंपत्तियाँ भी नहीं घटाती, इसलिए यह राजस्व प्राप्ति है। विनिवेश और ऋण वसूली परिसंपत्तियाँ घटाते हैं तथा उधार दायित्व बनाता है, इसलिए ये पूंजीगत प्राप्तियाँ हैं।"},
  {"id":"eco-planning-budget-30","question":"Arrange in chronological order: 1. Formation of NITI Aayog  2. Setting up of the National Development Council  3. Adoption of the Rolling Plan  4. Setting up of the Planning Commission","options":["2, 4, 3, 1","4, 2, 3, 1","4, 3, 2, 1","4, 2, 1, 3"],"answer":1,"explanation":"Planning Commission: March 1950; National Development Council: August 1952; Rolling Plan: 1978; NITI Aayog: January 2015.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. नीति आयोग का गठन  2. राष्ट्रीय विकास परिषद की स्थापना  3. रोलिंग योजना को अपनाना  4. योजना आयोग की स्थापना","optionsHi":["2, 4, 3, 1","4, 2, 3, 1","4, 3, 2, 1","4, 2, 1, 3"],"explanationHi":"योजना आयोग: मार्च 1950; राष्ट्रीय विकास परिषद: अगस्त 1952; रोलिंग योजना: 1978; नीति आयोग: जनवरी 2015।"},
  {"id":"eco-planning-budget-31","question":"A government’s budget shows: total expenditure ₹4,000 crore, revenue expenditure ₹3,000 crore, revenue receipts ₹2,400 crore, recovery of loans ₹100 crore, disinvestment ₹50 crore and interest payments ₹500 crore. Its fiscal deficit and primary deficit are respectively:","options":["₹600 crore and ₹100 crore","₹1,450 crore and ₹950 crore","₹1,450 crore and ₹850 crore","₹1,600 crore and ₹1,100 crore"],"answer":1,"explanation":"Non-debt receipts = 2,400 + 100 + 50 = 2,550. Fiscal deficit = 4,000 − 2,550 = ₹1,450 crore. Primary deficit = 1,450 − 500 = ₹950 crore. ₹600 crore is the revenue deficit (3,000 − 2,400).","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"किसी सरकार के बजट में कुल व्यय ₹4,000 करोड़, राजस्व व्यय ₹3,000 करोड़, राजस्व प्राप्तियाँ ₹2,400 करोड़, ऋणों की वसूली ₹100 करोड़, विनिवेश ₹50 करोड़ और ब्याज भुगतान ₹500 करोड़ दर्शाए गए हैं। उसका राजकोषीय घाटा और प्राथमिक घाटा क्रमशः कितने हैं?","optionsHi":["₹600 करोड़ और ₹100 करोड़","₹1,450 करोड़ और ₹950 करोड़","₹1,450 करोड़ और ₹850 करोड़","₹1,600 करोड़ और ₹1,100 करोड़"],"explanationHi":"गैर-ऋण प्राप्तियाँ = 2,400 + 100 + 50 = 2,550। राजकोषीय घाटा = 4,000 − 2,550 = ₹1,450 करोड़। प्राथमिक घाटा = 1,450 − 500 = ₹950 करोड़। ₹600 करोड़ राजस्व घाटा है (3,000 − 2,400)।"},
  {"id":"eco-planning-budget-32","question":"How many of these statements about the FRBM framework are correct? I. The FRBM Act was passed in 2003 and came into force in 2004. II. Amendments in 2018 made the debt-to-GDP ratio the main fiscal anchor. III. An escape clause allows the fiscal deficit target to be exceeded by up to 0.5% of GDP on specified grounds. IV. A Medium-Term Fiscal Policy Statement must be laid before Parliament with the Budget.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Act (2003) took effect in July 2004; the Finance Act 2018 shifted the anchor to debt; the escape clause permits a 0.5 percentage-point deviation for war, national calamity, structural reforms and the like; the Medium-Term Fiscal Policy Statement is one of the statements required by the Act.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"FRBM ढाँचे के बारे में इनमें से कितने कथन सही हैं? I. FRBM अधिनियम 2003 में पारित हुआ और 2004 में लागू हुआ। II. 2018 के संशोधनों ने ऋण-GDP अनुपात को मुख्य राजकोषीय आधार बनाया। III. एक निकासी खंड (escape clause) निर्दिष्ट आधारों पर राजकोषीय घाटा लक्ष्य को GDP के 0.5% तक पार करने की अनुमति देता है। IV. मध्यम अवधि राजकोषीय नीति विवरण बजट के साथ संसद में रखा जाना आवश्यक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। अधिनियम (2003) जुलाई 2004 से प्रभावी हुआ; वित्त अधिनियम 2018 ने आधार को ऋण पर स्थानांतरित किया; निकासी खंड युद्ध, राष्ट्रीय आपदा, संरचनात्मक सुधार आदि के लिए 0.5 प्रतिशत अंक के विचलन की अनुमति देता है; मध्यम अवधि राजकोषीय नीति विवरण अधिनियम द्वारा अपेक्षित विवरणों में से एक है।"},
  {"id":"eco-planning-budget-33","question":"Match the budget document with the Article of the Constitution: 1. Annual Financial Statement  2. Appropriation Bill  3. Supplementary grants  4. Vote on account; a. Article 114  b. Article 112  c. Article 115  d. Article 116","options":["1-b, 2-a, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-a, 2-b, 3-c, 4-d","1-b, 2-c, 3-a, 4-d"],"answer":0,"explanation":"Article 112: Annual Financial Statement; Article 114: Appropriation Bills; Article 115: supplementary, additional or excess grants; Article 116: votes on account, votes of credit and exceptional grants.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"बजट दस्तावेज़ का संविधान के अनुच्छेद से मिलान कीजिए: 1. वार्षिक वित्तीय विवरण  2. विनियोग विधेयक  3. अनुपूरक अनुदान  4. लेखानुदान; a. अनुच्छेद 114  b. अनुच्छेद 112  c. अनुच्छेद 115  d. अनुच्छेद 116","optionsHi":["1-b, 2-a, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-a, 2-b, 3-c, 4-d","1-b, 2-c, 3-a, 4-d"],"explanationHi":"अनुच्छेद 112: वार्षिक वित्तीय विवरण; अनुच्छेद 114: विनियोग विधेयक; अनुच्छेद 115: अनुपूरक, अतिरिक्त या आधिक्य अनुदान; अनुच्छेद 116: लेखानुदान, प्रत्ययानुदान और अपवादानुदान।"},
  {"id":"eco-planning-budget-34","question":"Assertion (A): A Money Bill can be introduced only in the Lok Sabha. Reason (R): The Rajya Sabha can delay a Money Bill for at most 14 days.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but R does not explain A. A follows from Article 109, which reserves the introduction of Money Bills to the Lok Sabha; the 14-day limit is a separate rule on how long the Rajya Sabha may hold such a bill.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): धन विधेयक केवल लोकसभा में पुरःस्थापित किया जा सकता है। कारण (R): राज्यसभा धन विधेयक को अधिकतम 14 दिन तक ही रोक सकती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं, पर R, A की व्याख्या नहीं करता। A अनुच्छेद 109 से निकलता है, जो धन विधेयकों के पुरःस्थापन को लोकसभा तक सीमित करता है; 14 दिन की सीमा एक अलग नियम है कि राज्यसभा ऐसे विधेयक को कितनी देर रोक सकती है।"},
  {"id":"eco-planning-budget-35","question":"How many of these statements about the Five-Year Plans are correct? I. The Third Plan fell short of its targets mainly because of the wars of 1962 and 1965 and the drought of 1965–66. II. The Fourth Plan aimed at “growth with stability and progressive achievement of self-reliance”. III. The Seventh Plan was followed by two annual plans. IV. The Twelfth Plan (2012–17) was the last Five-Year Plan.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: the Third Plan was hit by wars and the 1965–66 drought; the Fourth Plan aimed at growth with stability; the annual plans of 1990–91 and 1991–92 followed the Seventh Plan; and the Twelfth Plan (2012–17) was the last.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पंचवर्षीय योजनाओं के बारे में इनमें से कितने कथन सही हैं? I. तीसरी योजना मुख्यतः 1962 और 1965 के युद्धों तथा 1965–66 के सूखे के कारण अपने लक्ष्यों से पीछे रह गई। II. चौथी योजना का उद्देश्य “स्थिरता के साथ वृद्धि और आत्मनिर्भरता की प्रगतिशील प्राप्ति” था। III. सातवीं योजना के बाद दो वार्षिक योजनाएँ आईं। IV. बारहवीं योजना (2012–17) अंतिम पंचवर्षीय योजना थी।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: तीसरी योजना युद्धों और 1965–66 के सूखे से प्रभावित हुई; चौथी योजना का लक्ष्य स्थिरता के साथ वृद्धि था; सातवीं योजना के बाद 1990–91 और 1991–92 की वार्षिक योजनाएँ आईं; और बारहवीं योजना (2012–17) अंतिम थी।"},
  {"id":"eco-planning-budget-36","question":"How many of these statements about the Union Budget process are correct? I. Since 2017 the Union Budget has been presented on the last working day of February. II. The Economic Survey is prepared under the Chief Economic Adviser in the Department of Revenue. III. Demands for grants still undiscussed on the last allotted day are put to vote together through the “guillotine”. IV. Cut motions on demands for grants can be moved in the Rajya Sabha.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only III is correct. Since 2017 the Budget is presented on 1 February (I wrong); the Economic Survey comes from the Department of Economic Affairs (II wrong); and cut motions can be moved only in the Lok Sabha (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"केंद्रीय बजट प्रक्रिया के बारे में इनमें से कितने कथन सही हैं? I. 2017 से केंद्रीय बजट फरवरी के अंतिम कार्यदिवस को प्रस्तुत किया जाता है। II. आर्थिक सर्वेक्षण राजस्व विभाग में मुख्य आर्थिक सलाहकार के अधीन तैयार होता है। III. अनुदान मांगें, जिन पर आवंटित अंतिम दिन तक चर्चा नहीं हुई, “गिलोटिन” द्वारा एक साथ मतदान के लिए रखी जाती हैं। IV. अनुदान मांगों पर कटौती प्रस्ताव राज्यसभा में लाए जा सकते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल III सही है। 2017 से बजट 1 फरवरी को प्रस्तुत होता है (I गलत); आर्थिक सर्वेक्षण आर्थिक कार्य विभाग से आता है (II गलत); और कटौती प्रस्ताव केवल लोकसभा में लाए जा सकते हैं (IV गलत)।"},
  {"id":"eco-planning-budget-37","question":"Assertion (A): Heavy government borrowing can reduce private investment. Reason (R): Government borrowing raises the demand for loanable funds and pushes up interest rates.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: this is the crowding-out effect. Higher interest rates make private projects costlier to finance, so some private investment is displaced.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): सरकार की भारी उधारी निजी निवेश को घटा सकती है। कारण (R): सरकारी उधारी ऋण योग्य निधियों की मांग बढ़ाती है और ब्याज दरों को ऊपर धकेलती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: यह भीड़-बाह्यकरण (क्राउडिंग-आउट) प्रभाव है। ऊँची ब्याज दरों से निजी परियोजनाओं का वित्तपोषण महंगा हो जाता है, इसलिए कुछ निजी निवेश विस्थापित हो जाता है।"},
  {"id":"eco-planning-budget-38","question":"Match the committee with its subject: 1. Raja Chelliah Committee  2. Vijay Kelkar Task Force (2002)  3. N.K. Singh Committee (2017)  4. C. Rangarajan Expert Group (2014); a. Measurement of poverty  b. Review of the FRBM Act  c. Tax reforms after 1991  d. Direct and indirect tax reform","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-d, 4-a"],"answer":2,"explanation":"Raja Chelliah chaired the Tax Reforms Committee (1991); Vijay Kelkar headed the task forces on direct and indirect taxes (2002); N.K. Singh reviewed the FRBM Act; the Rangarajan group re-estimated poverty in 2014.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"समिति का उसके विषय से मिलान कीजिए: 1. राजा चेलैया समिति  2. विजय केलकर कार्यबल (2002)  3. एन.के. सिंह समिति (2017)  4. सी. रंगराजन विशेषज्ञ समूह (2014); a. गरीबी का मापन  b. FRBM अधिनियम की समीक्षा  c. 1991 के बाद कर सुधार  d. प्रत्यक्ष और अप्रत्यक्ष कर सुधार","optionsHi":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-d, 4-a"],"explanationHi":"राजा चेलैया ने कर सुधार समिति (1991) की अध्यक्षता की; विजय केलकर ने प्रत्यक्ष और अप्रत्यक्ष करों पर कार्यबलों (2002) का नेतृत्व किया; एन.के. सिंह ने FRBM अधिनियम की समीक्षा की; रंगराजन समूह ने 2014 में गरीबी का पुनः आकलन किया।"},
  {"id":"eco-planning-budget-39","question":"A dealer in one state buys goods for ₹10,000 plus 18% GST and sells them within the same state for ₹15,000 plus 18% GST. After input tax credit, how much CGST does the dealer deposit?","options":["₹450","₹2,700","₹900","₹1,350"],"answer":0,"explanation":"Output GST = 18% of 15,000 = 2,700; input credit = 18% of 10,000 = 1,800; net GST = 900. For an intra-state sale this is split equally into CGST and SGST, so CGST = ₹450. ₹900 is the total GST, not the CGST.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"एक राज्य का व्यापारी ₹10,000 जमा 18% GST पर माल खरीदता है और उसे उसी राज्य में ₹15,000 जमा 18% GST पर बेचता है। इनपुट टैक्स क्रेडिट के बाद व्यापारी कितना CGST जमा करता है?","optionsHi":["₹450","₹2,700","₹900","₹1,350"],"explanationHi":"आउटपुट GST = 15,000 का 18% = 2,700; इनपुट क्रेडिट = 10,000 का 18% = 1,800; निवल GST = 900। अंतः-राज्यीय बिक्री में यह CGST और SGST में बराबर बँटता है, इसलिए CGST = ₹450। ₹900 कुल GST है, CGST नहीं।"},
  {"id":"eco-planning-budget-40","question":"Which of the following taxes was NOT subsumed in GST?","options":["State VAT on most goods","Service tax","Basic customs duty on imports","Central excise duty on most manufactured goods"],"answer":2,"explanation":"GST replaced service tax, most central excise and state VAT, among others. Basic customs duty still applies to imports separately; only the countervailing and special additional duties on imports were replaced by IGST.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा कर GST में समाहित नहीं किया गया?","optionsHi":["अधिकांश वस्तुओं पर राज्य VAT","सेवा कर","आयात पर मूल सीमा शुल्क","अधिकांश विनिर्मित वस्तुओं पर केंद्रीय उत्पाद शुल्क"],"explanationHi":"GST ने सेवा कर, अधिकांश केंद्रीय उत्पाद शुल्क और राज्य VAT आदि का स्थान लिया। आयात पर मूल सीमा शुल्क अब भी अलग से लगता है; आयात पर केवल प्रतिकारी और विशेष अतिरिक्त शुल्कों का स्थान IGST ने लिया।"},
  {"id":"eco-planning-budget-41","question":"Which was the last Five-Year Plan in India?","options":["Tenth Plan","Eleventh Plan","Twelfth Plan","Thirteenth Plan"],"answer":2,"explanation":"The Twelfth Plan (2012–17) was the last. After the Planning Commission was replaced by NITI Aayog in 2015, no new Five-Year Plan was launched.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"भारत की अंतिम पंचवर्षीय योजना कौन-सी थी?","optionsHi":["दसवीं योजना","ग्यारहवीं योजना","बारहवीं योजना","तेरहवीं योजना"],"explanationHi":"बारहवीं योजना (2012–17) अंतिम थी। 2015 में योजना आयोग की जगह नीति आयोग आने के बाद कोई नई पंचवर्षीय योजना शुरू नहीं की गई।"},
  {"id":"eco-planning-budget-42","question":"India's financial year runs from:","options":["1 January to 31 December","1 April to 31 March","1 July to 30 June","1 October to 30 September"],"answer":1,"explanation":"The Government of India's financial year runs from 1 April to 31 March; the Budget for it is now presented on 1 February.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"भारत का वित्तीय वर्ष कब से कब तक चलता है?","optionsHi":["1 जनवरी से 31 दिसंबर","1 अप्रैल से 31 मार्च","1 जुलाई से 30 जून","1 अक्टूबर से 30 सितंबर"],"explanationHi":"भारत सरकार का वित्तीय वर्ष 1 अप्रैल से 31 मार्च तक चलता है; इसका बजट अब 1 फरवरी को प्रस्तुत किया जाता है।"},
  {"id":"eco-planning-budget-43","question":"The Second Five-Year Plan (1956–61), which stressed heavy industry, was based on the model of:","options":["Harrod and Domar","P. C. Mahalanobis","Arthur Lewis","John Maynard Keynes"],"answer":1,"explanation":"The Mahalanobis model gave priority to capital goods and heavy industry. The First Plan followed the Harrod–Domar model.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"द्वितीय पंचवर्षीय योजना (1956–61), जिसमें भारी उद्योग पर बल दिया गया, किस मॉडल पर आधारित थी?","optionsHi":["हैरोड और डोमर","पी. सी. महालनोबिस","आर्थर लुईस","जॉन मेनार्ड कीन्स"],"explanationHi":"महालनोबिस मॉडल ने पूंजीगत वस्तुओं और भारी उद्योग को प्राथमिकता दी। प्रथम योजना हैरोड–डोमर मॉडल पर आधारित थी।"},
  {"id":"eco-planning-budget-44","question":"The period 1966–69, when Annual Plans replaced a Five-Year Plan, is known as the:","options":["Rolling Plan period","Plan Holiday","Indicative Planning phase","Green Revolution phase"],"answer":1,"explanation":"After the Third Plan, wars and droughts led to three Annual Plans (1966–69), called the Plan Holiday. The Fourth Plan began in 1969.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"1966–69 की वह अवधि, जब पंचवर्षीय योजना के स्थान पर वार्षिक योजनाएँ चलीं, किस नाम से जानी जाती है?","optionsHi":["रोलिंग योजना काल","योजना अवकाश (प्लान हॉलिडे)","सांकेतिक योजना चरण","हरित क्रांति चरण"],"explanationHi":"तीसरी योजना के बाद युद्धों और सूखे के कारण तीन वार्षिक योजनाएँ (1966–69) चलीं, जिन्हें योजना अवकाश कहा गया। चौथी योजना 1969 में शुरू हुई।"},
  {"id":"eco-planning-budget-45","question":"Income tax is an example of a:","options":["Direct tax","Indirect tax","Goods and services tax","Customs duty"],"answer":0,"explanation":"A direct tax is paid by the person on whom it is levied and cannot be shifted. GST and customs duty are indirect taxes.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"आयकर किसका उदाहरण है?","optionsHi":["प्रत्यक्ष कर","अप्रत्यक्ष कर","वस्तु एवं सेवा कर","सीमा शुल्क"],"explanationHi":"प्रत्यक्ष कर उसी व्यक्ति द्वारा चुकाया जाता है जिस पर यह लगाया गया हो और इसे किसी अन्य पर नहीं डाला जा सकता। GST और सीमा शुल्क अप्रत्यक्ष कर हैं।"},
  {"id":"eco-planning-budget-46","question":"An Outcome Budget, linking money spent to measurable results, was first presented by the Union Government in:","options":["1991–92","2000–01","2005–06","2017–18"],"answer":2,"explanation":"The first Outcome Budget was presented in 2005–06, the same year the Gender Budget Statement first appeared.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"खर्च किए गए धन को मापनीय परिणामों से जोड़ने वाला परिणाम बजट (आउटकम बजट) केंद्र सरकार ने पहली बार किस वर्ष प्रस्तुत किया?","optionsHi":["1991–92","2000–01","2005–06","2017–18"],"explanationHi":"पहला परिणाम बजट 2005–06 में प्रस्तुत हुआ, उसी वर्ष लैंगिक बजट विवरण भी पहली बार आया।"},
  {"id":"eco-planning-budget-47","question":"In India, fiscal policy is framed mainly by the:","options":["Reserve Bank of India","Ministry of Finance","NITI Aayog","SEBI"],"answer":1,"explanation":"Fiscal policy (taxation, spending, borrowing) is the Government's, through the Ministry of Finance. Monetary policy is the RBI's.","difficulty":"moderate","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"भारत में राजकोषीय नीति मुख्यतः किसके द्वारा बनाई जाती है?","optionsHi":["भारतीय रिज़र्व बैंक","वित्त मंत्रालय","नीति आयोग","SEBI"],"explanationHi":"राजकोषीय नीति (कराधान, व्यय, उधारी) सरकार की होती है, जो वित्त मंत्रालय के माध्यम से बनती है। मौद्रिक नीति RBI की होती है।"},
  {"id":"eco-planning-budget-48","question":"The tax proposals in the Union Budget are given legal effect through the:","options":["Appropriation Bill","Finance Bill","Vote on account","Demands for grants"],"answer":1,"explanation":"The Finance Bill carries the taxation proposals. The Appropriation Bill authorises withdrawal of money from the Consolidated Fund for expenditure.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"केंद्रीय बजट के कर प्रस्तावों को कानूनी प्रभाव किसके माध्यम से मिलता है?","optionsHi":["विनियोग विधेयक","वित्त विधेयक","लेखानुदान","अनुदान मांगें"],"explanationHi":"वित्त विधेयक में कराधान संबंधी प्रस्ताव होते हैं। विनियोग विधेयक व्यय के लिए संचित निधि से धन निकालने को प्राधिकृत करता है।"},
  {"id":"eco-planning-budget-49","question":"Who was the first Deputy Chairman of the Planning Commission?","options":["V. T. Krishnamachari","Gulzarilal Nanda","C. D. Deshmukh","P. C. Mahalanobis"],"answer":1,"explanation":"Gulzarilal Nanda was the first Deputy Chairman (1950); the Prime Minister, Jawaharlal Nehru, was the Chairman.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"योजना आयोग के प्रथम उपाध्यक्ष कौन थे?","optionsHi":["वी. टी. कृष्णमाचारी","गुलजारीलाल नंदा","सी. डी. देशमुख","पी. सी. महालनोबिस"],"explanationHi":"गुलजारीलाल नंदा प्रथम उपाध्यक्ष (1950) थे; प्रधानमंत्री जवाहरलाल नेहरू अध्यक्ष थे।"},
  {"id":"eco-planning-budget-50","question":"Who was the first Vice-Chairperson of NITI Aayog?","options":["Rajiv Kumar","Arvind Panagariya","Montek Singh Ahluwalia","Amitabh Kant"],"answer":1,"explanation":"Arvind Panagariya was the first Vice-Chairperson (2015–17). Amitabh Kant was its CEO and Rajiv Kumar a later Vice-Chairperson; Montek Singh Ahluwalia was the last Deputy Chairman of the Planning Commission, not NITI Aayog.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"नीति आयोग के प्रथम उपाध्यक्ष कौन थे?","optionsHi":["राजीव कुमार","अरविंद पनगढ़िया","मोंटेक सिंह अहलूवालिया","अमिताभ कांत"],"explanationHi":"अरविंद पनगढ़िया प्रथम उपाध्यक्ष (2015–17) थे। अमिताभ कांत इसके मुख्य कार्यकारी अधिकारी (CEO) और राजीव कुमार बाद के उपाध्यक्ष थे; मोंटेक सिंह अहलूवालिया योजना आयोग के अंतिम उपाध्यक्ष थे, नीति आयोग के नहीं।"},
  {"id":"eco-planning-budget-51","question":"The theme of the Twelfth Five-Year Plan (2012–17) was:","options":["Growth with social justice and equality","Towards faster and more inclusive growth","Faster, more inclusive and sustainable growth","Growth with stability and progressive self-reliance"],"answer":2,"explanation":"The Twelfth Plan added ‘sustainable’ to the Eleventh Plan's theme of faster and more inclusive growth. Growth with stability and progressive self-reliance was the Fourth Plan's aim.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"बारहवीं पंचवर्षीय योजना (2012–17) का विषय क्या था?","optionsHi":["सामाजिक न्याय और समानता के साथ वृद्धि","तीव्र एवं अधिक समावेशी विकास की ओर","तीव्र, अधिक समावेशी और सतत विकास","स्थिरता और प्रगतिशील आत्मनिर्भरता के साथ वृद्धि"],"explanationHi":"बारहवीं योजना ने ग्यारहवीं योजना के तीव्र और अधिक समावेशी विकास के विषय में ‘सतत’ शब्द जोड़ा। स्थिरता और प्रगतिशील आत्मनिर्भरता के साथ वृद्धि चौथी योजना का उद्देश्य था।"},
  {"id":"eco-planning-budget-52","question":"The Laffer curve shows the relationship between:","options":["Inflation and unemployment","Tax rates and tax revenue","Income and inequality","Money supply and prices"],"answer":1,"explanation":"The Laffer curve suggests that beyond some point higher tax rates reduce total tax revenue. Inflation and unemployment are linked by the Phillips curve.","difficulty":"moderate","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"लैफर वक्र किसके बीच संबंध दर्शाता है?","optionsHi":["मुद्रास्फीति और बेरोज़गारी","कर दरें और कर राजस्व","आय और असमानता","मुद्रा आपूर्ति और कीमतें"],"explanationHi":"लैफर वक्र बताता है कि एक सीमा के बाद ऊँची कर दरें कुल कर राजस्व को घटा देती हैं। मुद्रास्फीति और बेरोज़गारी का संबंध फिलिप्स वक्र से दिखाया जाता है।"},
  {"id":"eco-planning-budget-53","question":"Direct Benefit Transfer, which credits subsidies and welfare payments straight into beneficiaries' bank accounts, was launched in India on:","options":["1 April 2010","1 January 2013","15 August 2014","1 July 2017"],"answer":1,"explanation":"DBT began on 1 January 2013. The Jan Dhan Yojana (August 2014) and Aadhaar later formed the ‘JAM’ trinity that widened it.","difficulty":"moderate","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"प्रत्यक्ष लाभ अंतरण (DBT), जिसमें सब्सिडी और कल्याणकारी भुगतान सीधे लाभार्थियों के बैंक खातों में जमा होते हैं, भारत में कब शुरू हुआ?","optionsHi":["1 अप्रैल 2010","1 जनवरी 2013","15 अगस्त 2014","1 जुलाई 2017"],"explanationHi":"DBT की शुरुआत 1 जनवरी 2013 को हुई। जन धन योजना (अगस्त 2014) और आधार ने बाद में ‘JAM’ त्रयी बनाकर इसका दायरा बढ़ाया।"},
  {"id":"eco-planning-budget-54","question":"When a government's estimated receipts are exactly equal to its estimated expenditure, its budget is called a:","options":["Deficit budget","Surplus budget","Balanced budget","Zero-based budget"],"answer":2,"explanation":"A balanced budget has receipts equal to expenditure. A zero-based budget is a method of preparing estimates from scratch, not a type of balance.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"जब किसी सरकार की अनुमानित प्राप्तियाँ उसके अनुमानित व्यय के ठीक बराबर होती हैं, तो उसका बजट क्या कहलाता है?","optionsHi":["घाटे का बजट","अधिशेष बजट","संतुलित बजट","शून्य-आधारित बजट"],"explanationHi":"संतुलित बजट में प्राप्तियाँ व्यय के बराबर होती हैं। शून्य-आधारित बजट अनुमान शुरू से तैयार करने की एक पद्धति है, संतुलन का कोई प्रकार नहीं।"},
  {"id":"eco-planning-budget-55","question":"The Union Budget 2025–26 set the fiscal deficit target (Budget Estimate) at:","options":["3.0% of GDP","4.4% of GDP","4.9% of GDP","5.1% of GDP"],"answer":1,"explanation":"Budget 2025–26 placed the fiscal deficit at 4.4% of GDP, down from 4.8% in the revised estimate for 2024–25.","difficulty":"hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"केंद्रीय बजट 2025–26 ने राजकोषीय घाटे का लक्ष्य (बजट अनुमान) कितना रखा?","optionsHi":["GDP का 3.0%","GDP का 4.4%","GDP का 4.9%","GDP का 5.1%"],"explanationHi":"बजट 2025–26 में राजकोषीय घाटा GDP का 4.4% रखा गया, जो 2024–25 के संशोधित अनुमान में 4.8% था।"},
  {"id":"eco-planning-budget-56","question":"In place of Five-Year Plans, NITI Aayog proposed a set of documents consisting of a:","options":["10-year plan with a 5-year mid-term review","20-year perspective plan with annual plans","15-year vision, 7-year strategy, 3-year action agenda","25-year vision, 10-year strategy and 5-year action plans"],"answer":1,"explanation":"NITI Aayog replaced Five-Year Plans with a 15-year vision, a 7-year strategy and a 3-year action agenda; the first Three-Year Action Agenda covered 2017–18 to 2019–20.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पंचवर्षीय योजनाओं के स्थान पर नीति आयोग ने दस्तावेज़ों का कौन-सा समूह प्रस्तावित किया?","optionsHi":["10 वर्ष की योजना, जिसकी 5 वर्ष पर मध्यावधि समीक्षा हो","वार्षिक योजनाओं के साथ 20 वर्ष की परिप्रेक्ष्य योजना","15 वर्ष का विज़न, 7 वर्ष की रणनीति, 3 वर्ष का कार्य एजेंडा","25 वर्ष का विज़न, 10 वर्ष की रणनीति और 5 वर्ष की कार्य योजनाएँ"],"explanationHi":"नीति आयोग ने पंचवर्षीय योजनाओं की जगह 15 वर्ष का विज़न, 7 वर्ष की रणनीति और 3 वर्ष का कार्य एजेंडा रखा; पहला त्रिवर्षीय कार्य एजेंडा 2017–18 से 2019–20 तक का था।"},
  {"id":"eco-planning-budget-57","question":"Because of political instability at the Centre, the Eighth Plan could not begin in 1990, and the years 1990–92 were covered by:","options":["The Rolling Plan","Two Annual Plans","The Seventh Plan extended by two years","A Perspective Plan"],"answer":1,"explanation":"Annual Plans were run for 1990–91 and 1991–92, and the Eighth Plan began in April 1992.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"केंद्र में राजनीतिक अस्थिरता के कारण आठवीं योजना 1990 में शुरू नहीं हो सकी, और 1990–92 के वर्ष किससे पूरे किए गए?","optionsHi":["रोलिंग योजना","दो वार्षिक योजनाएँ","दो वर्ष बढ़ाई गई सातवीं योजना","एक परिप्रेक्ष्य योजना"],"explanationHi":"1990–91 और 1991–92 के लिए वार्षिक योजनाएँ चलाई गईं, और आठवीं योजना अप्रैल 1992 में शुरू हुई।"},
  {"id":"eco-planning-budget-58","question":"The part of the government's borrowing that is met by borrowing from the Reserve Bank of India is called the:","options":["Primary deficit","Revenue deficit","Monetised deficit","Effective revenue deficit"],"answer":2,"explanation":"Monetised deficit is the increase in the RBI's net credit to the government. It adds to reserve money and so is the most inflationary way to finance a deficit.","difficulty":"hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"सरकार की उधारी का वह भाग जो भारतीय रिज़र्व बैंक से उधार लेकर पूरा किया जाता है, क्या कहलाता है?","optionsHi":["प्राथमिक घाटा","राजस्व घाटा","मुद्रीकृत घाटा","प्रभावी राजस्व घाटा"],"explanationHi":"मुद्रीकृत घाटा सरकार को RBI के निवल ऋण में वृद्धि है। यह आरक्षित मुद्रा बढ़ाता है, इसलिए घाटे के वित्तपोषण का सबसे अधिक मुद्रास्फीतिकारी तरीका है।"},
  {"id":"eco-planning-budget-59","question":"Ad hoc Treasury Bills, through which the RBI automatically financed the government's deficit, were discontinued from:","options":["1 April 1991","1 April 1994","1 April 1997","1 April 2003"],"answer":2,"explanation":"Under a 1994 agreement between the Government and the RBI, ad hoc Treasury Bills ended from 1 April 1997 and were replaced by Ways and Means Advances.","difficulty":"hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"तदर्थ ट्रेज़री बिल, जिनके माध्यम से RBI स्वतः सरकार के घाटे का वित्तपोषण करता था, किस तिथि से बंद कर दिए गए?","optionsHi":["1 अप्रैल 1991","1 अप्रैल 1994","1 अप्रैल 1997","1 अप्रैल 2003"],"explanationHi":"सरकार और RBI के बीच 1994 के समझौते के तहत तदर्थ ट्रेज़री बिल 1 अप्रैल 1997 से समाप्त हो गए और उनकी जगह अर्थोपाय अग्रिम (Ways and Means Advances) आए।"},
  {"id":"eco-planning-budget-60","question":"The Union's tax revenue rises by 15% in a year in which nominal GDP rises by 10%. The tax buoyancy is:","options":["0.67","1.0","1.5","2.5"],"answer":2,"explanation":"Tax buoyancy = % change in tax revenue ÷ % change in GDP = 15 ÷ 10 = 1.5. A value above 1 means revenue grows faster than the economy.","difficulty":"hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"किसी वर्ष केंद्र का कर राजस्व 15% बढ़ता है जबकि सांकेतिक GDP 10% बढ़ती है। कर उछाल (बॉयन्सी) कितनी है?","optionsHi":["0.67","1.0","1.5","2.5"],"explanationHi":"कर उछाल = कर राजस्व में % परिवर्तन ÷ GDP में % परिवर्तन = 15 ÷ 10 = 1.5। 1 से अधिक मान का अर्थ है कि राजस्व अर्थव्यवस्था से तेज़ बढ़ रहा है।"},
  {"id":"eco-planning-budget-61","question":"A government's fiscal deficit is 5% of GDP and its primary deficit is 1.5% of GDP. If GDP is ₹300 lakh crore, its interest payments are:","options":["₹4.5 lakh crore","₹10.5 lakh crore","₹15 lakh crore","₹19.5 lakh crore"],"answer":1,"explanation":"Interest payments = fiscal deficit − primary deficit = 5% − 1.5% = 3.5% of GDP. 3.5% of ₹300 lakh crore = ₹10.5 lakh crore.","difficulty":"hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"किसी सरकार का राजकोषीय घाटा GDP का 5% और प्राथमिक घाटा GDP का 1.5% है। यदि GDP ₹300 लाख करोड़ है, तो उसके ब्याज भुगतान कितने हैं?","optionsHi":["₹4.5 लाख करोड़","₹10.5 लाख करोड़","₹15 लाख करोड़","₹19.5 लाख करोड़"],"explanationHi":"ब्याज भुगतान = राजकोषीय घाटा − प्राथमिक घाटा = 5% − 1.5% = GDP का 3.5%। ₹300 लाख करोड़ का 3.5% = ₹10.5 लाख करोड़।"},
  {"id":"eco-planning-budget-62","question":"A tax levied on an activity that harms others, such as a carbon tax on pollution, in order to correct that harm, is called a:","options":["Progressive tax","Pigouvian tax","Proportional tax","Windfall tax"],"answer":1,"explanation":"A Pigouvian tax, named after A. C. Pigou, makes the polluter bear the external cost of a negative externality.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"दूसरों को हानि पहुँचाने वाली गतिविधि पर, जैसे प्रदूषण पर कार्बन कर, उस हानि को सुधारने के उद्देश्य से लगाया गया कर क्या कहलाता है?","optionsHi":["प्रगामी कर","पिगूवियन कर","समानुपातिक कर","आकस्मिक लाभ कर"],"explanationHi":"ए. सी. पिगू के नाम पर पिगूवियन कर, ऋणात्मक बाह्यता की बाह्य लागत प्रदूषक से वहन कराता है।"},
  {"id":"eco-planning-budget-63","question":"Revenue that the government gives up through tax exemptions, deductions and incentives is shown in the Budget documents as the:","options":["Receipt Budget","Medium-Term Fiscal Policy Statement","Statement on Guarantees given by the Government","Statement of Revenue Impact of Tax Incentives"],"answer":1,"explanation":"This statement, often called the tax expenditure statement, estimates revenue foregone because of concessions in direct and indirect taxes. The guarantees statement lists contingent liabilities, not revenue given up.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"कर छूट, कटौतियों और प्रोत्साहनों के कारण सरकार जो राजस्व छोड़ देती है, वह बजट दस्तावेज़ों में किस रूप में दर्शाया जाता है?","optionsHi":["प्राप्ति बजट","मध्यम अवधि राजकोषीय नीति विवरण","सरकार द्वारा दी गई प्रत्याभूतियों का विवरण","कर प्रोत्साहनों के राजस्व प्रभाव का विवरण"],"explanationHi":"इस विवरण को प्रायः कर व्यय विवरण कहा जाता है; यह प्रत्यक्ष और अप्रत्यक्ष करों में रियायतों के कारण छोड़े गए राजस्व का अनुमान देता है। प्रत्याभूति विवरण आकस्मिक देनदारियाँ बताता है, छोड़ा गया राजस्व नहीं।"},
  {"id":"eco-planning-budget-64","question":"The 80th Amendment (2000) changed the sharing of Union taxes with the States by:","options":["Assigning all income tax proceeds wholly to the States","Making all Union taxes part of a pool shared with the States","Replacing the Finance Commission with a permanent fiscal council","Creating the GST Council to share indirect taxes"],"answer":1,"explanation":"On the Tenth Finance Commission's ‘alternative scheme of devolution’, the 80th Amendment amended Article 270 so that all Union taxes (except cesses and surcharges) form a divisible pool, instead of only income tax and Union excise duties being shared.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"80वें संशोधन (2000) ने केंद्रीय करों के राज्यों के साथ बँटवारे में क्या परिवर्तन किया?","optionsHi":["आयकर की संपूर्ण आय राज्यों को सौंप दी","सभी केंद्रीय करों को राज्यों के साथ साझा होने वाले पूल का भाग बनाया","वित्त आयोग के स्थान पर स्थायी राजकोषीय परिषद बनाई","अप्रत्यक्ष करों के बँटवारे हेतु GST परिषद बनाई"],"explanationHi":"दसवें वित्त आयोग की ‘वैकल्पिक हस्तांतरण योजना’ के आधार पर 80वें संशोधन ने अनुच्छेद 270 में संशोधन किया, ताकि केवल आयकर और केंद्रीय उत्पाद शुल्क के बजाय सभी केंद्रीय कर (उपकर और अधिभार को छोड़कर) विभाज्य पूल बनें।"},
  {"id":"eco-planning-budget-65","question":"Under the GST rate rationalisation that took effect on 22 September 2025, most goods and services fall into two main slabs of:","options":["5% and 12%","5% and 18%","12% and 18%","12% and 28%"],"answer":1,"explanation":"The GST Council in September 2025 merged the 12% and 28% slabs, leaving 5% and 18% as the main rates, with a special 40% rate for a small set of sin and luxury goods.","difficulty":"hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"22 सितंबर 2025 से लागू GST दर युक्तिकरण के अंतर्गत अधिकांश वस्तुएँ और सेवाएँ किन दो मुख्य स्लैब में आती हैं?","optionsHi":["5% और 12%","5% और 18%","12% और 18%","12% और 28%"],"explanationHi":"सितंबर 2025 में GST परिषद ने 12% और 28% स्लैब को मिला दिया, जिससे 5% और 18% मुख्य दरें रह गईं, तथा कुछ हानिकारक और विलासिता वस्तुओं के लिए विशेष 40% दर रखी गई।"},
  {"id":"eco-planning-budget-66","question":"The Aspirational Districts Programme, run by NITI Aayog to improve the most backward districts on health, education, agriculture and other indicators, was launched in:","options":["2015","2018","2020","2023"],"answer":1,"explanation":"It was launched in January 2018 and covers over 100 districts ranked on real-time indicators. An Aspirational Blocks Programme followed in 2023.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"आकांक्षी जिला कार्यक्रम, जिसे नीति आयोग स्वास्थ्य, शिक्षा, कृषि और अन्य संकेतकों पर सबसे पिछड़े जिलों को सुधारने के लिए चलाता है, किस वर्ष शुरू हुआ?","optionsHi":["2015","2018","2020","2023"],"explanationHi":"यह जनवरी 2018 में शुरू हुआ और 100 से अधिक जिलों को वास्तविक समय के संकेतकों पर रैंक करता है। 2023 में आकांक्षी ब्लॉक कार्यक्रम आया।"},
  {"id":"eco-planning-budget-67","question":"The Government of India first issued Sovereign Green Bonds, to finance green infrastructure projects, in:","options":["2015–16","2019–20","2022–23","2024–25"],"answer":2,"explanation":"The first Sovereign Green Bonds were auctioned by the RBI in January 2023, in the financial year 2022–23, following an announcement in the 2022–23 Budget.","difficulty":"hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"भारत सरकार ने हरित अवसंरचना परियोजनाओं के वित्तपोषण हेतु संप्रभु हरित बॉन्ड पहली बार किस वर्ष जारी किए?","optionsHi":["2015–16","2019–20","2022–23","2024–25"],"explanationHi":"पहले संप्रभु हरित बॉन्ड की नीलामी RBI ने जनवरी 2023 में, यानी वित्त वर्ष 2022–23 में की, जिसकी घोषणा 2022–23 के बजट में हुई थी।"},
  {"id":"eco-planning-budget-68","question":"Match the plan with its author: A. Bombay Plan (1944) B. Gandhian Plan (1944) C. People's Plan (1945) D. Sarvodaya Plan (1950) — 1. Jayaprakash Narayan 2. M. N. Roy 3. S. N. Agarwal 4. A group of leading industrialists","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1"],"answer":0,"explanation":"The Bombay Plan was drawn up by industrialists such as J. R. D. Tata and G. D. Birla; the Gandhian Plan by S. N. Agarwal; the People's Plan by M. N. Roy; and the Sarvodaya Plan by Jayaprakash Narayan.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"योजना का उसके रचयिता से मिलान कीजिए: A. बॉम्बे योजना (1944) B. गांधीवादी योजना (1944) C. जन योजना (1945) D. सर्वोदय योजना (1950) — 1. जयप्रकाश नारायण 2. एम. एन. रॉय 3. एस. एन. अग्रवाल 4. प्रमुख उद्योगपतियों का एक समूह","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1"],"explanationHi":"बॉम्बे योजना जे. आर. डी. टाटा और जी. डी. बिड़ला जैसे उद्योगपतियों ने बनाई; गांधीवादी योजना एस. एन. अग्रवाल ने; जन योजना एम. एन. रॉय ने; और सर्वोदय योजना जयप्रकाश नारायण ने।"},
  {"id":"eco-planning-budget-69","question":"Match the type of grant with its description: A. Supplementary grant B. Excess grant C. Token grant D. Exceptional grant — 1. Granted for a special purpose that is not part of the current service of any year 2. A nominal sum voted for a new service when funds can be found by reappropriation 3. Money spent beyond the grant for a year, regularised after the Public Accounts Committee examines it 4. An extra amount needed in the current year for a service already provided for","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Supplementary and excess grants are under Article 115; exceptional grants and votes of credit under Article 116. A token grant is used to open a new service through reappropriation.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अनुदान के प्रकार का उसके विवरण से मिलान कीजिए: A. अनुपूरक अनुदान B. आधिक्य अनुदान C. सांकेतिक अनुदान D. अपवादानुदान — 1. किसी विशेष प्रयोजन के लिए दिया गया, जो किसी वर्ष की चालू सेवा का भाग नहीं है 2. नई सेवा के लिए मतदान से स्वीकृत नाममात्र की राशि, जब धन पुनर्विनियोजन से मिल सके 3. किसी वर्ष के अनुदान से अधिक खर्च की गई राशि, जिसे लोक लेखा समिति की जाँच के बाद नियमित किया जाता है 4. पहले से व्यवस्थित सेवा के लिए चालू वर्ष में आवश्यक अतिरिक्त राशि","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"अनुपूरक और आधिक्य अनुदान अनुच्छेद 115 के अंतर्गत हैं; अपवादानुदान और प्रत्ययानुदान अनुच्छेद 116 के अंतर्गत। सांकेतिक अनुदान का प्रयोग पुनर्विनियोजन के माध्यम से नई सेवा शुरू करने के लिए होता है।"},
  {"id":"eco-planning-budget-70","question":"How many of these statements about cut motions are correct? I. A ‘disapproval of policy cut’ seeks to reduce a demand to ₹1. II. An ‘economy cut’ seeks to reduce a demand by a specified amount. III. A ‘token cut’ seeks to reduce a demand by ₹100. IV. Cut motions on demands for grants can be moved only in the Lok Sabha.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: a policy cut reduces the demand to ₹1, an economy cut by a specified amount, a token cut by ₹100, and since demands are voted only by the Lok Sabha (Article 113), cut motions are moved only there.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कटौती प्रस्तावों के बारे में इनमें से कितने कथन सही हैं? I. ‘नीति अनुमोदन-विरोधी कटौती’ किसी मांग को घटाकर ₹1 करना चाहती है। II. ‘मितव्ययिता कटौती’ किसी मांग को एक निर्दिष्ट राशि से घटाना चाहती है। III. ‘सांकेतिक कटौती’ किसी मांग को ₹100 से घटाना चाहती है। IV. अनुदान मांगों पर कटौती प्रस्ताव केवल लोकसभा में लाए जा सकते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: नीति कटौती मांग को ₹1 तक घटाती है, मितव्ययिता कटौती निर्दिष्ट राशि से, सांकेतिक कटौती ₹100 से, और चूँकि मांगों पर मतदान केवल लोकसभा करती है (अनुच्छेद 113), कटौती प्रस्ताव केवल वहीं लाए जाते हैं।"},
  {"id":"eco-planning-budget-71","question":"Assertion (A): A government can have a negative primary deficit (a primary surplus) while still running a fiscal deficit. Reason (R): Primary deficit equals fiscal deficit minus interest payments.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: if interest payments exceed the fiscal deficit, the primary balance is in surplus even though the government is still borrowing.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"अभिकथन (A): कोई सरकार राजकोषीय घाटा चलाते हुए भी ऋणात्मक प्राथमिक घाटा (प्राथमिक अधिशेष) रख सकती है। कारण (R): प्राथमिक घाटा राजकोषीय घाटे में से ब्याज भुगतान घटाने के बराबर होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: यदि ब्याज भुगतान राजकोषीय घाटे से अधिक हों, तो सरकार के उधार लेते रहने पर भी प्राथमिक शेष अधिशेष में होता है।"},
  {"id":"eco-planning-budget-72","question":"Arrange in time order: 1. Minimum Needs Programme begins 2. Twenty Point Programme launched 3. Start of the Plan Holiday 4. Rolling Plan introduced","options":["3-2-1-4","3-1-2-4","3-1-4-2","1-3-2-4"],"answer":1,"explanation":"Plan Holiday (1966), Minimum Needs Programme (1974, Fifth Plan), Twenty Point Programme (1975), Rolling Plan (1978).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कालक्रम से व्यवस्थित कीजिए: 1. न्यूनतम आवश्यकता कार्यक्रम शुरू हुआ 2. बीस सूत्रीय कार्यक्रम शुरू हुआ 3. योजना अवकाश का आरंभ 4. रोलिंग योजना लागू हुई","optionsHi":["3-2-1-4","3-1-2-4","3-1-4-2","1-3-2-4"],"explanationHi":"योजना अवकाश (1966), न्यूनतम आवश्यकता कार्यक्रम (1974, पाँचवीं योजना), बीस सूत्रीय कार्यक्रम (1975), रोलिंग योजना (1978)।"},
  {"id":"eco-planning-budget-73","question":"How many of these statements about tax devolution under the Fifteenth Finance Commission are correct? I. It fixed the States' share of the divisible pool at 41% for 2021–26. II. Cesses and surcharges are outside the divisible pool. III. ‘Demographic performance’ was one of its criteria for sharing among States. IV. The share was cut from 42% partly because Jammu and Kashmir had become a Union Territory.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The 1 percentage point reduction roughly matched the share that would have gone to Jammu and Kashmir as a State.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पंद्रहवें वित्त आयोग के अंतर्गत कर हस्तांतरण के बारे में इनमें से कितने कथन सही हैं? I. इसने 2021–26 के लिए विभाज्य पूल में राज्यों का हिस्सा 41% तय किया। II. उपकर और अधिभार विभाज्य पूल से बाहर हैं। III. राज्यों के बीच बँटवारे के इसके मानदंडों में ‘जनसांख्यिकीय निष्पादन’ भी शामिल था। IV. हिस्सा 42% से घटाया गया, आंशिक रूप से इसलिए कि जम्मू और कश्मीर केंद्र शासित प्रदेश बन गया था।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। 1 प्रतिशत अंक की कमी लगभग उस हिस्से के बराबर थी जो जम्मू और कश्मीर को राज्य के रूप में मिलता।"},
  {"id":"eco-planning-budget-74","question":"Match the type of tax with its description: A. Progressive B. Proportional C. Regressive D. Degressive — 1. The rate rises with income, but at a slower pace beyond a point 2. Takes a larger share of a poor person's income than a rich person's 3. The same rate at every level of income 4. The rate rises as income rises","options":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1"],"answer":0,"explanation":"A progressive tax's rate rises with income, a proportional tax has one rate, a regressive tax weighs more on the poor, and a degressive tax is progressive only up to a point.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"कर के प्रकार का उसके विवरण से मिलान कीजिए: A. प्रगामी B. समानुपातिक C. प्रतिगामी D. अवरोही (डिग्रेसिव) — 1. दर आय के साथ बढ़ती है, पर एक सीमा के बाद धीमी गति से 2. गरीब की आय का अमीर की आय से बड़ा हिस्सा लेता है 3. आय के हर स्तर पर समान दर 4. आय बढ़ने पर दर बढ़ती है","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1"],"explanationHi":"प्रगामी कर की दर आय के साथ बढ़ती है, समानुपातिक कर की एक ही दर होती है, प्रतिगामी कर गरीबों पर अधिक भारी पड़ता है, और अवरोही कर एक सीमा तक ही प्रगामी होता है।"},
  {"id":"eco-planning-budget-75","question":"Revenue receipts are ₹25 lakh crore, revenue expenditure ₹30 lakh crore, capital expenditure ₹10 lakh crore and non-debt capital receipts ₹2 lakh crore. Roughly what share of the government's borrowing goes to meet the revenue deficit?","options":["25%","38.5%","50%","61.5%"],"answer":1,"explanation":"Revenue deficit = 30 − 25 = 5. Fiscal deficit = (30 + 10) − (25 + 2) = 13. Share = 5 ÷ 13 ≈ 38.5%, meaning over a third of borrowing funds current spending rather than assets.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"राजस्व प्राप्तियाँ ₹25 लाख करोड़, राजस्व व्यय ₹30 लाख करोड़, पूंजीगत व्यय ₹10 लाख करोड़ और गैर-ऋण पूंजीगत प्राप्तियाँ ₹2 लाख करोड़ हैं। सरकार की उधारी का लगभग कितना हिस्सा राजस्व घाटे की पूर्ति में जाता है?","optionsHi":["25%","38.5%","50%","61.5%"],"explanationHi":"राजस्व घाटा = 30 − 25 = 5। राजकोषीय घाटा = (30 + 10) − (25 + 2) = 13। हिस्सा = 5 ÷ 13 ≈ 38.5%, अर्थात् उधारी के एक-तिहाई से अधिक से परिसंपत्तियाँ नहीं, बल्कि चालू व्यय पूरा होता है।"},
  {"id":"eco-planning-budget-76","question":"How many of these statements about the Government of India's funds are correct? I. The Contingency Fund of India was created by a law of Parliament under Article 267. II. Money can be withdrawn from the Public Account without an appropriation by Parliament. III. All revenues, loans raised and loan repayments received by the Union go into the Consolidated Fund. IV. Charged expenditure can be discussed in Parliament but is not put to the vote.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct (Articles 267, 266(2), 266(1) and 113(1)).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"भारत सरकार की निधियों के बारे में इनमें से कितने कथन सही हैं? I. भारत की आकस्मिकता निधि अनुच्छेद 267 के अंतर्गत संसद के कानून द्वारा बनाई गई। II. संसद के विनियोग के बिना लोक लेखा से धन निकाला जा सकता है। III. संघ को प्राप्त सभी राजस्व, जुटाए गए ऋण और ऋण वापसियाँ संचित निधि में जाती हैं। IV. भारित व्यय पर संसद में चर्चा हो सकती है, पर उस पर मतदान नहीं होता।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं (अनुच्छेद 267, 266(2), 266(1) और 113(1))।"},
  {"id":"eco-planning-budget-77","question":"Assertion (A): The Rajya Sabha does not vote on the demands for grants. Reason (R): Article 113 provides that estimates of expenditure not charged on the Consolidated Fund are submitted to the Lok Sabha in the form of demands for grants.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. The Rajya Sabha may discuss the Budget but has no power to vote on the demands.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): राज्यसभा अनुदान मांगों पर मतदान नहीं करती। कारण (R): अनुच्छेद 113 के अनुसार संचित निधि पर भारित न होने वाले व्यय के प्राक्कलन अनुदान मांगों के रूप में लोकसभा को प्रस्तुत किए जाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है। राज्यसभा बजट पर चर्चा कर सकती है, पर मांगों पर मतदान की शक्ति उसके पास नहीं है।"},
  {"id":"eco-planning-budget-78","question":"Which of these is NOT a revenue receipt of the Union Government?","options":["Dividends from public sector enterprises","Interest received on loans given to States","Recovery of loans given to States","Corporation tax"],"answer":2,"explanation":"Recovery of loans reduces the government's assets, so it is a non-debt capital receipt. Interest and dividends are non-tax revenue, and corporation tax is tax revenue.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"इनमें से कौन-सी केंद्र सरकार की राजस्व प्राप्ति नहीं है?","optionsHi":["सार्वजनिक क्षेत्र के उद्यमों से लाभांश","राज्यों को दिए गए ऋणों पर प्राप्त ब्याज","राज्यों को दिए गए ऋणों की वसूली","निगम कर"],"explanationHi":"ऋणों की वसूली सरकार की परिसंपत्तियाँ घटाती है, इसलिए यह गैर-ऋण पूंजीगत प्राप्ति है। ब्याज और लाभांश गैर-कर राजस्व हैं, और निगम कर कर राजस्व है।"},
  {"id":"eco-planning-budget-79","question":"Match the committee or formula with its subject: A. Mahalanobis Committee (1960) B. Gadgil formula (1969) C. Lakdawala Expert Group (1993) D. Tendulkar Committee (2009) — 1. A new poverty line based on a wider consumption basket 2. Estimating poverty using State-specific price indices 3. Sharing central plan assistance among States 4. Distribution of income and levels of living","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"The Mahalanobis Committee studied income distribution, the Gadgil formula allocated central plan assistance from the Fourth Plan, Lakdawala used State-specific poverty lines, and Tendulkar revised the poverty line in 2009.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"समिति या सूत्र का उसके विषय से मिलान कीजिए: A. महालनोबिस समिति (1960) B. गाडगिल सूत्र (1969) C. लकड़ावाला विशेषज्ञ समूह (1993) D. तेंदुलकर समिति (2009) — 1. उपभोग की व्यापक टोकरी पर आधारित नई गरीबी रेखा 2. राज्य-विशिष्ट मूल्य सूचकांकों का उपयोग कर गरीबी का आकलन 3. राज्यों के बीच केंद्रीय योजना सहायता का बँटवारा 4. आय का वितरण और जीवन-स्तर","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"महालनोबिस समिति ने आय वितरण का अध्ययन किया, गाडगिल सूत्र ने चौथी योजना से केंद्रीय योजना सहायता आवंटित की, लकड़ावाला ने राज्य-विशिष्ट गरीबी रेखाओं का उपयोग किया, और तेंदुलकर ने 2009 में गरीबी रेखा संशोधित की।"},
  {"id":"eco-planning-budget-80","question":"Assertion (A): Raising indirect taxes tends to make the tax system more regressive. Reason (R): Indirect taxes are paid at the same rate on goods and services whatever the buyer's income.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: since the poor spend a larger share of their income on taxed consumption, a uniform indirect tax takes a larger share of their income.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"अभिकथन (A): अप्रत्यक्ष करों को बढ़ाने से कर प्रणाली अधिक प्रतिगामी होने लगती है। कारण (R): अप्रत्यक्ष कर वस्तुओं और सेवाओं पर क्रेता की आय चाहे जो हो, समान दर से चुकाए जाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: चूँकि गरीब अपनी आय का बड़ा हिस्सा कर-योग्य उपभोग पर खर्च करते हैं, समान अप्रत्यक्ष कर उनकी आय का बड़ा हिस्सा ले लेता है।"},
  {"id":"eco-planning-budget-81","question":"A government wants a fiscal deficit of 4.5% of GDP. Expected GDP is ₹320 lakh crore, revenue receipts ₹34 lakh crore and non-debt capital receipts ₹1 lakh crore. What is the most it can spend in total?","options":["₹48.4 lakh crore","₹49.4 lakh crore","₹50.4 lakh crore","₹14.4 lakh crore"],"answer":1,"explanation":"Allowed fiscal deficit = 4.5% × 320 = ₹14.4 lakh crore. Total expenditure = fiscal deficit + revenue receipts + non-debt capital receipts = 14.4 + 34 + 1 = ₹49.4 lakh crore.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"एक सरकार GDP का 4.5% राजकोषीय घाटा चाहती है। अनुमानित GDP ₹320 लाख करोड़, राजस्व प्राप्तियाँ ₹34 लाख करोड़ और गैर-ऋण पूंजीगत प्राप्तियाँ ₹1 लाख करोड़ हैं। वह कुल अधिकतम कितना खर्च कर सकती है?","optionsHi":["₹48.4 लाख करोड़","₹49.4 लाख करोड़","₹50.4 लाख करोड़","₹14.4 लाख करोड़"],"explanationHi":"अनुमत राजकोषीय घाटा = 4.5% × 320 = ₹14.4 लाख करोड़। कुल व्यय = राजकोषीय घाटा + राजस्व प्राप्तियाँ + गैर-ऋण पूंजीगत प्राप्तियाँ = 14.4 + 34 + 1 = ₹49.4 लाख करोड़।"},
  {"id":"eco-planning-budget-82","question":"Arrange in time order: 1. FRBM Act passed 2. GST introduced 3. Gender Budget Statement first presented 4. Planning Commission set up","options":["1-4-3-2","4-3-1-2","4-1-2-3","4-1-3-2"],"answer":3,"explanation":"Planning Commission (1950), FRBM Act (2003), first Gender Budget Statement (2005–06), GST (2017).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"कालक्रम से व्यवस्थित कीजिए: 1. FRBM अधिनियम पारित हुआ 2. GST लागू हुआ 3. लैंगिक बजट विवरण पहली बार प्रस्तुत हुआ 4. योजना आयोग की स्थापना हुई","optionsHi":["1-4-3-2","4-3-1-2","4-1-2-3","4-1-3-2"],"explanationHi":"योजना आयोग (1950), FRBM अधिनियम (2003), पहला लैंगिक बजट विवरण (2005–06), GST (2017)।"},
  {"id":"eco-planning-budget-83","question":"Assertion (A): Raising more money through market borrowings reduces the fiscal deficit. Reason (R): Market borrowings are capital receipts of the government.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A is false: borrowings are the very thing the fiscal deficit measures, so fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts) leaves them out. R is true: borrowings are debt-creating capital receipts.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"अभिकथन (A): बाज़ार से अधिक उधारी जुटाने से राजकोषीय घाटा घटता है। कारण (R): बाज़ार उधारी सरकार की पूंजीगत प्राप्तियाँ हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A असत्य है: उधारी वही है जिसे राजकोषीय घाटा मापता है, इसलिए राजकोषीय घाटा = कुल व्यय − (राजस्व प्राप्तियाँ + गैर-ऋण पूंजीगत प्राप्तियाँ) में इन्हें शामिल नहीं किया जाता। R सत्य है: उधारी ऋण सृजित करने वाली पूंजीगत प्राप्तियाँ हैं।"},
  {"id":"eco-planning-budget-84","question":"How many of these are classified as revenue expenditure in the Union Budget? I. Grants to States, even when used to create capital assets II. Interest payments on loans III. Defence capital outlay IV. Salaries of government employees","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are revenue expenditure: grants create no asset for the Union, and interest and salaries are current spending. Defence capital outlay is capital expenditure.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RBI Grade B","questionHi":"केंद्रीय बजट में इनमें से कितने राजस्व व्यय के रूप में वर्गीकृत हैं? I. राज्यों को अनुदान, भले ही उनसे पूंजीगत परिसंपत्तियाँ बनें II. ऋणों पर ब्याज भुगतान III. रक्षा पूंजीगत परिव्यय IV. सरकारी कर्मचारियों के वेतन","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV राजस्व व्यय हैं: अनुदान केंद्र के लिए कोई परिसंपत्ति नहीं बनाते, और ब्याज तथा वेतन चालू व्यय हैं। रक्षा पूंजीगत परिव्यय पूंजीगत व्यय है।"},
  {"id":"eco-planning-budget-85","question":"Assertion (A): Money advanced from the Contingency Fund of India for unforeseen expenditure is later made good from the Consolidated Fund once Parliament authorises the spending. Reason (R): Article 267 itself fixes the corpus of the Contingency Fund at ₹500 crore.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true: the Fund is recouped after Parliament approves the expenditure through a supplementary or excess grant. R is false: Article 267 only lets Parliament create the Fund by law; its corpus is set by that law and has been raised over time, to ₹30,000 crore in 2021.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): अप्रत्याशित व्यय के लिए भारत की आकस्मिकता निधि से दी गई राशि की पूर्ति बाद में, संसद द्वारा व्यय को अधिकृत किए जाने पर, संचित निधि से की जाती है। कारण (R): अनुच्छेद 267 स्वयं आकस्मिकता निधि का कोष ₹500 करोड़ निर्धारित करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A सत्य है: संसद द्वारा अनुपूरक या आधिक्य अनुदान के माध्यम से व्यय को स्वीकृत करने के बाद निधि की भरपाई की जाती है। R असत्य है: अनुच्छेद 267 केवल संसद को कानून द्वारा निधि बनाने की अनुमति देता है; उसका कोष उसी कानून से तय होता है और समय के साथ बढ़ाया गया है, 2021 में ₹30,000 करोड़ तक।"},
  {"id":"eco-planning-budget-86","question":"A budget in which the government's expenditure is greater than its receipts is called a:","options":["Surplus budget","Balanced budget","Deficit budget","Zero-based budget"],"answer":2,"explanation":"When spending exceeds receipts the gap must be met by borrowing or drawing on reserves, giving a deficit budget. A surplus budget has receipts above spending.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"जिस बजट में सरकार का व्यय उसकी प्राप्तियों से अधिक होता है, वह क्या कहलाता है?","optionsHi":["अधिशेष बजट","संतुलित बजट","घाटे का बजट","शून्य-आधारित बजट"],"explanationHi":"जब व्यय प्राप्तियों से अधिक होता है, तो अंतर की पूर्ति उधारी या भंडारों के उपयोग से करनी पड़ती है, जिससे घाटे का बजट बनता है। अधिशेष बजट में प्राप्तियाँ व्यय से अधिक होती हैं।"},
  {"id":"eco-planning-budget-87","question":"Money spent by the government on building roads, bridges and dams is classified as:","options":["Capital expenditure","Revenue expenditure","Transfer payment","Interest payment"],"answer":0,"explanation":"Capital expenditure creates assets or reduces liabilities. Salaries, subsidies and interest, which create no assets, are revenue expenditure.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"सरकार द्वारा सड़कों, पुलों और बाँधों के निर्माण पर खर्च किया गया धन किस रूप में वर्गीकृत होता है?","optionsHi":["पूंजीगत व्यय","राजस्व व्यय","अंतरण भुगतान","ब्याज भुगतान"],"explanationHi":"पूंजीगत व्यय परिसंपत्तियाँ बनाता है या देनदारियाँ घटाता है। वेतन, सब्सिडी और ब्याज, जो कोई परिसंपत्ति नहीं बनाते, राजस्व व्यय हैं।"},
  {"id":"eco-planning-budget-88","question":"A “vote on account” passed by the Lok Sabha allows the government to:","options":["Raise new taxes for the whole year without passing a Finance Bill","Withdraw funds for part of the year until the budget is passed","Spend from the Contingency Fund without Parliament's approval","Borrow abroad without any limit fixed by Parliament"],"answer":1,"explanation":"Under Article 116, a vote on account grants funds in advance, usually for a few months, so government can keep running while the full demands for grants are discussed.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"लोकसभा द्वारा पारित “लेखानुदान” सरकार को किसकी अनुमति देता है?","optionsHi":["वित्त विधेयक पारित किए बिना पूरे वर्ष के लिए नए कर लगाने की","बजट पारित होने तक वर्ष के एक भाग के लिए धन निकालने की","संसद की स्वीकृति के बिना आकस्मिकता निधि से खर्च करने की","संसद द्वारा निर्धारित किसी सीमा के बिना विदेश से उधार लेने की"],"explanationHi":"अनुच्छेद 116 के अंतर्गत लेखानुदान अग्रिम रूप से, प्रायः कुछ महीनों के लिए, धन उपलब्ध कराता है ताकि पूर्ण अनुदान मांगों पर चर्चा होने तक सरकार का कामकाज चलता रहे।"},
  {"id":"eco-planning-budget-89","question":"In zero-based budgeting:","options":["The budget must be balanced each year with a zero deficit","Each item is set at last year's level plus an inflation allowance","Only capital spending is financed by borrowing, never revenue spending","Every item must be justified afresh each year, ignoring past allocations"],"answer":3,"explanation":"Zero-based budgeting starts each programme from zero, so it must prove its need. Incremental budgeting, by contrast, simply adds to the previous year's figure.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"शून्य-आधारित बजटिंग में:","optionsHi":["हर वर्ष बजट शून्य घाटे के साथ संतुलित होना चाहिए","हर मद पिछले वर्ष के स्तर में मुद्रास्फीति भत्ता जोड़कर तय होती है","केवल पूंजीगत व्यय उधारी से वित्तपोषित होता है, राजस्व व्यय कभी नहीं","पिछले आवंटनों की उपेक्षा करते हुए हर मद का हर वर्ष नए सिरे से औचित्य सिद्ध करना होता है"],"explanationHi":"शून्य-आधारित बजटिंग में हर कार्यक्रम शून्य से शुरू होता है, इसलिए उसे अपनी आवश्यकता सिद्ध करनी पड़ती है। इसके विपरीत वृद्धिशील बजटिंग में पिछले वर्ष के आँकड़े में ही कुछ जोड़ दिया जाता है।"},
  {"id":"eco-planning-budget-90","question":"Money the government receives from selling part of its shares in public sector companies is a:","options":["Revenue receipt","Non-debt capital receipt","Debt-creating capital receipt","Tax receipt"],"answer":1,"explanation":"Disinvestment reduces the government's assets and creates no repayment obligation, so it is a non-debt capital receipt, like recovery of loans.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"सार्वजनिक क्षेत्र की कंपनियों में अपने कुछ शेयर बेचकर सरकार को जो धन मिलता है, वह है:","optionsHi":["राजस्व प्राप्ति","गैर-ऋण पूंजीगत प्राप्ति","ऋण सृजित करने वाली पूंजीगत प्राप्ति","कर प्राप्ति"],"explanationHi":"विनिवेश सरकार की परिसंपत्तियाँ घटाता है और कोई चुकौती दायित्व नहीं बनाता, इसलिए यह ऋण वसूली की तरह गैर-ऋण पूंजीगत प्राप्ति है।"},
  {"id":"eco-planning-budget-91","question":"During a recession, a counter-cyclical fiscal policy would typically involve:","options":["Raising taxes and cutting spending to cut the deficit","Raising the repo rate to curb inflation","Higher government spending and/or lower taxes","Selling forex reserves to support the rupee"],"answer":2,"explanation":"Fiscal policy leans against the cycle: it boosts demand in a slump and cools it in a boom. Changing the repo rate is monetary policy, decided by the RBI's MPC.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"मंदी के दौरान प्रति-चक्रीय राजकोषीय नीति में सामान्यतः क्या शामिल होगा?","optionsHi":["घाटा घटाने के लिए कर बढ़ाना और व्यय घटाना","मुद्रास्फीति रोकने के लिए रेपो दर बढ़ाना","सरकारी व्यय बढ़ाना और/या कर घटाना","रुपये को सहारा देने के लिए विदेशी मुद्रा भंडार बेचना"],"explanationHi":"राजकोषीय नीति चक्र के विपरीत चलती है: मंदी में मांग बढ़ाती है और तेज़ी में ठंडा करती है। रेपो दर बदलना मौद्रिक नीति है, जिसे RBI की MPC तय करती है।"},
  {"id":"eco-planning-budget-92","question":"In the Finance Commission's work, “horizontal devolution” refers to:","options":["The share of central taxes going to the states as a whole","Grants passed on by states to panchayats and towns","Borrowing limits set for each state by the Centre","Dividing the states' share among individual states"],"answer":3,"explanation":"Vertical devolution fixes how much of the divisible pool goes to all states together; horizontal devolution divides that share among states using criteria such as population, area and income distance.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"वित्त आयोग के कार्य में “क्षैतिज हस्तांतरण” का क्या अर्थ है?","optionsHi":["केंद्रीय करों का वह हिस्सा जो सभी राज्यों को मिलाकर जाता है","राज्यों द्वारा पंचायतों और नगरों को दिए गए अनुदान","केंद्र द्वारा प्रत्येक राज्य के लिए तय उधारी सीमाएँ","राज्यों के हिस्से को अलग-अलग राज्यों में बाँटना"],"explanationHi":"ऊर्ध्वाधर हस्तांतरण तय करता है कि विभाज्य पूल का कितना भाग सभी राज्यों को मिलाकर जाएगा; क्षैतिज हस्तांतरण उस हिस्से को जनसंख्या, क्षेत्रफल और आय-दूरी जैसे मानदंडों से राज्यों में बाँटता है।"},
  {"id":"eco-planning-budget-93","question":"Which of the following is NOT part of the divisible pool of central taxes shared with the states?","options":["Union cesses and surcharges","Corporation tax on company profits","Personal income tax on individuals","Central GST on intra-state supplies"],"answer":0,"explanation":"Under Article 270, cesses and surcharges stay with the Union, which is why states object when their share of central revenue rises. Corporation tax, income tax and CGST are shareable.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन राज्यों के साथ साझा किए जाने वाले केंद्रीय करों के विभाज्य पूल का भाग नहीं है?","optionsHi":["केंद्रीय उपकर और अधिभार","कंपनी के लाभ पर निगम कर","व्यक्तियों पर व्यक्तिगत आयकर","अंतः-राज्यीय आपूर्ति पर केंद्रीय GST"],"explanationHi":"अनुच्छेद 270 के अंतर्गत उपकर और अधिभार केंद्र के पास रहते हैं, इसीलिए केंद्रीय राजस्व में उनका हिस्सा बढ़ने पर राज्य आपत्ति करते हैं। निगम कर, आयकर और CGST साझा किए जा सकते हैं।"},
  {"id":"eco-planning-budget-94","question":"Statutory grants-in-aid to states in need of assistance, made on the recommendation of the Finance Commission, are provided under:","options":["Article 282","Article 275","Article 360","Article 112"],"answer":1,"explanation":"Article 275 grants are charged on the Consolidated Fund and follow Finance Commission advice. Article 282 allows discretionary grants for any public purpose.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"सहायता की आवश्यकता वाले राज्यों को वित्त आयोग की सिफारिश पर दिए जाने वाले सांविधिक सहायता अनुदान किस अनुच्छेद के अंतर्गत हैं?","optionsHi":["अनुच्छेद 282","अनुच्छेद 275","अनुच्छेद 360","अनुच्छेद 112"],"explanationHi":"अनुच्छेद 275 के अनुदान संचित निधि पर भारित होते हैं और वित्त आयोग की सलाह पर चलते हैं। अनुच्छेद 282 किसी भी लोक प्रयोजन के लिए विवेकाधीन अनुदान की अनुमति देता है।"},
  {"id":"eco-planning-budget-95","question":"The Public Accounts Committee of Parliament mainly examines:","options":["The budget estimates before they are voted","Tax bills referred by the Lok Sabha","CAG audit reports on government accounts","Appointments to public sector companies"],"answer":2,"explanation":"The PAC scrutinises how money already spent was used, based on the CAG's reports; by convention since 1967 its chairperson comes from the opposition. Budget estimates go to the Estimates Committee.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"संसद की लोक लेखा समिति मुख्य रूप से किसकी जाँच करती है?","optionsHi":["मतदान से पहले बजट प्राक्कलन","लोकसभा द्वारा भेजे गए कर विधेयक","सरकारी लेखों पर CAG की लेखा परीक्षा रिपोर्टें","सार्वजनिक क्षेत्र की कंपनियों में नियुक्तियाँ"],"explanationHi":"लोक लेखा समिति CAG की रिपोर्टों के आधार पर जाँचती है कि खर्च हो चुके धन का उपयोग कैसे हुआ; 1967 से परंपरा के अनुसार इसका अध्यक्ष विपक्ष से होता है। बजट प्राक्कलन प्राक्कलन समिति के पास जाते हैं।"},
  {"id":"eco-planning-budget-96","question":"All members of which financial committee of Parliament are drawn from the Lok Sabha alone?","options":["Estimates Committee","Public Accounts Committee","Committee on Public Undertakings","Business Advisory Committee of the Rajya Sabha"],"answer":0,"explanation":"The Estimates Committee has 30 members, all from the Lok Sabha. The PAC and the Committee on Public Undertakings include members of the Rajya Sabha too.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"संसद की किस वित्तीय समिति के सभी सदस्य केवल लोकसभा से लिए जाते हैं?","optionsHi":["प्राक्कलन समिति","लोक लेखा समिति","सार्वजनिक उपक्रम समिति","राज्यसभा की कार्य सलाहकार समिति"],"explanationHi":"प्राक्कलन समिति में 30 सदस्य होते हैं, सभी लोकसभा से। लोक लेखा समिति और सार्वजनिक उपक्रम समिति में राज्यसभा के सदस्य भी होते हैं।"},
  {"id":"eco-planning-budget-97","question":"In budget procedure, the “guillotine” refers to:","options":["Reducing a demand by a token ₹100 to voice a specific grievance","Rejecting the Finance Bill in the Rajya Sabha","Re-appropriating funds from one head of account to another","Voting on all remaining demands together without discussion"],"answer":3,"explanation":"Because time is limited, the Speaker applies the guillotine so that demands not yet discussed are voted together. The ₹100 reduction is a token cut motion.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"बजट प्रक्रिया में “गिलोटिन” से क्या तात्पर्य है?","optionsHi":["किसी विशेष शिकायत को उठाने के लिए मांग में सांकेतिक ₹100 की कटौती करना","राज्यसभा में वित्त विधेयक को अस्वीकार करना","धन को एक लेखा शीर्ष से दूसरे में पुनर्विनियोजित करना","शेष सभी मांगों पर बिना चर्चा के एक साथ मतदान कराना"],"explanationHi":"समय सीमित होने के कारण अध्यक्ष गिलोटिन लागू करते हैं, ताकि जिन मांगों पर चर्चा नहीं हुई उन पर एक साथ मतदान हो जाए। ₹100 की कटौती सांकेतिक कटौती प्रस्ताव है।"},
  {"id":"eco-planning-budget-98","question":"Which of the following is NOT a statement laid before Parliament under the FRBM framework?","options":["Medium-term Fiscal Policy Statement","Fiscal Policy Strategy Statement","Monetary Policy Statement","Macro-economic Framework Statement"],"answer":2,"explanation":"The FRBM Act requires fiscal statements from the government alongside the budget. Monetary policy statements are issued by the RBI and its Monetary Policy Committee, not under the FRBM Act.","difficulty":"hard","source":"UPSC Prelims · IBPS PO","questionHi":"निम्नलिखित में से कौन-सा FRBM ढाँचे के अंतर्गत संसद के समक्ष रखा जाने वाला विवरण नहीं है?","optionsHi":["मध्यम अवधि राजकोषीय नीति विवरण","राजकोषीय नीति रणनीति विवरण","मौद्रिक नीति विवरण","समष्टि-आर्थिक ढाँचा विवरण"],"explanationHi":"FRBM अधिनियम के अनुसार सरकार को बजट के साथ राजकोषीय विवरण देने होते हैं। मौद्रिक नीति विवरण RBI और उसकी मौद्रिक नीति समिति जारी करती है, FRBM अधिनियम के अंतर्गत नहीं।"},
  {"id":"eco-planning-budget-99","question":"How many of these statements are correct? I. No money can be withdrawn from the Consolidated Fund of India except under an appropriation made by law. II. No amendment can be moved to an Appropriation Bill that would change the amount of expenditure charged on the Consolidated Fund. III. The Finance Bill contains the government's tax proposals. IV. The Rajya Sabha can reject the Appropriation Bill.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct (Articles 114 and 266). The Appropriation Bill is a Money Bill, so the Rajya Sabha can only make recommendations within 14 days and cannot reject it; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. विधि द्वारा किए गए विनियोग के बिना भारत की संचित निधि से कोई धन नहीं निकाला जा सकता। II. विनियोग विधेयक में ऐसा कोई संशोधन नहीं लाया जा सकता जो संचित निधि पर भारित व्यय की राशि बदल दे। III. वित्त विधेयक में सरकार के कर प्रस्ताव होते हैं। IV. राज्यसभा विनियोग विधेयक को अस्वीकार कर सकती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं (अनुच्छेद 114 और 266)। विनियोग विधेयक धन विधेयक है, इसलिए राज्यसभा 14 दिन के भीतर केवल सिफारिशें कर सकती है और उसे अस्वीकार नहीं कर सकती; IV गलत है।"},
  {"id":"eco-planning-budget-100","question":"Match the fiscal term with its meaning. A. Pump priming  B. Fiscal consolidation  C. Crowding out  D. Fiscal drag; 1. Rising nominal incomes push taxpayers into higher brackets, raising tax take and dampening demand  2. Government borrowing raises interest rates and squeezes private investment  3. Steadily reducing deficits and debt  4. Government spending to restart a slack economy","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1"],"answer":0,"explanation":"Pump priming injects demand; consolidation is the FRBM-style path of lower deficits; crowding out is the cost of heavy borrowing; fiscal drag is an automatic tightening as incomes rise.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO","questionHi":"राजकोषीय शब्द का उसके अर्थ से मिलान कीजिए। A. पंप प्राइमिंग B. राजकोषीय समेकन C. भीड़-बाह्यकरण D. राजकोषीय ड्रैग; 1. बढ़ती सांकेतिक आय करदाताओं को ऊँचे कर वर्ग में पहुँचा देती है, जिससे कर संग्रह बढ़ता है और मांग घटती है 2. सरकारी उधारी ब्याज दरें बढ़ाती है और निजी निवेश को दबाती है 3. घाटे और ऋण को लगातार घटाना 4. सुस्त अर्थव्यवस्था को फिर चलाने के लिए सरकारी व्यय","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1"],"explanationHi":"पंप प्राइमिंग मांग का संचार करती है; समेकन घाटे घटाने का FRBM-शैली का मार्ग है; भीड़-बाह्यकरण भारी उधारी की कीमत है; राजकोषीय ड्रैग आय बढ़ने पर स्वतः होने वाला संकुचन है।"},
  {"id":"eco-planning-budget-101","question":"Assertion (A): The fiscal deficit can be reduced without cutting expenditure by raising more through disinvestment. Reason (R): Disinvestment proceeds are non-debt capital receipts, which are subtracted along with revenue receipts from total expenditure to obtain the fiscal deficit.","options":["A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts). More disinvestment shrinks the gap that must be borrowed, though critics call it selling the family silver to pay current bills.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): व्यय घटाए बिना भी विनिवेश से अधिक राशि जुटाकर राजकोषीय घाटा घटाया जा सकता है। कारण (R): विनिवेश की प्राप्तियाँ गैर-ऋण पूंजीगत प्राप्तियाँ हैं, जिन्हें राजस्व प्राप्तियों के साथ कुल व्यय में से घटाकर राजकोषीय घाटा निकाला जाता है।","optionsHi":["A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"राजकोषीय घाटा = कुल व्यय − (राजस्व प्राप्तियाँ + गैर-ऋण पूंजीगत प्राप्तियाँ)। अधिक विनिवेश उस अंतर को घटाता है जिसे उधार से पूरा करना है, हालाँकि आलोचक इसे चालू खर्च चुकाने के लिए पुश्तैनी संपत्ति बेचना कहते हैं।"},
  {"id":"eco-planning-budget-102","question":"A government's debt is 80% of GDP (GDP = 100). Next year nominal GDP grows by 10% and the government borrows an amount equal to 5% of this year's GDP. What is the new debt-to-GDP ratio, approximately?","options":["85%","77%","80%","75%"],"answer":1,"explanation":"Debt becomes 80 + 5 = 85 and GDP becomes 110, so the ratio is 85/110 ≈ 77.3%. Nominal growth faster than debt growth lets the ratio fall even with a deficit.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"किसी सरकार का ऋण GDP का 80% है (GDP = 100)। अगले वर्ष सांकेतिक GDP 10% बढ़ती है और सरकार इस वर्ष की GDP के 5% के बराबर उधार लेती है। नया ऋण-GDP अनुपात लगभग कितना है?","optionsHi":["85%","77%","80%","75%"],"explanationHi":"ऋण 80 + 5 = 85 हो जाता है और GDP 110, इसलिए अनुपात 85/110 ≈ 77.3% है। ऋण वृद्धि से तेज़ सांकेतिक वृद्धि घाटे के बावजूद अनुपात को गिरने देती है।"},
  {"id":"eco-planning-budget-103","question":"How many of these statements about the Finance Commission are correct? I. It is constituted by the President every ten years or earlier. II. It recommends how the net proceeds of shareable taxes are divided between the Union and the states. III. It suggests measures to augment states' Consolidated Funds to support panchayats and municipalities. IV. Its recommendations are binding on the Union Government.","options":["Only one","Only three","Only two","All four"],"answer":2,"explanation":"II and III are correct under Article 280. I is wrong: the President constitutes a Finance Commission every five years or earlier. IV is wrong: its recommendations are advisory, though by convention largely accepted.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"वित्त आयोग के बारे में इनमें से कितने कथन सही हैं? I. इसका गठन राष्ट्रपति द्वारा हर दस वर्ष में या उससे पहले किया जाता है। II. यह सिफारिश करता है कि साझा करों की निवल आय केंद्र और राज्यों के बीच कैसे बँटे। III. यह पंचायतों और नगरपालिकाओं की सहायता हेतु राज्यों की संचित निधि बढ़ाने के उपाय सुझाता है। IV. इसकी सिफारिशें केंद्र सरकार पर बाध्यकारी हैं।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"अनुच्छेद 280 के अंतर्गत II और III सही हैं। I गलत है: राष्ट्रपति हर पाँच वर्ष में या उससे पहले वित्त आयोग का गठन करते हैं। IV गलत है: इसकी सिफारिशें परामर्शी हैं, यद्यपि परंपरा से अधिकांशतः मान ली जाती हैं।"},
  {"id":"eco-planning-budget-104","question":"Arrange these themes or objectives in the order of the Five-Year Plans that adopted them: 1. Faster, more inclusive and sustainable growth  2. Growth with stability and progressive achievement of self-reliance  3. Growth with social justice and equality  4. Towards faster and more inclusive growth","options":["2-3-1-4","3-2-4-1","2-4-3-1","2-3-4-1"],"answer":3,"explanation":"The Fourth Plan (1969–74) sought growth with stability and self-reliance; the Ninth (1997–2002) growth with social justice and equality; the Eleventh (2007–12) faster and more inclusive growth; the Twelfth (2012–17) added “sustainable”.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन विषयों या उद्देश्यों को उन पंचवर्षीय योजनाओं के क्रम में व्यवस्थित कीजिए जिन्होंने इन्हें अपनाया: 1. तीव्र, अधिक समावेशी और सतत विकास  2. स्थिरता और आत्मनिर्भरता की प्रगतिशील प्राप्ति के साथ वृद्धि  3. सामाजिक न्याय और समानता के साथ वृद्धि  4. तीव्र एवं अधिक समावेशी विकास की ओर","optionsHi":["2-3-1-4","3-2-4-1","2-4-3-1","2-3-4-1"],"explanationHi":"चौथी योजना (1969–74) ने स्थिरता और आत्मनिर्भरता के साथ वृद्धि चाही; नौवीं (1997–2002) ने सामाजिक न्याय और समानता के साथ वृद्धि; ग्यारहवीं (2007–12) ने तीव्र और अधिक समावेशी विकास; बारहवीं (2012–17) ने “सतत” जोड़ा।"},
  {"id":"eco-planning-budget-105","question":"Assertion (A): A high revenue deficit is considered a sign of poor fiscal health. Reason (R): It means the government is borrowing to meet day-to-day expenses that do not create assets to service future debt.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Borrowing to pay salaries, subsidies and interest leaves future taxpayers with debt but no matching assets or income, which is why the FRBM framework targets eliminating the revenue deficit.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): उच्च राजस्व घाटा खराब राजकोषीय स्वास्थ्य का संकेत माना जाता है। कारण (R): इसका अर्थ है कि सरकार उन दैनिक खर्चों के लिए उधार ले रही है जो भविष्य के ऋण की सेवा हेतु परिसंपत्तियाँ नहीं बनाते।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"वेतन, सब्सिडी और ब्याज चुकाने के लिए उधार लेने से भावी करदाताओं पर ऋण का बोझ आता है पर उसके अनुरूप कोई परिसंपत्ति या आय नहीं होती, इसीलिए FRBM ढाँचा राजस्व घाटे को समाप्त करने का लक्ष्य रखता है।"},
  {"id":"eco-planning-budget-106","question":"How many of these statements about the division of taxing powers are correct? I. Corporation tax is levied by the Union and kept wholly by it, outside the divisible pool. II. Stamp duties on bills of exchange are levied by the Union but collected and kept by the states. III. Tax on agricultural income can be levied only by the states. IV. The Union can levy tax on the sale of alcoholic liquor for human consumption.","options":["Only one","Only two","All four","Only three"],"answer":1,"explanation":"II (Article 268) and III are correct. I is wrong: since the 80th Amendment all Union taxes, including corporation tax, form the divisible pool shared with states. IV is wrong: liquor for human consumption is taxed by the states.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कर लगाने की शक्तियों के विभाजन के बारे में इनमें से कितने कथन सही हैं? I. निगम कर संघ द्वारा लगाया जाता है और पूरी तरह उसी के पास रहता है, विभाज्य पूल से बाहर। II. विनिमय पत्रों पर स्टाम्प शुल्क संघ द्वारा लगाए जाते हैं पर राज्यों द्वारा वसूले और रखे जाते हैं। III. कृषि आय पर कर केवल राज्य लगा सकते हैं। IV. संघ मानव उपभोग हेतु मादक शराब की बिक्री पर कर लगा सकता है।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"II (अनुच्छेद 268) और III सही हैं। I गलत है: 80वें संशोधन के बाद निगम कर सहित सभी केंद्रीय कर राज्यों के साथ साझा होने वाले विभाज्य पूल का भाग हैं। IV गलत है: मानव उपभोग हेतु शराब पर कर राज्य लगाते हैं।"},
  {"id":"eco-planning-budget-107","question":"In a simple closed economy with a marginal propensity to consume of 0.75, the government raises its spending by ₹1,000 crore and also raises lump-sum taxes by ₹1,000 crore. Equilibrium income will rise by about:","options":["Zero, since the extra taxes cancel the extra spending","₹1,000 crore","₹4,000 crore","₹3,000 crore"],"answer":1,"explanation":"The spending multiplier is 1/(1 − 0.75) = 4 (+₹4,000 crore) and the tax multiplier −0.75/0.25 = −3 (−₹3,000 crore), a net rise of ₹1,000 crore: the balanced-budget multiplier is 1.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"एक सरल बंद अर्थव्यवस्था में, जहाँ सीमांत उपभोग प्रवृत्ति 0.75 है, सरकार अपना व्यय ₹1,000 करोड़ बढ़ाती है और एकमुश्त कर भी ₹1,000 करोड़ बढ़ाती है। संतुलन आय में लगभग कितनी वृद्धि होगी?","optionsHi":["शून्य, क्योंकि अतिरिक्त कर अतिरिक्त व्यय को निरस्त कर देते हैं","₹1,000 करोड़","₹4,000 करोड़","₹3,000 करोड़"],"explanationHi":"व्यय गुणक 1/(1 − 0.75) = 4 है (+₹4,000 करोड़) और कर गुणक −0.75/0.25 = −3 है (−₹3,000 करोड़), जिससे निवल वृद्धि ₹1,000 करोड़ होती है: संतुलित-बजट गुणक 1 होता है।"},
  {"id":"eco-planning-budget-108","question":"In a simple closed economy with a marginal propensity to consume of 0.8, a ₹100 crore cut in lump-sum taxes raises equilibrium income by about:","options":["₹500 crore","₹100 crore","₹400 crore","₹80 crore"],"answer":2,"explanation":"The tax multiplier is MPC/(1 − MPC) = 0.8/0.2 = 4, so income rises by ₹400 crore. It is smaller than the spending multiplier of 5 because households save part of any tax cut before it is spent.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"एक सरल बंद अर्थव्यवस्था में, जहाँ सीमांत उपभोग प्रवृत्ति 0.8 है, एकमुश्त करों में ₹100 करोड़ की कटौती से संतुलन आय में लगभग कितनी वृद्धि होती है?","optionsHi":["₹500 करोड़","₹100 करोड़","₹400 करोड़","₹80 करोड़"],"explanationHi":"कर गुणक = MPC/(1 − MPC) = 0.8/0.2 = 4, इसलिए आय ₹400 करोड़ बढ़ती है। यह व्यय गुणक 5 से छोटा है क्योंकि परिवार कर कटौती का कुछ भाग खर्च करने से पहले बचा लेते हैं।"},
  {"id":"eco-planning-budget-109","question":"Which of the following works as an 'automatic stabiliser' of the economy?","options":["A one-time stimulus package announced in the budget during a slump","A cut in the repo rate whenever growth slows down","A fixed yearly allocation for defence capital spending","Progressive income tax, which takes less as incomes fall"],"answer":3,"explanation":"Automatic stabilisers cushion the cycle without fresh decisions: falling incomes cut tax payments sharply and welfare payments rise. A stimulus package is discretionary fiscal policy, and the repo rate is a monetary tool.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"निम्नलिखित में से कौन अर्थव्यवस्था के 'स्वचालित स्थिरकारी' के रूप में काम करता है?","optionsHi":["मंदी के दौरान बजट में घोषित एकमुश्त प्रोत्साहन पैकेज","वृद्धि धीमी पड़ने पर रेपो दर में कटौती","रक्षा पूंजीगत व्यय के लिए निश्चित वार्षिक आवंटन","प्रगामी आयकर, जो आय घटने पर कम कर लेता है"],"explanationHi":"स्वचालित स्थिरकारी बिना नए निर्णयों के चक्र को सँभालते हैं: आय घटने पर कर भुगतान तेज़ी से घटता है और कल्याणकारी भुगतान बढ़ते हैं। प्रोत्साहन पैकेज विवेकाधीन राजकोषीय नीति है, और रेपो दर मौद्रिक उपकरण है।"},
  {"id":"eco-planning-budget-110","question":"A new excise duty is collected from manufacturers, but they raise their prices so that buyers bear most of it. In public-finance terms:","options":["the impact is on manufacturers, while the incidence falls mainly on consumers","the impact is on consumers, while the incidence falls on manufacturers","it becomes a direct tax, since manufacturers pay it to the State","both its impact and its incidence fall on the government"],"answer":0,"explanation":"Impact is on whoever first pays the tax to the government; incidence is on whoever finally bears the burden. Indirect taxes are those whose burden can be shifted, which is exactly what happened here.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"निर्माताओं से एक नया उत्पाद शुल्क वसूला जाता है, पर वे अपनी कीमतें बढ़ा देते हैं जिससे अधिकांश बोझ क्रेताओं पर पड़ता है। लोक वित्त की शब्दावली में:","optionsHi":["प्रभाव निर्माताओं पर है, जबकि घटना (इन्सिडेंस) मुख्यतः उपभोक्ताओं पर पड़ती है","प्रभाव उपभोक्ताओं पर है, जबकि घटना निर्माताओं पर पड़ती है","यह प्रत्यक्ष कर बन जाता है, क्योंकि निर्माता इसे राज्य को चुकाते हैं","इसका प्रभाव और घटना दोनों सरकार पर पड़ते हैं"],"explanationHi":"प्रभाव उस पर होता है जो सरकार को कर पहले चुकाता है; घटना उस पर जो अंततः बोझ वहन करता है। अप्रत्यक्ष कर वे हैं जिनका बोझ आगे खिसकाया जा सकता है, और यहाँ ठीक यही हुआ है।"},
  {"id":"eco-planning-budget-111","question":"Which statement correctly distinguishes tax buoyancy from tax elasticity?","options":["Buoyancy counts discretionary changes in rates and base; elasticity excludes them","Elasticity includes discretionary changes in tax rates, while buoyancy excludes them","Both measure revenue growth, but buoyancy uses nominal and elasticity real GDP","A buoyancy above 1 means that tax revenue is growing more slowly than GDP"],"answer":0,"explanation":"Elasticity captures the built-in response of the tax system to income growth; buoyancy also reflects new taxes, rate changes and better compliance. A buoyancy above 1 means revenue grows faster than GDP.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"कौन-सा कथन कर उछाल (बॉयन्सी) और कर लोच (इलास्टिसिटी) में सही अंतर बताता है?","optionsHi":["उछाल में दरों और आधार के विवेकाधीन परिवर्तन गिने जाते हैं; लोच में नहीं","लोच में कर दरों के विवेकाधीन परिवर्तन शामिल होते हैं, जबकि उछाल में नहीं","दोनों राजस्व वृद्धि मापते हैं, पर उछाल सांकेतिक और लोच वास्तविक GDP का प्रयोग करती है","1 से अधिक उछाल का अर्थ है कि कर राजस्व GDP से धीमी गति से बढ़ रहा है"],"explanationHi":"लोच कर प्रणाली की आय वृद्धि के प्रति अंतर्निहित प्रतिक्रिया दर्शाती है; उछाल में नए कर, दरों में परिवर्तन और बेहतर अनुपालन भी झलकते हैं। 1 से अधिक उछाल का अर्थ है कि राजस्व GDP से तेज़ बढ़ता है।"},
  {"id":"eco-planning-budget-112","question":"In the Harrod–Domar model, if the investment (savings) rate is 30% of GDP and the incremental capital–output ratio (ICOR) is 5, the growth rate of GDP is about:","options":["6%","16.7%","25%","1.5%"],"answer":0,"explanation":"Growth = savings rate ÷ ICOR = 30 ÷ 5 = 6%. A lower ICOR, i.e. more efficient use of capital, gives faster growth for the same investment; dividing ICOR by the rate (16.7%) inverts the formula.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"हैरोड–डोमर मॉडल में, यदि निवेश (बचत) दर GDP का 30% और वृद्धिशील पूंजी–उत्पाद अनुपात (ICOR) 5 है, तो GDP की वृद्धि दर लगभग कितनी है?","optionsHi":["6%","16.7%","25%","1.5%"],"explanationHi":"वृद्धि = बचत दर ÷ ICOR = 30 ÷ 5 = 6%। कम ICOR, यानी पूंजी का अधिक कुशल उपयोग, उसी निवेश पर तेज़ वृद्धि देता है; ICOR को दर से भाग देना (16.7%) सूत्र को उलट देना है।"},
  {"id":"eco-planning-budget-113","question":"Consider the following statements: I. No money can be withdrawn from the Consolidated Fund of India except under an appropriation made by law. II. No amendment may be proposed to an Appropriation Bill in either House that would vary the amount or change the destination of any grant made. III. The Appropriation Bill covers both the grants voted by the Lok Sabha and the expenditure charged on the Consolidated Fund. Which of the statements given above is/are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":3,"explanation":"All three follow Articles 114 and 266. Charged expenditure is not voted on, but it is still included in the Appropriation Bill so that withdrawals have legal authority.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: I. विधि द्वारा किए गए विनियोग के बिना भारत की संचित निधि से कोई धन नहीं निकाला जा सकता। II. विनियोग विधेयक में किसी भी सदन में ऐसा कोई संशोधन प्रस्तावित नहीं किया जा सकता जो किसी स्वीकृत अनुदान की राशि बदल दे या उसका गंतव्य बदल दे। III. विनियोग विधेयक में लोकसभा द्वारा मतदान से स्वीकृत अनुदान और संचित निधि पर भारित व्यय दोनों शामिल होते हैं। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल I","केवल I और II","केवल II और III","I, II और III"],"explanationHi":"तीनों अनुच्छेद 114 और 266 से निकलते हैं। भारित व्यय पर मतदान नहीं होता, फिर भी उसे विनियोग विधेयक में शामिल किया जाता है ताकि निकासी को कानूनी प्राधिकार मिले।"},
  {"id":"eco-planning-budget-114","question":"'Off-budget borrowing' by a government refers to:","options":["borrowing authorised by Parliament through a vote on account before the budget","loans given by the Union to the States, which are shown as capital spending","borrowing by public bodies, such as the FCI, for spending kept out of the fiscal deficit","external commercial borrowing by private companies, outside government accounts"],"answer":2,"explanation":"Shifting spending to agencies that borrow on their own books (for example FCI loans from the National Small Savings Fund) flatters the headline deficit while the liability ultimately rests with the government; this is why such borrowings are now disclosed separately.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किसी सरकार की 'ऑफ-बजट उधारी' से क्या तात्पर्य है?","optionsHi":["बजट से पहले लेखानुदान के माध्यम से संसद द्वारा अधिकृत उधारी","संघ द्वारा राज्यों को दिए गए ऋण, जो पूंजीगत व्यय के रूप में दिखाए जाते हैं","FCI जैसे सार्वजनिक निकायों द्वारा उस व्यय के लिए ली गई उधारी जो राजकोषीय घाटे से बाहर रखा जाता है","निजी कंपनियों की बाह्य वाणिज्यिक उधारी, जो सरकारी लेखों से बाहर होती है"],"explanationHi":"व्यय को ऐसी एजेंसियों पर डाल देना जो अपनी बही पर उधार लेती हैं (जैसे राष्ट्रीय लघु बचत निधि से FCI के ऋण) घोषित घाटे को अच्छा दिखाता है, जबकि देनदारी अंततः सरकार पर ही रहती है; इसीलिए ऐसी उधारी अब अलग से प्रकट की जाती है।"},
  {"id":"eco-planning-budget-115","question":"The 'structural' (cyclically adjusted) budget deficit is the deficit that would occur:","options":["if only capital expenditure financed by borrowing were counted","if output were at its potential, removing the cycle's effect on revenue and spending","if interest payments on past debt were excluded from spending","after adding off-budget borrowings of public bodies to the fiscal deficit"],"answer":1,"explanation":"In a slump revenues fall and some spending rises automatically, enlarging the actual deficit; the structural deficit strips this out to show the underlying fiscal stance. Excluding interest gives the primary deficit instead.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"'संरचनात्मक' (चक्रीय रूप से समायोजित) बजट घाटा वह घाटा है जो होता:","optionsHi":["यदि केवल उधारी से वित्तपोषित पूंजीगत व्यय गिना जाता","यदि उत्पादन अपनी संभावित सीमा पर होता, जिससे राजस्व और व्यय पर चक्र का प्रभाव हट जाता","यदि पिछले ऋण पर ब्याज भुगतान व्यय से बाहर रखे जाते","यदि सार्वजनिक निकायों की ऑफ-बजट उधारी राजकोषीय घाटे में जोड़ दी जाती"],"explanationHi":"मंदी में राजस्व घटता है और कुछ व्यय स्वतः बढ़ता है, जिससे वास्तविक घाटा बड़ा हो जाता है; संरचनात्मक घाटा इसे हटाकर अंतर्निहित राजकोषीय रुख दिखाता है। ब्याज को बाहर रखने से प्राथमिक घाटा मिलता है।"},
  {"id":"eco-planning-budget-116","question":"An 'inverted duty structure' under GST arises when:","options":["the output is taxed at a higher rate than its inputs, so tax is paid in cash","imported goods are taxed at a lower rate than exported goods","all goods in a chain are taxed at a single uniform rate","inputs are taxed at a higher rate than the output, so credit piles up unused"],"answer":3,"explanation":"If inputs carry, say, 18% and the product 5%, the credit cannot be fully set off, blocking working capital; refunds of such accumulated credit are allowed in specified cases.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"GST के अंतर्गत 'उलटी शुल्क संरचना' (इनवर्टेड ड्यूटी स्ट्रक्चर) तब उत्पन्न होती है जब:","optionsHi":["उत्पादन पर कर उसके इनपुट से ऊँची दर पर लगता है, इसलिए कर नकद चुकाना पड़ता है","आयातित वस्तुओं पर निर्यातित वस्तुओं से कम दर पर कर लगता है","एक शृंखला की सभी वस्तुओं पर एक समान दर से कर लगता है","इनपुट पर उत्पादन से ऊँची दर पर कर लगता है, जिससे क्रेडिट बिना उपयोग के जमा होता रहता है"],"explanationHi":"यदि इनपुट पर, मान लीजिए, 18% और उत्पाद पर 5% कर लगे, तो क्रेडिट पूरी तरह समायोजित नहीं हो पाता और कार्यशील पूंजी फँस जाती है; ऐसे जमा क्रेडिट की वापसी (रिफंड) निर्दिष्ट मामलों में अनुमत है।"},
  {"id":"eco-planning-budget-117","question":"In Indian fiscal federalism, 'vertical fiscal imbalance' refers to:","options":["differences in revenue-raising capacity and spending needs among the States","the gap between the Union's revenue and capital expenditure","the Union raising most revenue while the States bear most spending duties","the imbalance between direct and indirect taxes in total revenue"],"answer":2,"explanation":"Finance Commission tax devolution corrects this vertical gap; differences among States, the horizontal imbalance, are handled through the distribution formula and grants.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारतीय राजकोषीय संघवाद में 'ऊर्ध्वाधर राजकोषीय असंतुलन' से क्या तात्पर्य है?","optionsHi":["राज्यों के बीच राजस्व जुटाने की क्षमता और व्यय आवश्यकताओं में अंतर","संघ के राजस्व और पूंजीगत व्यय के बीच का अंतर","संघ द्वारा अधिकांश राजस्व जुटाना जबकि व्यय के अधिकांश दायित्व राज्यों पर होना","कुल राजस्व में प्रत्यक्ष और अप्रत्यक्ष करों का असंतुलन"],"explanationHi":"वित्त आयोग का कर हस्तांतरण इस ऊर्ध्वाधर अंतर को सुधारता है; राज्यों के बीच के अंतर, यानी क्षैतिज असंतुलन, को वितरण सूत्र और अनुदानों से संभाला जाता है।"},
  {"id":"eco-planning-budget-118","question":"Grants that the Union or a State may make for any public purpose, even one outside its own legislative competence, are provided for under:","options":["Article 275","Article 282","Article 280","Article 293"],"answer":1,"explanation":"Article 282 discretionary grants have funded many centrally sponsored schemes. Article 275 covers statutory grants-in-aid on Finance Commission advice, Article 280 the Finance Commission itself and Article 293 borrowing by States.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संघ या कोई राज्य किसी भी लोक प्रयोजन के लिए, यहाँ तक कि अपनी विधायी क्षमता से बाहर के प्रयोजन के लिए भी, जो अनुदान दे सकता है, उनका प्रावधान किस अनुच्छेद में है?","optionsHi":["अनुच्छेद 275","अनुच्छेद 282","अनुच्छेद 280","अनुच्छेद 293"],"explanationHi":"अनुच्छेद 282 के विवेकाधीन अनुदानों ने अनेक केंद्र प्रायोजित योजनाओं को वित्त दिया है। अनुच्छेद 275 वित्त आयोग की सलाह पर सांविधिक सहायता अनुदानों से, अनुच्छेद 280 स्वयं वित्त आयोग से और अनुच्छेद 293 राज्यों की उधारी से संबंधित है।"},
  {"id":"eco-planning-budget-119","question":"A tax of ₹2 on every litre of a fuel, regardless of its price, is an example of:","options":["an ad valorem duty","a direct tax","a specific duty","a progressive tax"],"answer":2,"explanation":"A specific duty is a fixed amount per unit; an ad valorem duty is a percentage of value, so its yield rises automatically with prices while a specific duty's does not.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"किसी ईंधन की कीमत चाहे जो हो, प्रत्येक लीटर पर ₹2 का कर किसका उदाहरण है?","optionsHi":["मूल्यानुसार शुल्क (एड वैलोरम)","प्रत्यक्ष कर","विशिष्ट शुल्क","प्रगामी कर"],"explanationHi":"विशिष्ट शुल्क प्रति इकाई निश्चित राशि होता है; मूल्यानुसार शुल्क मूल्य का प्रतिशत होता है, इसलिए कीमतें बढ़ने पर उसकी प्राप्ति स्वतः बढ़ती है जबकि विशिष्ट शुल्क की नहीं।"},
  {"id":"eco-planning-budget-120","question":"According to 'Ricardian equivalence', a debt-financed tax cut today has little effect on consumption because:","options":["government spending falls automatically to match the lost revenue","interest rates fall to zero, so saving yields nothing","the multiplier becomes very large in a liquidity trap","households expect higher future taxes to repay the debt and save the cut"],"answer":3,"explanation":"Forward-looking households treat government borrowing as deferred taxation, so total private saving rises to offset public dissaving. In practice, liquidity-constrained households weaken this result.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"'रिकार्डियन तुल्यता' के अनुसार, ऋण-वित्तपोषित वर्तमान कर कटौती का उपभोग पर बहुत कम प्रभाव पड़ता है क्योंकि:","optionsHi":["खोए राजस्व के अनुरूप सरकारी व्यय स्वतः घट जाता है","ब्याज दरें शून्य हो जाती हैं, इसलिए बचत से कुछ नहीं मिलता","तरलता जाल में गुणक बहुत बड़ा हो जाता है","परिवार ऋण चुकाने के लिए भावी ऊँचे करों की आशा करते हैं और कटौती की राशि बचा लेते हैं"],"explanationHi":"दूरदर्शी परिवार सरकारी उधारी को टाले गए कर के रूप में देखते हैं, इसलिए कुल निजी बचत सार्वजनिक ऋणात्मक बचत की भरपाई के लिए बढ़ जाती है। व्यवहार में तरलता-बाधित परिवार इस परिणाम को कमज़ोर कर देते हैं।"},
  {"id":"eco-planning-budget-121","question":"The 'golden rule' of fiscal policy says that, over the economic cycle, a government should:","options":["borrow only for investment and fund current spending from revenue","never borrow at all and run a balanced budget every year","borrow only to pay salaries, pensions and subsidies on time","keep its total debt fixed in rupee terms over the cycle"],"answer":0,"explanation":"Borrowing for assets that raise future output can pay for itself, while borrowing for consumption burdens future taxpayers; in Indian budget terms the rule amounts to eliminating the revenue deficit.","difficulty":"hard","source":"UPSC Prelims","questionHi":"राजकोषीय नीति का 'स्वर्णिम नियम' कहता है कि आर्थिक चक्र के दौरान सरकार को:","optionsHi":["केवल निवेश के लिए उधार लेना चाहिए और चालू व्यय राजस्व से चलाना चाहिए","कभी उधार नहीं लेना चाहिए और हर वर्ष बजट संतुलित रखना चाहिए","केवल वेतन, पेंशन और सब्सिडी समय पर चुकाने के लिए उधार लेना चाहिए","चक्र के दौरान अपना कुल ऋण रुपये के संदर्भ में स्थिर रखना चाहिए"],"explanationHi":"भावी उत्पादन बढ़ाने वाली परिसंपत्तियों के लिए उधार स्वयं अपना भुगतान कर सकता है, जबकि उपभोग के लिए उधार भावी करदाताओं पर बोझ डालता है; भारतीय बजट की शब्दावली में यह नियम राजस्व घाटा समाप्त करने के बराबर है।"},
  {"id":"eco-planning-budget-122","question":"If a government's primary deficit is zero in a year, its fiscal deficit equals its:","options":["revenue deficit","interest payments","capital expenditure","total expenditure"],"answer":1,"explanation":"Primary deficit = fiscal deficit − interest payments, so a zero primary deficit means the government borrows only to pay interest on past debt.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"यदि किसी वर्ष सरकार का प्राथमिक घाटा शून्य है, तो उसका राजकोषीय घाटा किसके बराबर होता है?","optionsHi":["राजस्व घाटा","ब्याज भुगतान","पूंजीगत व्यय","कुल व्यय"],"explanationHi":"प्राथमिक घाटा = राजकोषीय घाटा − ब्याज भुगतान, इसलिए शून्य प्राथमिक घाटे का अर्थ है कि सरकार केवल पिछले ऋण पर ब्याज चुकाने के लिए उधार लेती है।"},
  {"id":"eco-planning-budget-123","question":"A government’s debt is 60% of GDP. The nominal interest rate on its debt is 7% and nominal GDP grows at 11% a year. What primary balance keeps the debt-to-GDP ratio exactly constant?","options":["A primary surplus of about 2.2% of GDP","A primary deficit of about 2.2% of GDP","A primary deficit of about 2.4% of GDP","A primary surplus of about 2.4% of GDP"],"answer":1,"explanation":"The debt ratio is stable when the primary deficit equals d(g − r)/(1 + g) = 0.60 × 0.04 / 1.11 ≈ 2.16% of GDP. Because g > r, the government can run a primary deficit; 2.4% forgets to divide by (1 + g).","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"किसी सरकार का ऋण GDP का 60% है। उसके ऋण पर सांकेतिक ब्याज दर 7% है और सांकेतिक GDP प्रति वर्ष 11% बढ़ती है। ऋण-GDP अनुपात को ठीक स्थिर रखने वाला प्राथमिक शेष कौन-सा है?","optionsHi":["GDP का लगभग 2.2% का प्राथमिक अधिशेष","GDP का लगभग 2.2% का प्राथमिक घाटा","GDP का लगभग 2.4% का प्राथमिक घाटा","GDP का लगभग 2.4% का प्राथमिक अधिशेष"],"explanationHi":"ऋण अनुपात तब स्थिर रहता है जब प्राथमिक घाटा d(g − r)/(1 + g) = 0.60 × 0.04 / 1.11 ≈ GDP का 2.16% हो। चूँकि g > r, सरकार प्राथमिक घाटा चला सकती है; 2.4% में (1 + g) से भाग देना भूल जाया गया है।"},
  {"id":"eco-planning-budget-124","question":"Under the FRBM Act as amended in 2018, when the Centre invokes the ‘escape clause’ on grounds such as war, a national calamity or a collapse of agriculture, the fiscal deficit may exceed the target by at most:","options":["0.25% of GDP","1% of GDP","0.5% of GDP","1.5% of GDP"],"answer":2,"explanation":"The amended Act allows a deviation of up to 0.5% of GDP in a year on the specified grounds, and the Finance Minister must explain the reasons to Parliament. 0.25% is the minimum deficit cut required under the ‘buoyancy’ clause.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"2018 में संशोधित FRBM अधिनियम के अंतर्गत, जब केंद्र युद्ध, राष्ट्रीय आपदा या कृषि के पतन जैसे आधारों पर ‘निकासी खंड’ का प्रयोग करता है, तो राजकोषीय घाटा लक्ष्य से अधिकतम कितना अधिक हो सकता है?","optionsHi":["GDP का 0.25%","GDP का 1%","GDP का 0.5%","GDP का 1.5%"],"explanationHi":"संशोधित अधिनियम निर्दिष्ट आधारों पर एक वर्ष में GDP के 0.5% तक विचलन की अनुमति देता है, और वित्त मंत्री को संसद को कारण बताने होते हैं। 0.25% ‘उछाल’ (बॉयन्सी) खंड के अंतर्गत आवश्यक न्यूनतम घाटा कटौती है।"},
  {"id":"eco-planning-budget-125","question":"In the GST Council a decision needs at least three-fourths of the weighted votes of members present and voting; the Centre’s vote counts for one-third and all the States together for two-thirds. If every State is present and voting and the Centre supports a proposal, what minimum share of the States must also support it?","options":["75%","66.7%","50%","62.5%"],"answer":3,"explanation":"Needed: 1/3 + f × 2/3 ≥ 3/4, so f ≥ (5/12)/(2/3) = 5/8 = 62.5%. The trap is to apply 75% to the States alone, forgetting the Centre’s one-third already counts.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"GST परिषद में किसी निर्णय के लिए उपस्थित और मतदान करने वाले सदस्यों के भारित मतों का कम से कम तीन-चौथाई आवश्यक है; केंद्र का मत एक-तिहाई और सभी राज्यों का मिलाकर दो-तिहाई गिना जाता है। यदि सभी राज्य उपस्थित और मतदान कर रहे हों और केंद्र किसी प्रस्ताव का समर्थन करे, तो राज्यों का न्यूनतम कितना हिस्सा भी उसका समर्थन करे?","optionsHi":["75%","66.7%","50%","62.5%"],"explanationHi":"आवश्यक: 1/3 + f × 2/3 ≥ 3/4, इसलिए f ≥ (5/12)/(2/3) = 5/8 = 62.5%। जाल यह है कि राज्यों पर अकेले 75% लगा दिया जाए और केंद्र का एक-तिहाई पहले से गिना जाना भूल जाया जाए।"},
  {"id":"eco-planning-budget-126","question":"A rural roads scheme is to be judged by the rise in villages’ all-weather access to markets and health centres rather than by the kilometres of road laid. Which budgeting approach does this reflect?","options":["Line-item budgeting","Performance budgeting","Outcome budgeting","Zero-based budgeting"],"answer":2,"explanation":"Outcome budgeting measures the results that spending achieves for people; performance budgeting tracks activities and physical outputs such as kilometres built. Zero-based budgeting is about justifying each item afresh.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"एक ग्रामीण सड़क योजना का मूल्यांकन बनाई गई सड़क की किलोमीटर लंबाई के बजाय बाज़ारों और स्वास्थ्य केंद्रों तक गाँवों की सभी मौसम में पहुँच में वृद्धि से किया जाना है। यह किस बजट पद्धति को दर्शाता है?","optionsHi":["मदवार बजटिंग","निष्पादन बजटिंग","परिणाम बजटिंग","शून्य-आधारित बजटिंग"],"explanationHi":"परिणाम बजटिंग यह मापती है कि व्यय से लोगों को क्या परिणाम मिले; निष्पादन बजटिंग गतिविधियों और बनी सड़क की किलोमीटर जैसे भौतिक उत्पादों को मापती है। शून्य-आधारित बजटिंग हर मद का नए सिरे से औचित्य सिद्ध करने की पद्धति है।"},
  {"id":"eco-planning-budget-127","question":"Match the Article with its GST provision: A. Article 246A  B. Article 269A  C. Article 279A  D. Article 366(12A); 1. Defines ‘goods and services tax’  2. Constitutes the GST Council  3. Special power of Parliament and State legislatures to make laws on GST  4. Levy and collection of GST on inter-State supplies by the Union","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Article 246A gives the concurrent power to legislate on GST (with inter-State supply reserved for Parliament), 269A covers IGST on inter-State trade, 279A sets up the Council and 366(12A) defines GST. All came with the 101st Amendment, 2016.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"अनुच्छेद का उसके GST प्रावधान से मिलान कीजिए: A. अनुच्छेद 246A  B. अनुच्छेद 269A  C. अनुच्छेद 279A  D. अनुच्छेद 366(12A); 1. ‘वस्तु एवं सेवा कर’ को परिभाषित करता है  2. GST परिषद का गठन करता है  3. GST पर कानून बनाने की संसद और राज्य विधानमंडलों की विशेष शक्ति  4. संघ द्वारा अंतर-राज्यीय आपूर्ति पर GST का उद्ग्रहण और संग्रहण","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2"],"explanationHi":"अनुच्छेद 246A GST पर कानून बनाने की समवर्ती शक्ति देता है (अंतर-राज्यीय आपूर्ति संसद के लिए आरक्षित), 269A अंतर-राज्यीय व्यापार पर IGST से संबंधित है, 279A परिषद का गठन करता है और 366(12A) GST को परिभाषित करता है। ये सभी 2016 के 101वें संशोधन के साथ आए।"},
  {"id":"eco-planning-budget-128","question":"Under the Provisional Collection of Taxes Act, 1931, tax changes declared in the Finance Bill take effect immediately, but they lapse if the Bill is not enacted within:","options":["14 days","60 days","90 days","75 days"],"answer":3,"explanation":"The Act lets declared provisions operate at once, to stop people dodging a new levy, but only for 75 days unless the Finance Bill becomes law earlier. 14 days is the Rajya Sabha’s limit on a Money Bill.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"कर संग्रहण अधिनियम (Provisional Collection of Taxes Act), 1931 के अंतर्गत वित्त विधेयक में घोषित कर परिवर्तन तुरंत प्रभावी हो जाते हैं, पर यदि विधेयक निर्धारित अवधि में अधिनियमित न हो तो वे समाप्त हो जाते हैं। यह अवधि कितनी है?","optionsHi":["14 दिन","60 दिन","90 दिन","75 दिन"],"explanationHi":"यह अधिनियम घोषित प्रावधानों को तुरंत लागू होने देता है, ताकि लोग नए कर से बच न सकें, पर केवल 75 दिन के लिए, जब तक वित्त विधेयक उससे पहले कानून न बन जाए। 14 दिन धन विधेयक पर राज्यसभा की सीमा है।"},
  {"id":"eco-planning-budget-129","question":"How many of these statements are correct? I. A Money Bill can be introduced only on the recommendation of the President. II. A Financial Bill under Article 117(1) can be introduced only in the Lok Sabha. III. A Financial Bill under Article 117(3), which merely involves expenditure from the Consolidated Fund, can be introduced in either House. IV. Like a Money Bill, a Financial Bill under Article 117(1) cannot be rejected by the Rajya Sabha.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Apart from the rules on introduction, an Article 117(1) Bill is treated as an ordinary Bill, so the Rajya Sabha can amend or reject it and a joint sitting is possible; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"इनमें से कितने कथन सही हैं? I. धन विधेयक केवल राष्ट्रपति की सिफारिश पर पुरःस्थापित किया जा सकता है। II. अनुच्छेद 117(1) के अंतर्गत वित्तीय विधेयक केवल लोकसभा में पुरःस्थापित हो सकता है। III. अनुच्छेद 117(3) के अंतर्गत वित्तीय विधेयक, जिसमें केवल संचित निधि से व्यय निहित हो, किसी भी सदन में पुरःस्थापित हो सकता है। IV. धन विधेयक की तरह अनुच्छेद 117(1) के अंतर्गत वित्तीय विधेयक को राज्यसभा अस्वीकार नहीं कर सकती।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। पुरःस्थापन के नियमों के अतिरिक्त अनुच्छेद 117(1) का विधेयक साधारण विधेयक माना जाता है, इसलिए राज्यसभा उसमें संशोधन या उसे अस्वीकार कर सकती है और संयुक्त बैठक संभव है; IV गलत है।"},
  {"id":"eco-planning-budget-130","question":"Which of the following is charged on the Consolidated Fund of India?","options":["Salaries of the judges of High Courts","Salary of the Attorney General of India","Pensions of the judges of High Courts","Salaries of the Union Cabinet ministers"],"answer":2,"explanation":"Article 112(3) charges the pensions of High Court judges on the Consolidated Fund of India, but their salaries are charged on the Consolidated Fund of the State. The Attorney General’s pay and ministers’ salaries are voted expenditure.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"निम्नलिखित में से कौन भारत की संचित निधि पर भारित है?","optionsHi":["उच्च न्यायालयों के न्यायाधीशों के वेतन","भारत के महान्यायवादी का वेतन","उच्च न्यायालयों के न्यायाधीशों की पेंशन","केंद्रीय मंत्रिमंडल के मंत्रियों के वेतन"],"explanationHi":"अनुच्छेद 112(3) उच्च न्यायालयों के न्यायाधीशों की पेंशन को भारत की संचित निधि पर भारित करता है, पर उनके वेतन राज्य की संचित निधि पर भारित हैं। महान्यायवादी का वेतन और मंत्रियों के वेतन मतदान वाला व्यय हैं।"},
  {"id":"eco-planning-budget-131","question":"Assertion (A): Money can be paid out of the Public Account of India without an appropriation passed by Parliament. Reason (R): Sums in the Public Account, such as provident fund and small savings deposits, are held by the government as a banker and must be repaid to their owners.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Under Article 266(2), the Public Account holds money that is not the government’s own revenue; the government acts as a banker or trustee, so withdrawals need no appropriation law, unlike the Consolidated Fund.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"अभिकथन (A): संसद द्वारा पारित विनियोग के बिना भारत के लोक लेखा से धन निकाला जा सकता है। कारण (R): लोक लेखा में जमा राशियाँ, जैसे भविष्य निधि और लघु बचत जमाएँ, सरकार के पास बैंकर के रूप में रखी जाती हैं और उनके स्वामियों को लौटानी होती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"अनुच्छेद 266(2) के अंतर्गत लोक लेखा में वह धन होता है जो सरकार का अपना राजस्व नहीं है; सरकार बैंकर या न्यासी के रूप में काम करती है, इसलिए संचित निधि के विपरीत निकासी के लिए विनियोग कानून आवश्यक नहीं।"},
  {"id":"eco-planning-budget-132","question":"A budget shows: revenue receipts ₹20 lakh crore; revenue expenditure ₹26 lakh crore, including interest payments of ₹7 lakh crore; capital expenditure ₹6 lakh crore; recovery of loans ₹1 lakh crore; disinvestment receipts ₹1 lakh crore. The fiscal deficit and primary deficit are:","options":["₹12 and ₹5 lakh crore","₹11 and ₹4 lakh crore","₹6 and −₹1 lakh crore","₹10 and ₹3 lakh crore"],"answer":3,"explanation":"Fiscal deficit = total expenditure 32 − (revenue receipts 20 + non-debt capital receipts 2) = 10; primary deficit = 10 − interest 7 = 3. Ignoring the non-debt receipts gives 12 and 5; ₹6 lakh crore is the revenue deficit.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक बजट में: राजस्व प्राप्तियाँ ₹20 लाख करोड़; राजस्व व्यय ₹26 लाख करोड़, जिसमें ₹7 लाख करोड़ ब्याज भुगतान हैं; पूंजीगत व्यय ₹6 लाख करोड़; ऋणों की वसूली ₹1 लाख करोड़; विनिवेश प्राप्तियाँ ₹1 लाख करोड़ हैं। राजकोषीय घाटा और प्राथमिक घाटा क्रमशः हैं:","optionsHi":["₹12 और ₹5 लाख करोड़","₹11 और ₹4 लाख करोड़","₹6 और −₹1 लाख करोड़","₹10 और ₹3 लाख करोड़"],"explanationHi":"राजकोषीय घाटा = कुल व्यय 32 − (राजस्व प्राप्तियाँ 20 + गैर-ऋण पूंजीगत प्राप्तियाँ 2) = 10; प्राथमिक घाटा = 10 − ब्याज 7 = 3। गैर-ऋण प्राप्तियों को छोड़ देने पर 12 और 5 आते हैं; ₹6 लाख करोड़ राजस्व घाटा है।"},
  {"id":"eco-planning-budget-133","question":"Financing a deficit by creating new money is often called an ‘inflation tax’ mainly because:","options":["Rising prices push taxpayers into higher income-tax slabs and raise collections","Inflation erodes the real value of cash held, shifting resources to the issuer","The central bank pays interest on the new money, which the government then taxes","Higher prices raise GST collections, since GST is charged as a share of value"],"answer":1,"explanation":"New money lets the government buy real resources, while inflation cuts the purchasing power of the cash already held by the public, acting like a tax on money balances. Bracket creep (fiscal drag) is a different effect.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"नई मुद्रा बनाकर घाटे का वित्तपोषण करना प्रायः ‘मुद्रास्फीति कर’ क्यों कहलाता है?","optionsHi":["बढ़ती कीमतें करदाताओं को ऊँचे आयकर स्लैब में धकेलती हैं और संग्रह बढ़ाती हैं","मुद्रास्फीति धारित नकदी का वास्तविक मूल्य घटाती है, जिससे संसाधन निर्गमकर्ता को स्थानांतरित हो जाते हैं","केंद्रीय बैंक नई मुद्रा पर ब्याज देता है, जिस पर सरकार फिर कर लगाती है","ऊँची कीमतें GST संग्रह बढ़ाती हैं, क्योंकि GST मूल्य के अनुपात में लगता है"],"explanationHi":"नई मुद्रा से सरकार वास्तविक संसाधन खरीद लेती है, जबकि मुद्रास्फीति जनता के पास पहले से रखी नकदी की क्रय शक्ति घटा देती है, जो मुद्रा शेष पर कर जैसा काम करती है। ब्रैकेट क्रीप (राजकोषीय ड्रैग) एक अलग प्रभाव है।"},
  {"id":"eco-planning-budget-134","question":"In Musgrave’s three-fold classification of the functions of public finance, deliberately running a larger deficit during a slump to revive demand belongs to the:","options":["Allocation function","Distribution function","Stabilisation function","Developmental function"],"answer":2,"explanation":"Musgrave’s functions are allocation (providing goods the market under-supplies), distribution (adjusting income shares) and stabilisation (keeping output, employment and prices steady); counter-cyclical deficits serve stabilisation.","difficulty":"moderate","source":"RBI Grade B · UPSC Prelims","questionHi":"मस्ग्रेव के लोक वित्त के कार्यों के त्रिविध वर्गीकरण में, मंदी के दौरान मांग को पुनर्जीवित करने के लिए जानबूझकर बड़ा घाटा चलाना किस कार्य के अंतर्गत आता है?","optionsHi":["आवंटन कार्य","वितरण कार्य","स्थिरीकरण कार्य","विकासात्मक कार्य"],"explanationHi":"मस्ग्रेव के कार्य हैं: आवंटन (बाज़ार द्वारा कम आपूर्ति की गई वस्तुएँ उपलब्ध कराना), वितरण (आय के हिस्सों को समायोजित करना) और स्थिरीकरण (उत्पादन, रोज़गार और कीमतों को स्थिर रखना); प्रति-चक्रीय घाटे स्थिरीकरण की सेवा करते हैं।"},
  {"id":"eco-planning-budget-135","question":"An uncongested toll expressway, from which non-payers can be shut out but where one more car imposes no cost on other users, is an example of a:","options":["Club (toll) good","Pure public good","Common-pool resource","Pure private good"],"answer":0,"explanation":"It is excludable (tolls) but non-rival (while uncongested), which defines a club good. A pure public good is non-excludable as well; a common-pool resource is rival but non-excludable.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"भीड़-रहित टोल एक्सप्रेसवे, जिससे भुगतान न करने वालों को बाहर रखा जा सकता है पर जहाँ एक और कार अन्य उपयोगकर्ताओं पर कोई लागत नहीं डालती, किसका उदाहरण है?","optionsHi":["क्लब (टोल) वस्तु","शुद्ध सार्वजनिक वस्तु","सामूहिक संसाधन","शुद्ध निजी वस्तु"],"explanationHi":"यह अपवर्जनीय (टोल) पर अप्रतिस्पर्धी (भीड़ न होने तक) है, जो क्लब वस्तु की परिभाषा है। शुद्ध सार्वजनिक वस्तु अनपवर्जनीय भी होती है; सामूहिक संसाधन प्रतिस्पर्धी पर अनपवर्जनीय होता है।"},
  {"id":"eco-planning-budget-136","question":"The ‘displacement effect’, under which public spending jumps during a crisis such as a war and does not fall back to its old level afterwards, is associated with:","options":["Adolph Wagner","Richard Musgrave","Buchanan and Tullock","Peacock and Wiseman"],"answer":3,"explanation":"Peacock and Wiseman argued that public spending rises in steps: crises raise the tax level people tolerate, and it stays higher later. Wagner’s law links a rising share of public spending to industrial growth in general; Buchanan and Tullock founded public choice theory.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"‘विस्थापन प्रभाव’, जिसके अनुसार युद्ध जैसे संकट में सार्वजनिक व्यय छलाँग लगाता है और बाद में अपने पुराने स्तर पर नहीं लौटता, किससे संबद्ध है?","optionsHi":["एडॉल्फ वैगनर","रिचर्ड मस्ग्रेव","ब्यूकैनन और टुलोक","पीकॉक और वाइज़मैन"],"explanationHi":"पीकॉक और वाइज़मैन ने तर्क दिया कि सार्वजनिक व्यय सीढ़ी-दर-सीढ़ी बढ़ता है: संकट उस कर स्तर को बढ़ा देते हैं जिसे लोग सहन करते हैं, और वह बाद में भी ऊँचा बना रहता है। वैगनर का नियम औद्योगिक वृद्धि के साथ सार्वजनिक व्यय के बढ़ते हिस्से को जोड़ता है; ब्यूकैनन और टुलोक ने लोक चयन सिद्धांत की नींव रखी।"},
  {"id":"eco-planning-budget-137","question":"Which of the following is NOT one of Adam Smith’s four canons of taxation?","options":["Certainty","Convenience","Economy","Elasticity"],"answer":3,"explanation":"Smith’s canons are equality, certainty, convenience and economy. Elasticity, productivity and simplicity were added by later writers such as Bastable.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"निम्नलिखित में से कौन एडम स्मिथ के कराधान के चार सिद्धांतों में से नहीं है?","optionsHi":["निश्चितता","सुविधा","मितव्ययिता","लोच"],"explanationHi":"स्मिथ के सिद्धांत हैं: समानता, निश्चितता, सुविधा और मितव्ययिता। लोच, उत्पादकता और सरलता को बाद के लेखकों, जैसे बैस्टेबल, ने जोड़ा।"},
  {"id":"eco-planning-budget-138","question":"Two taxpayers with the same income and circumstances paying the same amount of tax illustrates:","options":["Horizontal equity","Vertical equity","The benefit principle","Tax neutrality"],"answer":0,"explanation":"Horizontal equity means equals are treated equally; vertical equity means those with a greater ability to pay bear more. The benefit principle links tax to the benefit received from public services.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"समान आय और परिस्थितियों वाले दो करदाताओं द्वारा समान कर चुकाना किसका उदाहरण है?","optionsHi":["क्षैतिज समता","ऊर्ध्वाधर समता","लाभ सिद्धांत","कर तटस्थता"],"explanationHi":"क्षैतिज समता का अर्थ है कि समान लोगों से समान व्यवहार हो; ऊर्ध्वाधर समता का अर्थ है कि अधिक भुगतान-क्षमता वाले अधिक कर दें। लाभ सिद्धांत कर को सार्वजनिक सेवाओं से मिले लाभ से जोड़ता है।"},
  {"id":"eco-planning-budget-139","question":"A per-unit tax is imposed on the sellers of a good whose demand is perfectly inelastic and whose supply curve slopes upward. The burden of the tax falls:","options":["Entirely on the sellers, since they pay it to the treasury","Entirely on the buyers, as the price rises by the full tax","Equally on buyers and sellers, whatever the elasticities","Mostly on the sellers, as the quantity sold falls sharply"],"answer":1,"explanation":"Incidence depends on elasticities, not on who hands the tax over. With perfectly inelastic demand, quantity does not change and the price rises by the whole tax, so buyers bear all of it.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"ऐसी वस्तु के विक्रेताओं पर प्रति इकाई कर लगाया जाता है जिसकी मांग पूर्णतः बेलोचदार है और आपूर्ति वक्र ऊपर की ओर ढालू है। कर का बोझ किस पर पड़ता है?","optionsHi":["पूरी तरह विक्रेताओं पर, क्योंकि वे इसे राजकोष में चुकाते हैं","पूरी तरह क्रेताओं पर, क्योंकि कीमत पूरे कर के बराबर बढ़ जाती है","क्रेताओं और विक्रेताओं पर बराबर, लोच चाहे जो हो","अधिकांशतः विक्रेताओं पर, क्योंकि बिक्री की मात्रा तेज़ी से घटती है"],"explanationHi":"कर की घटना लोच पर निर्भर करती है, इस पर नहीं कि कर कौन सौंपता है। पूर्णतः बेलोचदार मांग में मात्रा नहीं बदलती और कीमत पूरे कर के बराबर बढ़ जाती है, इसलिए क्रेता पूरा बोझ उठाते हैं।"},
  {"id":"eco-planning-budget-140","question":"With straight-line demand and supply curves, if a per-unit tax on a good is doubled, the deadweight loss from the tax:","options":["Also roughly doubles in size","Rises by about one and a half times","Becomes about four times as large","Stays about the same, as only prices change"],"answer":2,"explanation":"Deadweight loss is a triangle of ½ × tax × fall in quantity, and the fall in quantity is itself proportional to the tax, so the loss rises with the square of the tax rate. This is why broad bases with low rates are preferred.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"सरल रेखीय मांग और आपूर्ति वक्रों के साथ, यदि किसी वस्तु पर प्रति इकाई कर दोगुना कर दिया जाए, तो कर से होने वाली अधिभार-हानि (डेडवेट लॉस):","optionsHi":["भी लगभग दोगुनी हो जाती है","लगभग डेढ़ गुना बढ़ती है","लगभग चार गुना हो जाती है","लगभग समान रहती है, क्योंकि केवल कीमतें बदलती हैं"],"explanationHi":"अधिभार-हानि ½ × कर × मात्रा में गिरावट वाला एक त्रिभुज है, और मात्रा में गिरावट स्वयं कर के समानुपाती है, इसलिए हानि कर दर के वर्ग के अनुसार बढ़ती है। इसीलिए व्यापक आधार और कम दरों को प्राथमिकता दी जाती है।"},
  {"id":"eco-planning-budget-141","question":"Which pairing of a Five-Year Plan with its stated focus is correct?","options":["Fifth Plan – Growth with social justice and equality","Seventh Plan – Food, work and productivity","Ninth Plan – Removal of poverty (Garibi Hatao)","Third Plan – Faster and more inclusive growth"],"answer":1,"explanation":"The Seventh Plan (1985–90) stressed food, work and productivity. Garibi Hatao belongs to the Fifth Plan, growth with social justice and equality to the Ninth, and faster and more inclusive growth to the Eleventh.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"पंचवर्षीय योजना और उसके घोषित केंद्र-बिंदु का कौन-सा युग्म सही है?","optionsHi":["पाँचवीं योजना – सामाजिक न्याय और समानता के साथ वृद्धि","सातवीं योजना – खाद्यान्न, रोज़गार और उत्पादकता","नौवीं योजना – गरीबी उन्मूलन (गरीबी हटाओ)","तीसरी योजना – तीव्र और अधिक समावेशी विकास"],"explanationHi":"सातवीं योजना (1985–90) में खाद्यान्न, रोज़गार और उत्पादकता पर बल था। गरीबी हटाओ पाँचवीं योजना का, सामाजिक न्याय और समानता के साथ वृद्धि नौवीं का, और तीव्र तथा अधिक समावेशी विकास ग्यारहवीं का केंद्र-बिंदु था।"},
  {"id":"eco-planning-budget-142","question":"The Mahalanobis model behind the Second Five-Year Plan argued that, in a closed economy, the long-run rate of growth depends mainly on:","options":["The share of investment going to the capital-goods sector","The share of investment going to agriculture and irrigation","The growth of export earnings to pay for imported machinery","The inflow of foreign aid to fill the domestic savings gap"],"answer":0,"explanation":"Assuming a closed economy, Mahalanobis held that a larger share of investment in machine-making (capital goods) raises future investment capacity and growth, which is why the Second Plan favoured heavy industry. The aid argument is the two-gap model.","difficulty":"moderate","source":"UPSC Prelims · RBI Grade B","questionHi":"द्वितीय पंचवर्षीय योजना के पीछे के महालनोबिस मॉडल का तर्क था कि बंद अर्थव्यवस्था में दीर्घकालिक वृद्धि दर मुख्यतः किस पर निर्भर करती है?","optionsHi":["निवेश का वह हिस्सा जो पूंजीगत वस्तु क्षेत्र में जाता है","निवेश का वह हिस्सा जो कृषि और सिंचाई में जाता है","आयातित मशीनरी के भुगतान के लिए निर्यात आय की वृद्धि","घरेलू बचत अंतराल को भरने के लिए विदेशी सहायता का प्रवाह"],"explanationHi":"बंद अर्थव्यवस्था मानकर महालनोबिस का मत था कि मशीन-निर्माण (पूंजीगत वस्तुओं) में निवेश का बड़ा हिस्सा भावी निवेश क्षमता और वृद्धि बढ़ाता है, इसीलिए द्वितीय योजना ने भारी उद्योग को प्राथमिकता दी। सहायता वाला तर्क द्वि-अंतराल मॉडल का है।"},
  {"id":"eco-planning-budget-143","question":"A key functional difference between NITI Aayog and the former Planning Commission is that NITI Aayog:","options":["Is a statutory body, while the Planning Commission was set up by a resolution","Is chaired by the Finance Minister rather than by the Prime Minister","Prepares Five-Year Plans that must be approved by the National Development Council","Has no power to allocate plan funds to central ministries and the States"],"answer":3,"explanation":"The Planning Commission decided plan allocations to ministries and States; NITI Aayog is an advisory think tank without fund-allocation powers. Like its predecessor it was created by a Cabinet resolution and is chaired by the PM.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"नीति आयोग और पूर्ववर्ती योजना आयोग के बीच एक प्रमुख कार्यात्मक अंतर यह है कि नीति आयोग:","optionsHi":["एक सांविधिक निकाय है, जबकि योजना आयोग संकल्प से बना था","प्रधानमंत्री के बजाय वित्त मंत्री की अध्यक्षता में चलता है","ऐसी पंचवर्षीय योजनाएँ बनाता है जिन्हें राष्ट्रीय विकास परिषद से अनुमोदित कराना होता है","केंद्रीय मंत्रालयों और राज्यों को योजना निधि आवंटित करने की शक्ति नहीं रखता"],"explanationHi":"योजना आयोग मंत्रालयों और राज्यों के लिए योजना आवंटन तय करता था; नीति आयोग निधि आवंटन की शक्ति के बिना एक परामर्शी थिंक टैंक है। अपने पूर्ववर्ती की तरह यह भी मंत्रिमंडल के संकल्प से बना है और प्रधानमंत्री इसके अध्यक्ष हैं।"},
  {"id":"eco-planning-budget-144","question":"The duty of the Finance Commission to recommend measures to augment a State’s Consolidated Fund so as to supplement the resources of Panchayats and Municipalities was added by:","options":["The 42nd Amendment Act of 1976","The 80th Amendment of 2000","The 101st Amendment of 2016","The 73rd and 74th Amendments"],"answer":3,"explanation":"The 73rd and 74th Amendments (1992) inserted Article 280(3)(bb) and (c), on the basis of State Finance Commission reports. The 80th Amendment changed tax sharing to a divisible pool; the 101st brought GST.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"पंचायतों और नगरपालिकाओं के संसाधनों की पूर्ति हेतु राज्य की संचित निधि बढ़ाने के उपाय सुझाने का वित्त आयोग का कर्तव्य किसके द्वारा जोड़ा गया?","optionsHi":["42वाँ संशोधन अधिनियम, 1976","80वाँ संशोधन, 2000","101वाँ संशोधन, 2016","73वाँ और 74वाँ संशोधन"],"explanationHi":"73वें और 74वें संशोधनों (1992) ने राज्य वित्त आयोगों की रिपोर्टों के आधार पर अनुच्छेद 280(3)(bb) और (c) जोड़े। 80वें संशोधन ने कर बँटवारे को विभाज्य पूल में बदला; 101वाँ GST लाया।"},
  {"id":"eco-planning-budget-145","question":"A State Finance Commission is constituted:","options":["By the President every five years, under Article 280","By the Governor every five years, under Article 243-I","By the Union Finance Commission, under Article 243Y","By the State legislature every three years, under Article 243-I"],"answer":1,"explanation":"Article 243-I requires the Governor to constitute a Finance Commission every five years to review the finances of Panchayats; Article 243Y extends its remit to Municipalities. Article 280 covers the Union Finance Commission.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"राज्य वित्त आयोग का गठन किया जाता है:","optionsHi":["राष्ट्रपति द्वारा हर पाँच वर्ष में, अनुच्छेद 280 के अंतर्गत","राज्यपाल द्वारा हर पाँच वर्ष में, अनुच्छेद 243-I के अंतर्गत","संघ वित्त आयोग द्वारा, अनुच्छेद 243Y के अंतर्गत","राज्य विधानमंडल द्वारा हर तीन वर्ष में, अनुच्छेद 243-I के अंतर्गत"],"explanationHi":"अनुच्छेद 243-I के अनुसार राज्यपाल पंचायतों की वित्तीय स्थिति की समीक्षा के लिए हर पाँच वर्ष में वित्त आयोग गठित करते हैं; अनुच्छेद 243Y इसका दायरा नगरपालिकाओं तक बढ़ाता है। अनुच्छेद 280 संघ वित्त आयोग से संबंधित है।"},
  {"id":"eco-planning-budget-146","question":"A State still owes part of a loan made to it by the Government of India and wants to raise a fresh loan in the market. Under Article 293 it:","options":["May borrow freely within India, subject only to RBI guidelines","Needs a resolution passed by both Houses of Parliament","Can borrow only from the RBI through ways and means advances","Needs the consent of the Government of India for the loan"],"answer":3,"explanation":"Article 293(3) says a State may not raise a loan without the Union’s consent while any part of a Union loan to it is outstanding; the Union may attach conditions. States can borrow only within India.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"किसी राज्य पर भारत सरकार द्वारा दिए गए ऋण का कुछ भाग अब भी बकाया है और वह बाज़ार से नया ऋण लेना चाहता है। अनुच्छेद 293 के अंतर्गत वह:","optionsHi":["भारत के भीतर स्वतंत्र रूप से उधार ले सकता है, केवल RBI के दिशानिर्देशों के अधीन","संसद के दोनों सदनों से पारित संकल्प की आवश्यकता होगी","केवल अर्थोपाय अग्रिमों के माध्यम से RBI से उधार ले सकता है","ऋण के लिए भारत सरकार की सहमति आवश्यक होगी"],"explanationHi":"अनुच्छेद 293(3) के अनुसार जब तक संघ के ऋण का कोई भाग बकाया हो, राज्य संघ की सहमति के बिना ऋण नहीं ले सकता; संघ शर्तें लगा सकता है। राज्य केवल भारत के भीतर उधार ले सकते हैं।"},
  {"id":"eco-planning-budget-147","question":"Under Article 276, the total of taxes on professions, trades, callings and employments that any one person can be made to pay to a State or local body in a year cannot exceed:","options":["₹2,500","₹250","₹5,000","₹25,000"],"answer":0,"explanation":"The ceiling of ₹250 was raised to ₹2,500 by the 60th Amendment (1988), and it remains in the Constitution. Because of this cap, professional tax is a minor source of State revenue.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"अनुच्छेद 276 के अंतर्गत, किसी एक व्यक्ति से किसी राज्य या स्थानीय निकाय को एक वर्ष में वृत्ति, व्यापार, आजीविका और नियोजन पर लगाए जा सकने वाले करों का कुल योग कितनी सीमा से अधिक नहीं हो सकता?","optionsHi":["₹2,500","₹250","₹5,000","₹25,000"],"explanationHi":"₹250 की सीमा को 60वें संशोधन (1988) द्वारा बढ़ाकर ₹2,500 किया गया, जो संविधान में विद्यमान है। इस सीमा के कारण व्यवसाय कर राज्य राजस्व का एक छोटा स्रोत है।"},
  {"id":"eco-planning-budget-148","question":"Under Article 268, stamp duties on bills of exchange, cheques and promissory notes mentioned in the Union List are:","options":["Levied and collected by the States under their own laws","Levied by the Union but collected and kept by the States","Levied and collected by the Union and assigned wholly to the States","Levied and collected by the Union and shared through the divisible pool"],"answer":1,"explanation":"Article 268 covers duties that the Union imposes but that the States collect and appropriate. Article 269 covers taxes the Union both levies and collects but assigns to the States; Article 270 covers the shared divisible pool.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"अनुच्छेद 268 के अंतर्गत, संघ सूची में उल्लिखित विनिमय पत्रों, चेकों और प्रतिज्ञा-पत्रों पर स्टाम्प शुल्क:","optionsHi":["राज्यों द्वारा अपने कानूनों के अंतर्गत लगाए और वसूले जाते हैं","संघ द्वारा लगाए जाते हैं पर राज्यों द्वारा वसूले और रखे जाते हैं","संघ द्वारा लगाए और वसूले जाते हैं तथा पूरी तरह राज्यों को सौंप दिए जाते हैं","संघ द्वारा लगाए और वसूले जाते हैं तथा विभाज्य पूल के माध्यम से बाँटे जाते हैं"],"explanationHi":"अनुच्छेद 268 उन शुल्कों से संबंधित है जो संघ लगाता है पर राज्य वसूलते और अपने पास रखते हैं। अनुच्छेद 269 उन करों से संबंधित है जो संघ लगाता और वसूलता है पर राज्यों को सौंप देता है; अनुच्छेद 270 साझा विभाज्य पूल से।"},
  {"id":"eco-planning-budget-149","question":"In a closed economy the marginal propensity to consume out of disposable income is 0.8 and income tax is a flat 25% of income. If government spending rises by ₹100 crore, equilibrium income rises by:","options":["₹500 crore","₹400 crore","₹250 crore","₹200 crore"],"answer":2,"explanation":"Multiplier = 1/[1 − c(1 − t)] = 1/(1 − 0.8 × 0.75) = 1/0.4 = 2.5, so income rises by ₹250 crore. ₹500 crore ignores the tax leakage; ₹400 crore uses the tax multiplier c/(1 − c).","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"एक बंद अर्थव्यवस्था में प्रयोज्य आय से सीमांत उपभोग प्रवृत्ति 0.8 है और आयकर आय का एक समान 25% है। यदि सरकारी व्यय ₹100 करोड़ बढ़ता है, तो संतुलन आय कितनी बढ़ती है?","optionsHi":["₹500 करोड़","₹400 करोड़","₹250 करोड़","₹200 करोड़"],"explanationHi":"गुणक = 1/[1 − c(1 − t)] = 1/(1 − 0.8 × 0.75) = 1/0.4 = 2.5, इसलिए आय ₹250 करोड़ बढ़ती है। ₹500 करोड़ कर के रिसाव की उपेक्षा करता है; ₹400 करोड़ कर गुणक c/(1 − c) का उपयोग करता है।"},
  {"id":"eco-planning-budget-150","question":"‘Fiscal dominance’ describes a situation in which:","options":["The finance ministry, not the central bank, legally fixes the policy repo rate each quarter","Fiscal policy beats monetary policy in a liquidity trap, so the treasury takes the lead","Persistent budget surpluses absorb private saving and push market interest rates down","Heavy deficits and debt press the central bank to keep rates low or fund the government"],"answer":3,"explanation":"Under fiscal dominance the government’s financing needs constrain monetary policy, forcing low rates or monetisation and weakening the central bank’s control of inflation. That is why an independent inflation-targeting framework is paired with fiscal rules.","difficulty":"hard","source":"RBI Grade B","questionHi":"‘राजकोषीय प्रभुत्व’ उस स्थिति का वर्णन करता है जिसमें:","optionsHi":["केंद्रीय बैंक नहीं, बल्कि वित्त मंत्रालय हर तिमाही नीतिगत रेपो दर कानूनन तय करता है","तरलता जाल में राजकोषीय नीति मौद्रिक नीति को हरा देती है, इसलिए राजकोष नेतृत्व करता है","लगातार बजट अधिशेष निजी बचत को सोख लेते हैं और बाज़ार ब्याज दरों को नीचे धकेलते हैं","भारी घाटे और ऋण केंद्रीय बैंक पर दरें नीची रखने या सरकार को वित्त देने का दबाव डालते हैं"],"explanationHi":"राजकोषीय प्रभुत्व में सरकार की वित्तपोषण आवश्यकताएँ मौद्रिक नीति को बाँध देती हैं, जिससे नीची दरें या मुद्रीकरण करना पड़ता है और मुद्रास्फीति पर केंद्रीय बैंक का नियंत्रण कमज़ोर होता है। इसीलिए स्वतंत्र मुद्रास्फीति-लक्ष्यीकरण ढाँचे के साथ राजकोषीय नियम जोड़े जाते हैं।"},
  {"id":"eco-planning-budget-151","question":"In an open economy, private saving is 25% of GDP, private investment 28% of GDP and the government’s budget deficit 6% of GDP. Using the identity (S − I) + (T − G) = (X − M), the current account balance is:","options":["A deficit of 9% of GDP","A deficit of 3% of GDP","A surplus of 3% of GDP","A deficit of 6% of GDP"],"answer":0,"explanation":"(S − I) = −3 and (T − G) = −6, so X − M = −9% of GDP. This ‘twin deficits’ link shows that a larger fiscal deficit, unless matched by higher private saving, widens the current account deficit.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"एक खुली अर्थव्यवस्था में निजी बचत GDP का 25%, निजी निवेश GDP का 28% और सरकार का बजट घाटा GDP का 6% है। पहचान (S − I) + (T − G) = (X − M) का प्रयोग करने पर चालू खाता शेष है:","optionsHi":["GDP का 9% घाटा","GDP का 3% घाटा","GDP का 3% अधिशेष","GDP का 6% घाटा"],"explanationHi":"(S − I) = −3 और (T − G) = −6, इसलिए X − M = GDP का −9%। यह ‘जुड़वाँ घाटे’ का संबंध दर्शाता है कि बड़ा राजकोषीय घाटा, जब तक ऊँची निजी बचत से संतुलित न हो, चालू खाता घाटे को बढ़ाता है।"},
  {"id":"eco-planning-budget-152","question":"A small trader opts for the GST composition scheme. Which consequence follows?","options":["He pays a low flat rate on turnover but can neither claim nor pass on input credit","He pays no GST at all but can still pass input tax credit on to his business buyers","He pays only IGST on all sales, while CGST and SGST on his supplies are fully waived","He claims input tax credit as usual but pays tax at a flat rate on profit, not on turnover"],"answer":0,"explanation":"The composition scheme trades simplicity for credit: tax is paid at a low rate on turnover, input tax credit is not available, and the dealer cannot collect GST from customers, so his buyers get no credit either.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक छोटा व्यापारी GST की संघटन योजना (कंपोज़िशन स्कीम) चुनता है। इसका क्या परिणाम होता है?","optionsHi":["वह टर्नओवर पर कम एकसमान दर से कर चुकाता है, पर इनपुट क्रेडिट न ले सकता है, न आगे दे सकता है","वह कोई GST नहीं चुकाता, पर फिर भी अपने व्यावसायिक क्रेताओं को इनपुट टैक्स क्रेडिट दे सकता है","वह अपनी सभी बिक्री पर केवल IGST चुकाता है, जबकि उसकी आपूर्तियों पर CGST और SGST पूरी तरह माफ़ हैं","वह सामान्य रूप से इनपुट टैक्स क्रेडिट लेता है पर टर्नओवर पर नहीं, बल्कि लाभ पर एकसमान दर से कर चुकाता है"],"explanationHi":"संघटन योजना में सरलता के बदले क्रेडिट छोड़ना पड़ता है: टर्नओवर पर कम दर से कर चुकाया जाता है, इनपुट टैक्स क्रेडिट उपलब्ध नहीं होता, और डीलर ग्राहकों से GST वसूल नहीं कर सकता, इसलिए उसके क्रेताओं को भी क्रेडिट नहीं मिलता।"},
  {"id":"eco-planning-budget-153","question":"During a Financial Emergency proclaimed under Article 360, the President may:","options":["Levy taxes on State List subjects without any law of Parliament","Transfer the balance of a State’s Consolidated Fund to the Union","Direct a cut in the salaries of Supreme Court and High Court judges","Spend from the Consolidated Fund of India without an appropriation law"],"answer":2,"explanation":"Article 360 lets the President direct reductions in the salaries of Union and State employees, including Supreme Court and High Court judges, and require State Money Bills to be reserved for consideration. It does not suspend the need for laws to tax or spend.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"अनुच्छेद 360 के अंतर्गत घोषित वित्तीय आपातकाल के दौरान राष्ट्रपति:","optionsHi":["संसद के किसी कानून के बिना राज्य सूची के विषयों पर कर लगा सकते हैं","किसी राज्य की संचित निधि का शेष संघ को अंतरित कर सकते हैं","उच्चतम न्यायालय और उच्च न्यायालयों के न्यायाधीशों के वेतन में कटौती का निर्देश दे सकते हैं","विनियोग कानून के बिना भारत की संचित निधि से खर्च कर सकते हैं"],"explanationHi":"अनुच्छेद 360 राष्ट्रपति को उच्चतम न्यायालय और उच्च न्यायालयों के न्यायाधीशों सहित संघ और राज्यों के कर्मचारियों के वेतन में कटौती का निर्देश देने तथा राज्यों के धन विधेयकों को विचारार्थ आरक्षित रखने की अपेक्षा करने की शक्ति देता है। यह कर लगाने या खर्च करने के लिए कानूनों की आवश्यकता को निलंबित नहीं करता।"},
  {"id":"eco-planning-budget-154","question":"How many of these statements are correct? I. The distinction between Plan and Non-Plan expenditure was dropped from the Union Budget of 2017–18. II. The Union Government keeps its accounts on a cash basis. III. The Receipt Budget shows recoveries of loans as revenue receipts. IV. Excess grants are voted by the Lok Sabha before the extra money is spent, on the advice of the Public Accounts Committee.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Recoveries of loans are non-debt capital receipts, and excess grants are voted only after the money has been spent and the PAC has examined the excess, so III and IV are wrong.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"इनमें से कितने कथन सही हैं? I. योजना और गैर-योजना व्यय का भेद 2017–18 के केंद्रीय बजट से समाप्त कर दिया गया। II. केंद्र सरकार अपने लेखे नकद आधार पर रखती है। III. प्राप्ति बजट ऋणों की वसूली को राजस्व प्राप्तियों के रूप में दिखाता है। IV. आधिक्य अनुदान अतिरिक्त धन खर्च करने से पहले लोक लेखा समिति की सलाह पर लोकसभा द्वारा मतदान से स्वीकृत किए जाते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। ऋणों की वसूली गैर-ऋण पूंजीगत प्राप्तियाँ हैं, और आधिक्य अनुदान धन खर्च हो जाने और लोक लेखा समिति द्वारा आधिक्य की जाँच के बाद ही स्वीकृत होते हैं, इसलिए III और IV गलत हैं।"},
  {"id":"eco-planning-budget-155","question":"The National Planning Committee set up by the Indian National Congress in 1938 was chaired by:","options":["Jawaharlal Nehru","Subhas Chandra Bose","M. Visvesvaraya","P. C. Mahalanobis"],"answer":0,"explanation":"The committee was set up in 1938 during Subhas Chandra Bose’s term as Congress President, but Jawaharlal Nehru chaired it. Visvesvaraya had earlier written Planned Economy for India (1934).","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"भारतीय राष्ट्रीय कांग्रेस द्वारा 1938 में गठित राष्ट्रीय योजना समिति के अध्यक्ष कौन थे?","optionsHi":["जवाहरलाल नेहरू","सुभाष चंद्र बोस","एम. विश्वेश्वरैया","पी. सी. महालनोबिस"],"explanationHi":"समिति का गठन 1938 में सुभाष चंद्र बोस के कांग्रेस अध्यक्ष काल में हुआ, पर इसकी अध्यक्षता जवाहरलाल नेहरू ने की। विश्वेश्वरैया ने इससे पहले ‘प्लान्ड इकोनॉमी फॉर इंडिया’ (1934) लिखी थी।"},
  {"id":"eco-planning-budget-156","question":"‘Planned Economy for India’ (1934), one of the earliest blueprints for economic planning in the country, was written by:","options":["Shriman Narayan","M. N. Roy","M. Visvesvaraya","J. R. D. Tata"],"answer":2,"explanation":"Engineer-statesman M. Visvesvaraya proposed doubling national income in ten years through industrialisation. Shriman Narayan wrote the Gandhian Plan, M. N. Roy the People’s Plan, and Tata was among the Bombay Plan authors.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"‘प्लान्ड इकोनॉमी फॉर इंडिया’ (1934), जो देश में आर्थिक नियोजन के सबसे पहले प्रारूपों में से एक थी, किसने लिखी?","optionsHi":["श्रीमन नारायण","एम. एन. रॉय","एम. विश्वेश्वरैया","जे. आर. डी. टाटा"],"explanationHi":"इंजीनियर-राजनेता एम. विश्वेश्वरैया ने औद्योगीकरण द्वारा दस वर्ष में राष्ट्रीय आय दोगुनी करने का प्रस्ताव रखा। श्रीमन नारायण ने गांधीवादी योजना, एम. एन. रॉय ने जन योजना लिखी, और टाटा बॉम्बे योजना के लेखकों में थे।"},
  {"id":"eco-planning-budget-157","question":"How many of these statements about short-term government paper are correct? I. Treasury bills are issued at a discount and redeemed at face value. II. The Government of India issues Treasury bills of 91, 182 and 364 days. III. State governments meet temporary cash gaps through ways and means advances from the RBI. IV. Cash Management Bills, of less than 91 days, meet temporary mismatches in the Centre’s cash flow.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: T-bills are issued at a discount; the Centre issues 91, 182 and 364-day bills; States use RBI ways and means advances for short gaps; and Cash Management Bills of under 91 days meet the Centre's temporary mismatches.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"अल्पकालिक सरकारी प्रतिभूतियों के बारे में इनमें से कितने कथन सही हैं? I. ट्रेज़री बिल बट्टे पर जारी होते हैं और अंकित मूल्य पर भुनाए जाते हैं। II. भारत सरकार 91, 182 और 364 दिन के ट्रेज़री बिल जारी करती है। III. राज्य सरकारें अस्थायी नकदी अंतराल RBI से अर्थोपाय अग्रिमों द्वारा पूरे करती हैं। IV. 91 दिन से कम के नकद प्रबंधन बिल केंद्र के नकदी प्रवाह में अस्थायी असंतुलन पूरे करते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: ट्रेज़री बिल बट्टे पर जारी होते हैं; केंद्र 91, 182 और 364 दिन के बिल जारी करता है; राज्य छोटे अंतराल के लिए RBI के अर्थोपाय अग्रिम लेते हैं; और 91 दिन से कम के नकद प्रबंधन बिल केंद्र के अस्थायी असंतुलन पूरे करते हैं।"},
  {"id":"eco-planning-budget-158","question":"A 91-day Treasury bill with a face value of ₹100 is issued at ₹98.50. Its annualised yield on a 365-day basis is about:","options":["6.00%","6.02%","6.11%","1.52%"],"answer":2,"explanation":"Yield = (100 − 98.5)/98.5 × 365/91 × 100 ≈ 6.11%. Dividing the discount by face value instead of price gives 6.02%; simply multiplying 1.5% by four gives 6.00%; 1.52% is not annualised.","difficulty":"hard","source":"RBI Grade B","questionHi":"₹100 अंकित मूल्य का 91 दिन का ट्रेज़री बिल ₹98.50 पर जारी होता है। 365 दिन के आधार पर इसकी वार्षिकीकृत प्रतिफल दर लगभग कितनी है?","optionsHi":["6.00%","6.02%","6.11%","1.52%"],"explanationHi":"प्रतिफल = (100 − 98.5)/98.5 × 365/91 × 100 ≈ 6.11%। बट्टे को कीमत के बजाय अंकित मूल्य से भाग देने पर 6.02% आता है; 1.5% को केवल चार से गुणा करने पर 6.00%; और 1.52% वार्षिकीकृत नहीं है।"},
  {"id":"eco-planning-budget-159","question":"Ways and Means Advances (WMA) from the RBI to the Government of India are meant to:","options":["Finance the government’s fiscal deficit on a permanent basis","Bridge temporary mismatches between the government’s receipts and payments","Refinance the government’s maturing dated securities at below-market rates","Fund the capital of public sector banks during a financial crisis"],"answer":1,"explanation":"WMA are short-term advances, within limits agreed with the RBI, that cover timing gaps in cash flow; use beyond the limit becomes an overdraft. They replaced the ad hoc Treasury bills that had monetised deficits automatically.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"भारत सरकार को RBI से मिलने वाले अर्थोपाय अग्रिम (WMA) का उद्देश्य क्या है?","optionsHi":["सरकार के राजकोषीय घाटे का स्थायी आधार पर वित्तपोषण","सरकार की प्राप्तियों और भुगतानों के बीच अस्थायी असंतुलन को पाटना","सरकार की परिपक्व हो रही दिनांकित प्रतिभूतियों का बाज़ार से कम दर पर पुनर्वित्तपोषण","वित्तीय संकट के दौरान सार्वजनिक क्षेत्र के बैंकों की पूंजी की पूर्ति"],"explanationHi":"WMA अल्पकालिक अग्रिम हैं, जो RBI से सहमत सीमाओं के भीतर नकदी प्रवाह के समय-अंतराल पूरे करते हैं; सीमा से अधिक उपयोग ओवरड्राफ्ट बन जाता है। इन्होंने उन तदर्थ ट्रेज़री बिलों का स्थान लिया जो घाटे का स्वतः मुद्रीकरण करते थे।"},
  {"id":"eco-planning-budget-160","question":"Assertion (A): Since April 2006 the RBI has generally not subscribed to the primary issues of the Central Government’s securities. Reason (R): The FRBM Act also bars the RBI from buying Central Government securities in the secondary market through open market operations.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"The FRBM Act barred RBI subscription to primary issues from 1 April 2006, except on specified grounds, but expressly allowed it to trade G-secs in the secondary market, which is how OMOs work. So A is true and R is false.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"अभिकथन (A): अप्रैल 2006 से RBI ने सामान्यतः केंद्र सरकार की प्रतिभूतियों के प्राथमिक निर्गमों में अभिदान नहीं किया है। कारण (R): FRBM अधिनियम RBI को खुले बाज़ार संचालन के माध्यम से द्वितीयक बाज़ार में केंद्र सरकार की प्रतिभूतियाँ खरीदने से भी रोकता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"FRBM अधिनियम ने 1 अप्रैल 2006 से निर्दिष्ट आधारों को छोड़कर RBI के प्राथमिक निर्गमों में अभिदान पर रोक लगाई, पर द्वितीयक बाज़ार में G-secs के व्यापार की स्पष्ट अनुमति दी, जिससे OMO चलते हैं। इसलिए A सत्य और R असत्य है।"},
  {"id":"eco-planning-budget-161","question":"Collections under small savings schemes such as the Public Provident Fund and National Savings Certificates are credited to the National Small Savings Fund, which is part of the:","options":["Consolidated Fund of India","Contingency Fund of India","Public Account of India","Reserve Bank’s balance sheet"],"answer":2,"explanation":"The NSSF, set up in 1999, sits in the Public Account because the deposits belong to savers and must be repaid. Its money is lent mainly to the Centre through special securities, one source of financing the fiscal deficit.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"लोक भविष्य निधि और राष्ट्रीय बचत प्रमाणपत्र जैसी लघु बचत योजनाओं का संग्रह राष्ट्रीय लघु बचत निधि में जमा होता है, जो किसका भाग है?","optionsHi":["भारत की संचित निधि","भारत की आकस्मिकता निधि","भारत का लोक लेखा","रिज़र्व बैंक का तुलन पत्र"],"explanationHi":"1999 में बनी NSSF लोक लेखा में है क्योंकि जमाएँ बचतकर्ताओं की हैं और लौटानी होती हैं। इसका धन मुख्यतः विशेष प्रतिभूतियों के माध्यम से केंद्र को उधार दिया जाता है, जो राजकोषीय घाटे के वित्तपोषण का एक स्रोत है।"},
  {"id":"eco-planning-budget-162","question":"Which criterion used by the Fifteenth Finance Commission for sharing taxes among the States was meant to reward States that had brought down their fertility rates?","options":["Demographic performance","Income distance","Forest and ecology","Population as per Census 2011"],"answer":0,"explanation":"Because the 2011 population was used (itself a criterion, which favours populous States), the Commission added ‘demographic performance’ so that States that had controlled fertility were not penalised. Income distance favours poorer States, and forest cover rewards ecological services.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"राज्यों के बीच करों के बँटवारे के लिए पंद्रहवें वित्त आयोग द्वारा प्रयुक्त कौन-सा मानदंड उन राज्यों को पुरस्कृत करने के लिए था जिन्होंने अपनी प्रजनन दर घटाई थी?","optionsHi":["जनसांख्यिकीय निष्पादन","आय दूरी","वन और पारिस्थितिकी","जनगणना 2011 के अनुसार जनसंख्या"],"explanationHi":"चूँकि 2011 की जनसंख्या का उपयोग (जो स्वयं एक मानदंड है और अधिक आबादी वाले राज्यों के पक्ष में जाता है) किया गया, आयोग ने ‘जनसांख्यिकीय निष्पादन’ जोड़ा ताकि प्रजनन दर नियंत्रित करने वाले राज्य दंडित न हों। आय दूरी गरीब राज्यों के पक्ष में जाती है, और वन आवरण पारिस्थितिकीय सेवाओं को पुरस्कृत करता है।"},
  {"id":"eco-planning-budget-163","question":"Under the ‘income distance’ criterion used by recent Finance Commissions for horizontal devolution, a State gets a larger share when:","options":["Its per capita income is further below that of the highest-income States","Its total income has grown faster than the national average in recent years","Its own tax revenue is a larger share of its gross State domestic product","Its per capita income is closer to that of the highest-income States"],"answer":0,"explanation":"Income distance measures how far a State’s per capita income lies below a benchmark of the richest States; the greater the gap, the larger the share, so it is an equalising criterion. Tax effort is rewarded by a separate criterion.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"क्षैतिज हस्तांतरण के लिए हाल के वित्त आयोगों द्वारा प्रयुक्त ‘आय दूरी’ मानदंड के अंतर्गत किसी राज्य को बड़ा हिस्सा तब मिलता है जब:","optionsHi":["उसकी प्रति व्यक्ति आय सबसे अधिक आय वाले राज्यों की आय से और नीचे हो","हाल के वर्षों में उसकी कुल आय राष्ट्रीय औसत से तेज़ बढ़ी हो","उसका अपना कर राजस्व उसके सकल राज्य घरेलू उत्पाद का बड़ा हिस्सा हो","उसकी प्रति व्यक्ति आय सबसे अधिक आय वाले राज्यों की आय के निकट हो"],"explanationHi":"आय दूरी यह मापती है कि किसी राज्य की प्रति व्यक्ति आय सबसे धनी राज्यों के मानक से कितनी नीचे है; अंतर जितना अधिक, हिस्सा उतना बड़ा, इसलिए यह समकारी मानदंड है। कर प्रयास को एक अलग मानदंड से पुरस्कृत किया जाता है।"},
  {"id":"eco-planning-budget-164","question":"Under the reverse charge mechanism in GST:","options":["The supplier pays the tax and later recovers it from the government as a refund","The recipient of the supply, rather than the supplier, is liable to pay the tax","The tax is collected only at the final retail stage instead of at each stage","The Centre pays the tax on behalf of small suppliers below the threshold"],"answer":1,"explanation":"Normally the supplier pays GST; for notified supplies, or purchases from certain unregistered persons, the liability shifts to the recipient, who may then claim input tax credit if eligible.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"GST में रिवर्स चार्ज तंत्र के अंतर्गत:","optionsHi":["आपूर्तिकर्ता कर चुकाता है और बाद में सरकार से रिफंड के रूप में वसूल लेता है","कर चुकाने का दायित्व आपूर्तिकर्ता के बजाय आपूर्ति प्राप्तकर्ता का होता है","कर हर चरण के बजाय केवल अंतिम खुदरा चरण पर वसूला जाता है","केंद्र सीमा से नीचे के छोटे आपूर्तिकर्ताओं की ओर से कर चुकाता है"],"explanationHi":"सामान्यतः आपूर्तिकर्ता GST चुकाता है; अधिसूचित आपूर्तियों, या कुछ अपंजीकृत व्यक्तियों से खरीद में, दायित्व प्राप्तकर्ता पर आ जाता है, जो पात्र होने पर इनपुट टैक्स क्रेडिट का दावा कर सकता है।"},
  {"id":"eco-planning-budget-165","question":"Exports are ‘zero-rated’ under GST. This means that the exporter:","options":["Pays no tax on the export and cannot claim credit for tax paid on inputs","Pays tax at a token rate of 0.1% and can claim credit for tax paid on inputs","Pays no tax on the export yet can claim or get a refund of input credit","Pays the full tax on the export but gets a refund once foreign payment arrives"],"answer":2,"explanation":"Zero-rating removes tax from the export and refunds the tax embedded in inputs, so exports leave free of domestic taxes. An exempt supply also bears no output tax, but its input tax credit is lost.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"GST के अंतर्गत निर्यात ‘शून्य-दर’ वाले होते हैं। इसका अर्थ है कि निर्यातक:","optionsHi":["निर्यात पर कोई कर नहीं चुकाता और इनपुट पर चुकाए कर का क्रेडिट नहीं ले सकता","0.1% की सांकेतिक दर से कर चुकाता है और इनपुट पर चुकाए कर का क्रेडिट ले सकता है","निर्यात पर कोई कर नहीं चुकाता, फिर भी इनपुट क्रेडिट का दावा या रिफंड पा सकता है","निर्यात पर पूरा कर चुकाता है पर विदेशी भुगतान आने पर रिफंड पा जाता है"],"explanationHi":"शून्य-दर निर्यात से कर हटाती है और इनपुट में निहित कर लौटाती है, इसलिए निर्यात घरेलू करों से मुक्त होकर जाते हैं। छूट प्राप्त आपूर्ति पर भी आउटपुट कर नहीं लगता, पर उसका इनपुट टैक्स क्रेडिट खो जाता है।"},
  {"id":"eco-planning-budget-166","question":"Assertion (A): A firm making only GST-exempt supplies often bears higher costs than a firm making zero-rated supplies. Reason (R): Input tax credit is not available on inputs used for exempt supplies, so the tax on inputs becomes part of the firm’s cost.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Neither firm charges output tax, but only the zero-rated supplier can recover the GST paid on inputs. For the exempt supplier that tax is stranded and raises costs, which is why ‘exempt’ is not the same as ‘tax-free’.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"अभिकथन (A): केवल GST-मुक्त आपूर्तियाँ करने वाली फर्म की लागत प्रायः शून्य-दर आपूर्तियाँ करने वाली फर्म से अधिक होती है। कारण (R): छूट प्राप्त आपूर्तियों में प्रयुक्त इनपुट पर इनपुट टैक्स क्रेडिट उपलब्ध नहीं होता, इसलिए इनपुट पर लगा कर फर्म की लागत का भाग बन जाता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों फर्में आउटपुट कर नहीं लगातीं, पर केवल शून्य-दर आपूर्तिकर्ता ही इनपुट पर चुकाया GST वापस पा सकता है। छूट प्राप्त आपूर्तिकर्ता के लिए वह कर फँस जाता है और लागत बढ़ाता है, इसीलिए ‘छूट’ का अर्थ ‘कर-मुक्त’ नहीं है।"},
  {"id":"eco-planning-budget-167","question":"Under the GST rules, an e-way bill is generally required before moving goods whose consignment value exceeds:","options":["₹25,000","₹1 lakh","₹10 lakh","₹50,000"],"answer":3,"explanation":"The e-way bill, generated on the common portal, is needed for movement of goods worth more than ₹50,000 per consignment, with some State-specific variations for movement within a State.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"GST नियमों के अंतर्गत, सामान्यतः किस मूल्य से अधिक की खेप वाले माल को ले जाने से पहले ई-वे बिल आवश्यक होता है?","optionsHi":["₹25,000","₹1 लाख","₹10 लाख","₹50,000"],"explanationHi":"साझा पोर्टल पर बनने वाला ई-वे बिल प्रति खेप ₹50,000 से अधिक मूल्य के माल की आवाजाही के लिए आवश्यक है, जिसमें राज्य के भीतर आवाजाही के लिए कुछ राज्य-विशिष्ट भिन्नताएँ हैं।"},
  {"id":"eco-planning-budget-168","question":"The GST (Compensation to States) Act, 2017 worked out each State’s ‘protected revenue’ by assuming that its revenue from the subsumed taxes would grow every year by:","options":["10%","12%","14%","15%"],"answer":2,"explanation":"Revenue for the base year 2015–16 was projected to grow at 14% a year; any shortfall of actual GST revenue below this was paid from the compensation cess fund for five years.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"GST (राज्यों को क्षतिपूर्ति) अधिनियम, 2017 ने प्रत्येक राज्य का ‘संरक्षित राजस्व’ यह मानकर निकाला कि समाहित करों से उसका राजस्व हर वर्ष कितना बढ़ेगा?","optionsHi":["10%","12%","14%","15%"],"explanationHi":"आधार वर्ष 2015–16 के राजस्व के प्रति वर्ष 14% की दर से बढ़ने का अनुमान था; वास्तविक GST राजस्व में इससे कोई भी कमी पाँच वर्ष तक क्षतिपूर्ति उपकर निधि से चुकाई गई।"},
  {"id":"eco-planning-budget-169","question":"Minimum Alternate Tax (MAT) is meant for companies that:","options":["Show large book profits but pay little normal tax because of exemptions","Make losses in their books and so would otherwise pay no tax at all on their turnover","Distribute dividends to shareholders out of profits that have not yet been taxed","Earn income abroad on which no tax has been paid to any foreign government"],"answer":0,"explanation":"MAT taxes a minimum share of book profit when tax under the normal provisions falls below it, stopping ‘zero-tax companies’ that show healthy profits to shareholders. Firms with book losses pay no MAT.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"न्यूनतम वैकल्पिक कर (MAT) किन कंपनियों के लिए है?","optionsHi":["जो बड़े बही लाभ दिखाती हैं पर छूटों के कारण सामान्य कर बहुत कम चुकाती हैं","जो अपनी बहियों में घाटा दिखाती हैं और इसलिए अन्यथा अपने टर्नओवर पर कोई कर नहीं चुकातीं","जो उन लाभों में से शेयरधारकों को लाभांश बाँटती हैं जिन पर अभी कर नहीं लगा","जो विदेश में ऐसी आय अर्जित करती हैं जिस पर किसी विदेशी सरकार को कर नहीं चुकाया गया"],"explanationHi":"जब सामान्य प्रावधानों के अंतर्गत कर बही लाभ के एक न्यूनतम हिस्से से नीचे चला जाता है, तो MAT उस न्यूनतम हिस्से पर कर लगाता है, जिससे शेयरधारकों को अच्छे लाभ दिखाने वाली ‘शून्य-कर कंपनियाँ’ रुकती हैं। बही घाटे वाली फर्में MAT नहीं चुकातीं।"},
  {"id":"eco-planning-budget-170","question":"Which of these taxes is administered by the Central Board of Direct Taxes rather than by the Central Board of Indirect Taxes and Customs?","options":["Basic customs duty on imports","Central excise duty on petrol","Integrated GST on imports","Securities Transaction Tax"],"answer":3,"explanation":"Securities Transaction Tax, introduced in 2004 on deals in securities on recognised stock exchanges, is collected under the Finance Act and administered by the CBDT. Customs, excise and IGST fall under the CBIC.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"इनमें से कौन-सा कर केंद्रीय अप्रत्यक्ष कर और सीमा शुल्क बोर्ड के बजाय केंद्रीय प्रत्यक्ष कर बोर्ड द्वारा प्रशासित होता है?","optionsHi":["आयात पर मूल सीमा शुल्क","पेट्रोल पर केंद्रीय उत्पाद शुल्क","आयात पर एकीकृत GST","प्रतिभूति लेन-देन कर"],"explanationHi":"2004 में मान्यता प्राप्त स्टॉक एक्सचेंजों पर प्रतिभूतियों के सौदों पर लागू किया गया प्रतिभूति लेन-देन कर वित्त अधिनियम के अंतर्गत वसूला जाता है और CBDT द्वारा प्रशासित होता है। सीमा शुल्क, उत्पाद शुल्क और IGST CBIC के अंतर्गत आते हैं।"},
  {"id":"eco-planning-budget-171","question":"After the Union Budget 2020–21 abolished the Dividend Distribution Tax, dividends from Indian companies are taxed:","options":["In the hands of the shareholders, at the rates that apply to them","Only in the hands of the company, at a flat rate on profits paid out","Neither in the company’s hands nor in the hands of shareholders","Only when shareholders sell their shares, as part of capital gains"],"answer":0,"explanation":"DDT was paid by companies on dividends declared; from 2020–21 the classical system returned, with dividends added to the shareholder’s income and taxed at his or her applicable rate, with tax deducted at source.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"केंद्रीय बजट 2020–21 द्वारा लाभांश वितरण कर समाप्त किए जाने के बाद भारतीय कंपनियों के लाभांश पर कर कैसे लगता है?","optionsHi":["शेयरधारकों के हाथ में, उन पर लागू दरों से","केवल कंपनी के हाथ में, चुकाए गए लाभ पर एकसमान दर से","न कंपनी के हाथ में, न शेयरधारकों के हाथ में","केवल तब जब शेयरधारक अपने शेयर बेचें, पूंजीगत लाभ के भाग के रूप में"],"explanationHi":"DDT घोषित लाभांश पर कंपनियाँ चुकाती थीं; 2020–21 से परंपरागत प्रणाली लौट आई, जिसमें लाभांश शेयरधारक की आय में जुड़ता है और उसकी लागू दर से कर लगता है, तथा स्रोत पर कर कटौती होती है।"},
  {"id":"eco-planning-budget-172","question":"Under a hypothetical income tax, income up to ₹3 lakh is exempt, the next ₹3 lakh is taxed at 10% and income above ₹6 lakh at 20%. For a person earning ₹10 lakh, the average and marginal tax rates are:","options":["Average 20%, marginal 20%","Average 11%, marginal 20%","Average 11%, marginal 10%","Average 15%, marginal 20%"],"answer":1,"explanation":"Tax = 10% of 3 lakh + 20% of 4 lakh = ₹1.1 lakh, an average rate of 11%; the rate on the last rupee earned is 20%. Applying 20% to the whole income is the common slab-system mistake.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक काल्पनिक आयकर में ₹3 लाख तक की आय मुक्त है, अगले ₹3 लाख पर 10% कर लगता है और ₹6 लाख से ऊपर की आय पर 20%। ₹10 लाख कमाने वाले व्यक्ति के लिए औसत और सीमांत कर दरें हैं:","optionsHi":["औसत 20%, सीमांत 20%","औसत 11%, सीमांत 20%","औसत 11%, सीमांत 10%","औसत 15%, सीमांत 20%"],"explanationHi":"कर = 3 लाख का 10% + 4 लाख का 20% = ₹1.1 लाख, यानी औसत दर 11%; अंतिम रुपये पर दर 20% है। पूरी आय पर 20% लगा देना स्लैब प्रणाली की आम भूल है।"},
  {"id":"eco-planning-budget-173","question":"Which of the following is NOT a source of financing the Union Government’s fiscal deficit?","options":["Net market borrowings through dated securities","Securities issued against small savings","Net external assistance from multilateral bodies","Proceeds from disinvestment of PSU shares"],"answer":3,"explanation":"Disinvestment is a non-debt capital receipt that is counted before the deficit is struck, so it reduces the fiscal deficit rather than financing it. The deficit itself is financed by borrowing from the market, small savings, external sources and so on.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"निम्नलिखित में से कौन केंद्र सरकार के राजकोषीय घाटे के वित्तपोषण का स्रोत नहीं है?","optionsHi":["दिनांकित प्रतिभूतियों के माध्यम से निवल बाज़ार उधारी","लघु बचत के बदले जारी प्रतिभूतियाँ","बहुपक्षीय निकायों से निवल बाह्य सहायता","सार्वजनिक क्षेत्र के उपक्रमों के शेयरों के विनिवेश से प्राप्तियाँ"],"explanationHi":"विनिवेश गैर-ऋण पूंजीगत प्राप्ति है जो घाटा निकालने से पहले गिनी जाती है, इसलिए यह राजकोषीय घाटे का वित्तपोषण करने के बजाय उसे घटाती है। घाटे का वित्तपोषण बाज़ार उधारी, लघु बचत, बाह्य स्रोतों आदि से होता है।"},
  {"id":"eco-planning-budget-174","question":"A government’s debt is 50% of GDP and its primary budget is exactly balanced. If the nominal interest rate on debt is 8% and nominal GDP grows by 10%, next year’s debt-to-GDP ratio will be about:","options":["49.0%","49.1%","51.0%","50.0%"],"answer":1,"explanation":"With no primary deficit, debt grows only by interest: 50 × 1.08 / 1.10 ≈ 49.09% of GDP. Subtracting the 2-point growth–interest gap from 50% straight away gives 49.0%, which ignores the division by (1 + g).","difficulty":"very-hard","source":"RBI Grade B","questionHi":"किसी सरकार का ऋण GDP का 50% है और उसका प्राथमिक बजट ठीक संतुलित है। यदि ऋण पर सांकेतिक ब्याज दर 8% और सांकेतिक GDP वृद्धि 10% है, तो अगले वर्ष का ऋण-GDP अनुपात लगभग होगा:","optionsHi":["49.0%","49.1%","51.0%","50.0%"],"explanationHi":"प्राथमिक घाटा न होने पर ऋण केवल ब्याज से बढ़ता है: 50 × 1.08 / 1.10 ≈ GDP का 49.09%। 50% में से सीधे 2 अंक का वृद्धि–ब्याज अंतर घटा देने पर 49.0% आता है, जो (1 + g) से भाग देना छोड़ देता है।"},
  {"id":"eco-planning-budget-175","question":"Which of the following did NOT contribute to the ‘Plan Holiday’ of 1966–69?","options":["The war with Pakistan in 1965","Two successive droughts in the mid-1960s","The shortfall of the Third Plan’s targets","The first oil price shock of 1973"],"answer":3,"explanation":"War, drought, the Third Plan’s failure and the 1966 devaluation forced three Annual Plans before the Fourth Plan began in 1969. The oil shock came in 1973, during the Fourth Plan.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"निम्नलिखित में से किसने 1966–69 के ‘योजना अवकाश’ में योगदान नहीं दिया?","optionsHi":["1965 में पाकिस्तान के साथ युद्ध","1960 के दशक के मध्य में लगातार दो सूखे","तीसरी योजना के लक्ष्यों में कमी","1973 का पहला तेल मूल्य आघात"],"explanationHi":"युद्ध, सूखा, तीसरी योजना की विफलता और 1966 के अवमूल्यन ने 1969 में चौथी योजना शुरू होने से पहले तीन वार्षिक योजनाएँ चलाने को विवश किया। तेल आघात 1973 में, चौथी योजना के दौरान आया।"},
  {"id":"eco-planning-budget-176","question":"The first Five-Year Plan to adopt ‘monitorable targets’ for indicators such as poverty, literacy and infant mortality, in addition to a target for GDP growth, was the:","options":["Eighth Plan","Ninth Plan","Eleventh Plan","Tenth Plan"],"answer":3,"explanation":"The Tenth Plan (2002–07) recognised that growth alone was not enough and set monitorable targets for key social indicators. The Eleventh Plan later expanded the list of such targets.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"GDP वृद्धि के लक्ष्य के साथ-साथ गरीबी, साक्षरता और शिशु मृत्यु दर जैसे संकेतकों के लिए ‘निगरानी योग्य लक्ष्य’ अपनाने वाली पहली पंचवर्षीय योजना कौन-सी थी?","optionsHi":["आठवीं योजना","नौवीं योजना","ग्यारहवीं योजना","दसवीं योजना"],"explanationHi":"दसवीं योजना (2002–07) ने माना कि केवल वृद्धि पर्याप्त नहीं है और प्रमुख सामाजिक संकेतकों के लिए निगरानी योग्य लक्ष्य रखे। ग्यारहवीं योजना ने बाद में ऐसे लक्ष्यों की सूची बढ़ाई।"},
  {"id":"eco-planning-budget-177","question":"Using the Harrod–Domar relation, if the incremental capital–output ratio is 4.5, by how many percentage points of GDP must the investment rate rise to lift growth from 6% to 8%?","options":["2 percentage points","4.5 percentage points","9 percentage points","8 percentage points"],"answer":2,"explanation":"Investment rate = growth × ICOR, so it must rise from 27% to 36% of GDP, a rise of 2 × 4.5 = 9 points. Answering 2 confuses the change in growth with the change in investment.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"हैरोड–डोमर संबंध का प्रयोग करते हुए, यदि वृद्धिशील पूंजी–उत्पाद अनुपात 4.5 है, तो वृद्धि को 6% से 8% तक ले जाने के लिए निवेश दर को GDP के कितने प्रतिशत अंक बढ़ाना होगा?","optionsHi":["2 प्रतिशत अंक","4.5 प्रतिशत अंक","9 प्रतिशत अंक","8 प्रतिशत अंक"],"explanationHi":"निवेश दर = वृद्धि × ICOR, इसलिए इसे GDP के 27% से 36% तक बढ़ना होगा, यानी 2 × 4.5 = 9 अंक की वृद्धि। 2 उत्तर देना वृद्धि में परिवर्तन को निवेश में परिवर्तन से उलझाना है।"},
  {"id":"eco-planning-budget-178","question":"If a government’s revenue deficit is larger than its fiscal deficit, it follows that:","options":["Interest payments must exceed the primary deficit of that year","Non-debt capital receipts exceed capital outlay, funding current spending","Capital expenditure is being financed entirely out of fresh borrowing","The government must be running a surplus on its revenue account this year"],"answer":1,"explanation":"Fiscal deficit = revenue deficit + capital expenditure − non-debt capital receipts. If the fiscal deficit is smaller, non-debt receipts such as disinvestment exceed capital spending and are financing current spending, a weak fiscal sign.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"यदि किसी सरकार का राजस्व घाटा उसके राजकोषीय घाटे से बड़ा है, तो इससे निष्कर्ष निकलता है कि:","optionsHi":["ब्याज भुगतान उस वर्ष के प्राथमिक घाटे से अधिक होने चाहिए","गैर-ऋण पूंजीगत प्राप्तियाँ पूंजीगत परिव्यय से अधिक हैं और चालू व्यय का वित्तपोषण कर रही हैं","पूंजीगत व्यय पूरी तरह नई उधारी से वित्तपोषित हो रहा है","सरकार इस वर्ष अपने राजस्व खाते पर अधिशेष चला रही होगी"],"explanationHi":"राजकोषीय घाटा = राजस्व घाटा + पूंजीगत व्यय − गैर-ऋण पूंजीगत प्राप्तियाँ। यदि राजकोषीय घाटा छोटा है, तो विनिवेश जैसी गैर-ऋण प्राप्तियाँ पूंजीगत व्यय से अधिक हैं और चालू व्यय का वित्तपोषण कर रही हैं, जो कमज़ोर राजकोषीय संकेत है।"},
  {"id":"eco-planning-budget-179","question":"Net fiscal deficit differs from gross fiscal deficit in that it:","options":["Deducts the government’s net lending to States and other bodies","Excludes the interest payments on past borrowing","Adds the borrowing done by public enterprises outside the budget","Counts only the part of borrowing financed by the RBI"],"answer":0,"explanation":"Net fiscal deficit = gross fiscal deficit − net lending (loans given minus recoveries), since loans create financial assets. Excluding interest gives the primary deficit; RBI financing is the monetised deficit.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"निवल राजकोषीय घाटा सकल राजकोषीय घाटे से किस प्रकार भिन्न है?","optionsHi":["यह राज्यों और अन्य निकायों को सरकार के निवल उधार को घटाता है","यह पिछली उधारी पर ब्याज भुगतान को शामिल नहीं करता","यह बजट से बाहर सार्वजनिक उद्यमों द्वारा की गई उधारी को जोड़ता है","यह उधारी के केवल उस भाग को गिनता है जिसका वित्तपोषण RBI ने किया"],"explanationHi":"निवल राजकोषीय घाटा = सकल राजकोषीय घाटा − निवल उधार (दिए गए ऋण घटा वसूलियाँ), क्योंकि ऋण वित्तीय परिसंपत्तियाँ बनाते हैं। ब्याज को छोड़ने से प्राथमिक घाटा मिलता है; RBI द्वारा वित्तपोषण मुद्रीकृत घाटा है।"},
  {"id":"eco-planning-budget-180","question":"Which of these is credited to the Public Account of India rather than to the Consolidated Fund of India?","options":["Proceeds of Treasury bills issued by the Centre","Provident fund deposits of government employees","Income tax collected by the Union","Recoveries of loans given to State governments"],"answer":1,"explanation":"Article 266(1) puts all revenue, all loans raised (including Treasury bills) and loan repayments into the Consolidated Fund. Provident fund deposits are held in trust and go to the Public Account under Article 266(2).","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"इनमें से कौन भारत की संचित निधि के बजाय भारत के लोक लेखा में जमा होता है?","optionsHi":["केंद्र द्वारा जारी ट्रेज़री बिलों की आय","सरकारी कर्मचारियों की भविष्य निधि जमाएँ","संघ द्वारा वसूला गया आयकर","राज्य सरकारों को दिए गए ऋणों की वसूली"],"explanationHi":"अनुच्छेद 266(1) सभी राजस्व, जुटाए गए सभी ऋण (ट्रेज़री बिल सहित) और ऋण वापसियों को संचित निधि में रखता है। भविष्य निधि जमाएँ न्यास के रूप में रखी जाती हैं और अनुच्छेद 266(2) के अंतर्गत लोक लेखा में जाती हैं।"},
  {"id":"eco-planning-budget-181","question":"Under Article 116, a ‘vote of credit’ is granted by the Lok Sabha when:","options":["The demand cannot be stated in detail because of its size or indefinite nature","Money already spent on a service exceeds the amount Parliament granted for that year","A new service not in the Budget needs only a token sum to begin","Money is needed for part of the year until the Budget is passed"],"answer":0,"explanation":"A vote of credit is like a blank cheque for an unexpected demand, such as during a war, whose details cannot be given. The other options describe an excess grant, a token grant and a vote on account.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"अनुच्छेद 116 के अंतर्गत लोकसभा ‘प्रत्ययानुदान’ कब स्वीकृत करती है?","optionsHi":["जब मांग का विवरण उसके आकार या अनिश्चित स्वरूप के कारण नहीं दिया जा सकता","जब किसी सेवा पर पहले ही खर्च हुआ धन उस वर्ष के लिए संसद द्वारा स्वीकृत राशि से अधिक हो","जब बजट में न शामिल किसी नई सेवा को शुरू करने के लिए केवल सांकेतिक राशि चाहिए","जब बजट पारित होने तक वर्ष के एक भाग के लिए धन चाहिए"],"explanationHi":"प्रत्ययानुदान किसी अप्रत्याशित मांग, जैसे युद्ध के समय, के लिए खुले चेक जैसा है जिसका विवरण नहीं दिया जा सकता। अन्य विकल्प आधिक्य अनुदान, सांकेतिक अनुदान और लेखानुदान का वर्णन करते हैं।"},
  {"id":"eco-planning-budget-182","question":"Since 1993, between the general discussion on the Budget and the voting on demands, the demands for grants of ministries are examined in detail by:","options":["The Estimates Committee","The Public Accounts Committee","The Committee on Public Undertakings","Departmental Standing Committees"],"answer":3,"explanation":"Department-related Standing Committees scrutinise each ministry’s demands during the Budget recess and report to Parliament. The PAC examines accounts after spending, and the Estimates Committee suggests economies.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"1993 से बजट पर सामान्य चर्चा और मांगों पर मतदान के बीच मंत्रालयों की अनुदान मांगों की विस्तृत जाँच कौन करता है?","optionsHi":["प्राक्कलन समिति","लोक लेखा समिति","सार्वजनिक उपक्रम समिति","विभागीय संबंधित स्थायी समितियाँ"],"explanationHi":"विभाग-संबंधित स्थायी समितियाँ बजट अवकाश के दौरान प्रत्येक मंत्रालय की मांगों की जाँच करती हैं और संसद को रिपोर्ट देती हैं। लोक लेखा समिति खर्च के बाद लेखों की जाँच करती है, और प्राक्कलन समिति मितव्ययिता के सुझाव देती है।"},
  {"id":"eco-planning-budget-183","question":"The doctrine of ‘functional finance’, associated with Abba Lerner, holds that:","options":["The budget should be balanced every year to keep public finances sound","Fiscal tools should be judged by their effect on jobs and prices, not on balance","Public spending should be confined to defence, justice and essential public works","Government should borrow only to finance investment and never to meet current spending"],"answer":1,"explanation":"Lerner argued that fiscal tools exist to keep the economy at full employment without inflation, so deficits or surpluses are fine if they achieve that. Annual balance is ‘sound finance’, and borrowing only for investment is the golden rule.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"अब्बा लर्नर से संबद्ध ‘क्रियात्मक वित्त’ (फंक्शनल फाइनेंस) का सिद्धांत मानता है कि:","optionsHi":["सार्वजनिक वित्त को स्वस्थ रखने के लिए बजट हर वर्ष संतुलित होना चाहिए","राजकोषीय उपकरणों को रोज़गार और कीमतों पर उनके प्रभाव से आँका जाए, संतुलन से नहीं","सार्वजनिक व्यय रक्षा, न्याय और आवश्यक सार्वजनिक निर्माण तक सीमित रहे","सरकार केवल निवेश के वित्तपोषण के लिए उधार ले, चालू व्यय के लिए कभी नहीं"],"explanationHi":"लर्नर का तर्क था कि राजकोषीय उपकरण अर्थव्यवस्था को मुद्रास्फीति के बिना पूर्ण रोज़गार पर रखने के लिए हैं, इसलिए घाटे या अधिशेष तब ठीक हैं जब वे यह लक्ष्य पाएँ। वार्षिक संतुलन ‘सुदृढ़ वित्त’ है, और केवल निवेश के लिए उधार स्वर्णिम नियम है।"},
  {"id":"eco-planning-budget-184","question":"Under Article 292, the Union Government may borrow on the security of the Consolidated Fund of India:","options":["Only with the prior approval of the Reserve Bank of India","Within the limits, if any, that Parliament fixes by law","Only within India and never from foreign lenders","Up to the limits that the Finance Commission recommends"],"answer":1,"explanation":"Article 292 lets the Union borrow within or outside India within limits Parliament may fix by law; States, under Article 293, can borrow only within India. Parliament has instead set deficit and debt targets through the FRBM Act.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"अनुच्छेद 292 के अंतर्गत, केंद्र सरकार भारत की संचित निधि की प्रतिभूति पर उधार ले सकती है:","optionsHi":["केवल भारतीय रिज़र्व बैंक की पूर्व स्वीकृति से","उन सीमाओं के भीतर, यदि कोई हों, जो संसद कानून द्वारा तय करे","केवल भारत के भीतर, विदेशी ऋणदाताओं से कभी नहीं","उन सीमाओं तक जो वित्त आयोग सिफारिश करे"],"explanationHi":"अनुच्छेद 292 संघ को भारत के भीतर या बाहर से उन सीमाओं में उधार लेने देता है जो संसद कानून द्वारा तय करे; राज्य, अनुच्छेद 293 के अंतर्गत, केवल भारत के भीतर उधार ले सकते हैं। संसद ने उसके बजाय FRBM अधिनियम के माध्यम से घाटा और ऋण लक्ष्य तय किए हैं।"},
  {"id":"eco-planning-budget-185","question":"Which of the following is still levied by the States outside GST?","options":["Entertainment tax by the State on cinema tickets","Value added tax on mobile phones","Luxury tax on hotel rooms","Electricity duty on power consumed"],"answer":3,"explanation":"Electricity is kept out of GST, so States continue to levy electricity duty. State entertainment tax, VAT on goods such as phones and luxury tax were all subsumed in GST in 2017.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा कर राज्य अब भी GST से बाहर लगाते हैं?","optionsHi":["राज्य द्वारा सिनेमा टिकटों पर मनोरंजन कर","मोबाइल फ़ोन पर मूल्य वर्धित कर","होटल के कमरों पर विलासिता कर","खपत की गई बिजली पर विद्युत शुल्क"],"explanationHi":"बिजली GST से बाहर रखी गई है, इसलिए राज्य विद्युत शुल्क लगाते रहते हैं। राज्य का मनोरंजन कर, फ़ोन जैसी वस्तुओं पर VAT और विलासिता कर, सभी 2017 में GST में समाहित हो गए।"},
  {"id":"eco-planning-budget-186","question":"States were induced to enact their own fiscal responsibility laws in the mid-2000s mainly because:","options":["The FRBM Act, 2003 directly applied its targets to every State","The GST Council required them as a condition for compensation","The RBI refused to manage the debt of States that lacked such laws","The Twelfth Finance Commission tied debt relief to such laws"],"answer":3,"explanation":"The Twelfth Finance Commission (2005–10) tied its debt consolidation and relief facility to States enacting fiscal responsibility legislation, and nearly all did. The Union FRBM Act binds only the Centre.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"2000 के दशक के मध्य में राज्यों को अपने राजकोषीय उत्तरदायित्व कानून बनाने के लिए मुख्यतः क्यों प्रेरित किया गया?","optionsHi":["FRBM अधिनियम, 2003 ने अपने लक्ष्य सीधे हर राज्य पर लागू किए","GST परिषद ने क्षतिपूर्ति की शर्त के रूप में इसे अनिवार्य किया","RBI ने ऐसे कानून न रखने वाले राज्यों के ऋण का प्रबंधन करने से इनकार किया","बारहवें वित्त आयोग ने ऋण राहत को ऐसे कानूनों से जोड़ा"],"explanationHi":"बारहवें वित्त आयोग (2005–10) ने अपनी ऋण समेकन और राहत सुविधा को राज्यों द्वारा राजकोषीय उत्तरदायित्व कानून बनाने से जोड़ा, और लगभग सभी राज्यों ने बनाए। केंद्रीय FRBM अधिनियम केवल केंद्र पर बाध्यकारी है।"},
  {"id":"eco-planning-budget-187","question":"Under Article 279, the ‘net proceeds’ of a Union tax, which decide how much is shared with the States, are ascertained and certified by:","options":["The Chairman of the Finance Commission","The Comptroller and Auditor-General","The Revenue Secretary, Ministry of Finance","The Controller General of Accounts of India"],"answer":1,"explanation":"Article 279 makes the CAG’s certificate of net proceeds (collections minus the cost of collection) final. The Finance Commission recommends the share, but does not certify the amount.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"अनुच्छेद 279 के अंतर्गत, किसी केंद्रीय कर की ‘निवल आय’, जो तय करती है कि राज्यों के साथ कितना साझा होगा, कौन निर्धारित और प्रमाणित करता है?","optionsHi":["वित्त आयोग का अध्यक्ष","नियंत्रक एवं महालेखा परीक्षक","वित्त मंत्रालय का राजस्व सचिव","भारत का महालेखा नियंत्रक"],"explanationHi":"अनुच्छेद 279 निवल आय (संग्रह घटा संग्रह की लागत) के CAG के प्रमाणपत्र को अंतिम बनाता है। वित्त आयोग हिस्सा सिफारिश करता है, पर राशि प्रमाणित नहीं करता।"},
  {"id":"eco-planning-budget-188","question":"Under Article 289, the property and income of a State are exempt from Union taxation, but Parliament may by law tax:","options":["Income from a trade or business run by or for the State government","Agricultural income earned on farms that the State government owns and runs","Salaries that the State pays to members of its own civil services","Land and buildings the State uses for its ordinary government offices"],"answer":0,"explanation":"Article 289(2) lets the Union tax a State’s trading or business operations, unless Parliament declares a trade incidental to ordinary government functions. Ordinary government property and income stay exempt.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 289 के अंतर्गत, राज्य की संपत्ति और आय संघ के कराधान से मुक्त हैं, पर संसद कानून द्वारा किस पर कर लगा सकती है?","optionsHi":["राज्य सरकार द्वारा या उसकी ओर से चलाए जा रहे व्यापार या कारोबार की आय","राज्य सरकार के स्वामित्व और संचालन वाले खेतों पर अर्जित कृषि आय","राज्य द्वारा अपनी सिविल सेवाओं के सदस्यों को दिए जाने वाले वेतन","राज्य द्वारा अपने सामान्य सरकारी कार्यालयों के लिए प्रयुक्त भूमि और भवन"],"explanationHi":"अनुच्छेद 289(2) संघ को राज्य के व्यापारिक या कारोबारी संचालन पर कर लगाने देता है, जब तक संसद यह घोषित न करे कि कोई व्यापार सामान्य सरकारी कार्यों का आनुषंगिक है। सामान्य सरकारी संपत्ति और आय मुक्त रहती हैं।"},
  {"id":"eco-planning-budget-189","question":"The qualifications of the members of the Finance Commission, and the way they are selected, are laid down by:","options":["Article 280 of the Constitution itself, in full detail","An order issued by the President after consulting the CAG","A law made by Parliament under Article 280(2)","Rules framed by NITI Aayog with the Finance Ministry’s approval"],"answer":2,"explanation":"Article 280(2) leaves these matters to Parliament, which passed the Finance Commission (Miscellaneous Provisions) Act, 1951. It requires, for example, that the chairman have experience in public affairs.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"वित्त आयोग के सदस्यों की अर्हताएँ और उनके चयन की रीति किसके द्वारा निर्धारित की जाती है?","optionsHi":["संविधान का अनुच्छेद 280 स्वयं, पूर्ण विस्तार में","CAG से परामर्श के बाद राष्ट्रपति द्वारा जारी आदेश","अनुच्छेद 280(2) के अंतर्गत संसद द्वारा बनाया गया कानून","वित्त मंत्रालय के अनुमोदन से नीति आयोग द्वारा बनाए गए नियम"],"explanationHi":"अनुच्छेद 280(2) ये विषय संसद पर छोड़ता है, जिसने वित्त आयोग (प्रकीर्ण उपबंध) अधिनियम, 1951 पारित किया। उदाहरण के लिए, यह अपेक्षा करता है कि अध्यक्ष को सार्वजनिक कार्यों का अनुभव हो।"},
  {"id":"eco-planning-budget-190","question":"The idea of a ‘rolling plan’, adopted by the Janata government in 1978 with targets revised every year, is usually credited to:","options":["Gunnar Myrdal","P. C. Mahalanobis","D. R. Gadgil","Ragnar Nurkse"],"answer":0,"explanation":"Gunnar Myrdal advocated plans that are reviewed and extended each year instead of fixed five-year blocks. D. R. Gadgil, then Deputy Chairman of the Planning Commission, is known for the Gadgil formula.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"‘रोलिंग योजना’ का विचार, जिसे 1978 में जनता सरकार ने अपनाया और जिसके लक्ष्य हर वर्ष संशोधित होते हैं, सामान्यतः किसे श्रेय दिया जाता है?","optionsHi":["गुन्नार मिर्डल","पी. सी. महालनोबिस","डी. आर. गाडगिल","रैग्नर नर्कसे"],"explanationHi":"गुन्नार मिर्डल ने निश्चित पंचवर्षीय खंडों के बजाय ऐसी योजनाओं की वकालत की जिनकी हर वर्ष समीक्षा और विस्तार हो। तत्कालीन योजना आयोग के उपाध्यक्ष डी. आर. गाडगिल गाडगिल सूत्र के लिए जाने जाते हैं।"},
  {"id":"eco-planning-budget-191","question":"The draft of the Fifth Five-Year Plan (1974–79), which stressed removal of poverty and self-reliance, was prepared under:","options":["D. P. Dhar","D. R. Gadgil","Gulzarilal Nanda","Manmohan Singh"],"answer":0,"explanation":"D. P. Dhar, as Deputy Chairman of the Planning Commission, prepared the Fifth Plan draft. Gadgil was associated with the Fourth Plan and Nanda with the early Plans.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"पाँचवीं पंचवर्षीय योजना (1974–79) का प्रारूप, जिसमें गरीबी उन्मूलन और आत्मनिर्भरता पर बल था, किसके नेतृत्व में तैयार हुआ?","optionsHi":["डी. पी. धर","डी. आर. गाडगिल","गुलजारीलाल नंदा","मनमोहन सिंह"],"explanationHi":"योजना आयोग के उपाध्यक्ष के रूप में डी. पी. धर ने पाँचवीं योजना का प्रारूप तैयार किया। गाडगिल चौथी योजना से और नंदा आरंभिक योजनाओं से जुड़े थे।"},
  {"id":"eco-planning-budget-192","question":"Which feature distinguishes imperative (directive) planning from indicative planning?","options":["In imperative planning, targets are only forecasts meant to guide private firms’ choices","In imperative planning, the State fixes targets and enforces them by controlling resources","In imperative planning, the private sector sets targets and the State only offers incentives","In imperative planning, there are no numerical targets at all, only broad policy goals"],"answer":1,"explanation":"Imperative planning, as in the Soviet model, directs production and resources by command. Indicative planning sets broad targets and steers a market economy through incentives and public investment, the path India took from the Eighth Plan.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"कौन-सी विशेषता आदेशात्मक (निर्देशात्मक) नियोजन को सांकेतिक नियोजन से अलग करती है?","optionsHi":["आदेशात्मक नियोजन में लक्ष्य केवल पूर्वानुमान होते हैं जो निजी फर्मों के चुनाव को दिशा देते हैं","आदेशात्मक नियोजन में राज्य लक्ष्य तय करता है और संसाधनों पर नियंत्रण से उन्हें लागू कराता है","आदेशात्मक नियोजन में निजी क्षेत्र लक्ष्य तय करता है और राज्य केवल प्रोत्साहन देता है","आदेशात्मक नियोजन में कोई संख्यात्मक लक्ष्य नहीं होते, केवल व्यापक नीतिगत उद्देश्य होते हैं"],"explanationHi":"आदेशात्मक नियोजन, जैसे सोवियत मॉडल में, आदेश द्वारा उत्पादन और संसाधनों को निर्देशित करता है। सांकेतिक नियोजन व्यापक लक्ष्य तय करता है और प्रोत्साहनों तथा सार्वजनिक निवेश से बाज़ार अर्थव्यवस्था को दिशा देता है; भारत ने आठवीं योजना से यही मार्ग अपनाया।"},
  {"id":"eco-planning-budget-193","question":"Assertion (A): An outgoing government presents an interim budget in a general election year. Reason (R): The Constitution forbids any change in tax rates in an interim budget.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"An interim budget with a vote on account is presented so that the new government can frame the full Budget. Avoiding major tax changes in it is only a convention; the Constitution does not mention interim budgets at all.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"अभिकथन (A): आम चुनाव के वर्ष में निवर्तमान सरकार अंतरिम बजट प्रस्तुत करती है। कारण (R): संविधान अंतरिम बजट में कर दरों में किसी भी परिवर्तन को प्रतिबंधित करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"लेखानुदान के साथ अंतरिम बजट इसलिए प्रस्तुत होता है ताकि नई सरकार पूर्ण बजट बना सके। उसमें बड़े कर परिवर्तनों से बचना केवल परंपरा है; संविधान में अंतरिम बजट का उल्लेख ही नहीं है।"},
  {"id":"eco-planning-budget-194","question":"How many of these statements about the voting of the Union Budget are correct? I. No demand for a grant can be made except on the recommendation of the President. II. The Lok Sabha may increase the amount of a demand for grant. III. The Rajya Sabha may discuss the Budget but does not vote on the demands for grants. IV. Expenditure charged on the Consolidated Fund may be discussed but is not put to the vote.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I (Article 113(3)), III and IV are correct. The Lok Sabha can assent to, refuse or reduce a demand, but cannot increase it, so II is wrong.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"केंद्रीय बजट पर मतदान के बारे में इनमें से कितने कथन सही हैं? I. राष्ट्रपति की सिफारिश के बिना अनुदान की कोई मांग नहीं की जा सकती। II. लोकसभा अनुदान की मांग की राशि बढ़ा सकती है। III. राज्यसभा बजट पर चर्चा कर सकती है पर अनुदान मांगों पर मतदान नहीं करती। IV. संचित निधि पर भारित व्यय पर चर्चा हो सकती है पर उस पर मतदान नहीं होता।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I (अनुच्छेद 113(3)), III और IV सही हैं। लोकसभा किसी मांग को स्वीकार, अस्वीकार या घटा सकती है, पर बढ़ा नहीं सकती, इसलिए II गलत है।"},
  {"id":"eco-planning-budget-195","question":"During a boom, a government’s actual fiscal deficit falls because tax receipts surge, but its cyclically adjusted (structural) primary deficit widens. The government’s fiscal stance is best described as:","options":["Contractionary, because the actual deficit has fallen","Expansionary, as the structural deficit has widened","Neutral, because the two changes cancel out","Contractionary, because tax receipts have risen"],"answer":1,"explanation":"The fiscal stance is judged by the change in the structural primary balance, which strips out the effect of the cycle. Here discretionary policy has loosened, so the stance is expansionary and pro-cyclical, despite the smaller headline deficit.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"तेज़ी के दौरान सरकार का वास्तविक राजकोषीय घाटा घटता है क्योंकि कर प्राप्तियाँ बढ़ जाती हैं, पर उसका चक्रीय रूप से समायोजित (संरचनात्मक) प्राथमिक घाटा बढ़ता है। सरकार के राजकोषीय रुख का सबसे उपयुक्त वर्णन है:","optionsHi":["संकुचनकारी, क्योंकि वास्तविक घाटा घटा है","विस्तारकारी, क्योंकि संरचनात्मक घाटा बढ़ा है","तटस्थ, क्योंकि दोनों परिवर्तन एक-दूसरे को निरस्त कर देते हैं","संकुचनकारी, क्योंकि कर प्राप्तियाँ बढ़ी हैं"],"explanationHi":"राजकोषीय रुख का आकलन संरचनात्मक प्राथमिक शेष में परिवर्तन से होता है, जो चक्र के प्रभाव को हटा देता है। यहाँ विवेकाधीन नीति ढीली हुई है, इसलिए घोषित घाटा छोटा होने पर भी रुख विस्तारकारी और अनुचक्रीय है।"},
  {"id":"eco-planning-budget-196","question":"In the IS–LM framework, an increase in government spending raises output the most when:","options":["The LM curve is vertical, because money demand does not depend on interest","The LM curve is horizontal, as in a liquidity trap","The IS curve is very flat, because investment is highly interest-sensitive","The central bank raises interest rates to keep the money supply fixed"],"answer":1,"explanation":"With a horizontal LM curve, interest rates do not rise as income rises, so there is no crowding out and the full multiplier works. With a vertical LM, crowding out is complete and output does not change.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"IS–LM ढाँचे में, सरकारी व्यय बढ़ने से उत्पादन सबसे अधिक कब बढ़ता है?","optionsHi":["जब LM वक्र ऊर्ध्वाधर हो, क्योंकि मुद्रा की मांग ब्याज पर निर्भर नहीं करती","जब LM वक्र क्षैतिज हो, जैसे तरलता जाल में","जब IS वक्र बहुत सपाट हो, क्योंकि निवेश ब्याज के प्रति अत्यधिक संवेदनशील है","जब केंद्रीय बैंक मुद्रा आपूर्ति स्थिर रखने के लिए ब्याज दरें बढ़ाता है"],"explanationHi":"क्षैतिज LM वक्र में आय बढ़ने पर ब्याज दरें नहीं बढ़तीं, इसलिए भीड़-बाह्यकरण नहीं होता और पूरा गुणक काम करता है। ऊर्ध्वाधर LM में भीड़-बाह्यकरण पूर्ण होता है और उत्पादन नहीं बदलता।"},
  {"id":"eco-planning-budget-197","question":"In the Union Government’s accounts, ‘public debt’ under the Consolidated Fund of India does NOT include:","options":["Dated securities sold to banks and other investors in the market","Treasury bills of 91, 182 and 364 days issued by the Centre","Loans taken from multilateral agencies such as the World Bank","Provident funds and small savings held in the Public Account"],"answer":3,"explanation":"Public debt covers internal debt (dated securities, Treasury bills and so on) and external debt raised against the Consolidated Fund. Provident funds, small savings and reserve funds are ‘other liabilities’ held in the Public Account.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"केंद्र सरकार के लेखों में, भारत की संचित निधि के अंतर्गत ‘सार्वजनिक ऋण’ में क्या शामिल नहीं है?","optionsHi":["बाज़ार में बैंकों और अन्य निवेशकों को बेची गई दिनांकित प्रतिभूतियाँ","केंद्र द्वारा जारी 91, 182 और 364 दिन के ट्रेज़री बिल","विश्व बैंक जैसी बहुपक्षीय एजेंसियों से लिए गए ऋण","लोक लेखा में रखी भविष्य निधियाँ और लघु बचत"],"explanationHi":"सार्वजनिक ऋण में आंतरिक ऋण (दिनांकित प्रतिभूतियाँ, ट्रेज़री बिल आदि) और संचित निधि के विरुद्ध जुटाया गया बाह्य ऋण आते हैं। भविष्य निधियाँ, लघु बचत और आरक्षित निधियाँ लोक लेखा में रखी ‘अन्य देनदारियाँ’ हैं।"},
  {"id":"eco-planning-budget-198","question":"In India, anti-dumping duty on imports is imposed by:","options":["The Ministry of Commerce, on the advice of the Department of Revenue","The Ministry of Finance, on the recommendation of the DGTR","The Central Board of Indirect Taxes, on the advice of the RBI","The GST Council, on the recommendation of the Ministry of Commerce"],"answer":1,"explanation":"The Directorate General of Trade Remedies, under the Commerce Ministry, investigates dumping and recommends a duty; the Ministry of Finance (Department of Revenue) decides and notifies it under the Customs Tariff Act.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"भारत में आयात पर पाटनरोधी शुल्क कौन लगाता है?","optionsHi":["वाणिज्य मंत्रालय, राजस्व विभाग की सलाह पर","वित्त मंत्रालय, DGTR की सिफारिश पर","केंद्रीय अप्रत्यक्ष कर बोर्ड, RBI की सलाह पर","GST परिषद, वाणिज्य मंत्रालय की सिफारिश पर"],"explanationHi":"वाणिज्य मंत्रालय के अधीन व्यापार उपचार महानिदेशालय (DGTR) पाटन की जाँच कर शुल्क की सिफारिश करता है; वित्त मंत्रालय (राजस्व विभाग) सीमा शुल्क टैरिफ अधिनियम के अंतर्गत इसका निर्णय लेकर इसे अधिसूचित करता है।"},
  {"id":"eco-planning-budget-199","question":"For a supplier dealing only in goods in most States, GST registration becomes compulsory once aggregate turnover in a financial year exceeds:","options":["₹10 lakh","₹20 lakh","₹75 lakh","₹40 lakh"],"answer":3,"explanation":"Since 2019 the threshold for suppliers of goods is ₹40 lakh in most States, while it is ₹20 lakh for service providers; lower limits apply in some special category States.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"अधिकांश राज्यों में केवल वस्तुओं के आपूर्तिकर्ता के लिए GST पंजीकरण तब अनिवार्य हो जाता है जब किसी वित्तीय वर्ष में कुल टर्नओवर किस सीमा से अधिक हो जाए?","optionsHi":["₹10 लाख","₹20 लाख","₹75 लाख","₹40 लाख"],"explanationHi":"2019 से वस्तुओं के आपूर्तिकर्ताओं के लिए अधिकांश राज्यों में सीमा ₹40 लाख है, जबकि सेवा प्रदाताओं के लिए ₹20 लाख; कुछ विशेष श्रेणी के राज्यों में कम सीमाएँ लागू हैं।"},
  {"id":"eco-planning-budget-200","question":"Which provision of the Constitution requires the Annual Financial Statement to show expenditure on revenue account separately from other expenditure?","options":["Article 112(2)","Article 113(1)","Article 114(3)","Article 266(1)"],"answer":0,"explanation":"Article 112(2) requires the estimates to show charged and voted expenditure separately and to distinguish revenue-account expenditure from other expenditure; this is the basis of the revenue–capital split.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संविधान का कौन-सा प्रावधान अपेक्षा करता है कि वार्षिक वित्तीय विवरण में राजस्व लेखे पर व्यय को अन्य व्यय से अलग दर्शाया जाए?","optionsHi":["अनुच्छेद 112(2)","अनुच्छेद 113(1)","अनुच्छेद 114(3)","अनुच्छेद 266(1)"],"explanationHi":"अनुच्छेद 112(2) अपेक्षा करता है कि प्राक्कलन भारित और मतदान वाले व्यय को अलग दिखाएँ और राजस्व लेखे के व्यय को अन्य व्यय से अलग करें; यही राजस्व–पूंजीगत विभाजन का आधार है।"},
  {"id":"eco-planning-budget-201","question":"Under Article 243ZD, at least what share of the members of a District Planning Committee must be elected by and from the elected members of the district-level Panchayat and the Municipalities in the district?","options":["One-half","Two-thirds","Three-fourths","Four-fifths"],"answer":3,"explanation":"Article 243ZD requires not less than four-fifths of DPC members to be so elected, in proportion to the rural and urban populations of the district. The DPC consolidates the plans of Panchayats and Municipalities.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 243ZD के अंतर्गत, जिला योजना समिति के कम से कम कितने हिस्से सदस्य जिले की जिला-स्तरीय पंचायत और नगरपालिकाओं के निर्वाचित सदस्यों में से और उनके द्वारा निर्वाचित होने चाहिए?","optionsHi":["एक-आधा","दो-तिहाई","तीन-चौथाई","चार-पंचमांश"],"explanationHi":"अनुच्छेद 243ZD के अनुसार DPC के कम से कम चार-पंचमांश सदस्य जिले की ग्रामीण और शहरी जनसंख्या के अनुपात में इस प्रकार निर्वाचित होने चाहिए। DPC पंचायतों और नगरपालिकाओं की योजनाओं को समेकित करती है।"},
  {"id":"eco-planning-budget-202","question":"Under the rationalisation of centrally sponsored schemes in 2016, the Centre–State funding ratio for ‘core’ schemes in the North-Eastern and Himalayan States is generally:","options":["60:40","75:25","90:10","100:0"],"answer":2,"explanation":"Core schemes are generally shared 60:40 with most States and 90:10 with the North-Eastern and Himalayan States; ‘core of the core’ schemes such as MGNREGA follow their own, more generous patterns.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2016 में केंद्र प्रायोजित योजनाओं के युक्तिकरण के अंतर्गत, पूर्वोत्तर और हिमालयी राज्यों में ‘कोर’ योजनाओं के लिए केंद्र–राज्य वित्तपोषण अनुपात सामान्यतः क्या है?","optionsHi":["60:40","75:25","90:10","100:0"],"explanationHi":"कोर योजनाएँ सामान्यतः अधिकांश राज्यों के साथ 60:40 और पूर्वोत्तर तथा हिमालयी राज्यों के साथ 90:10 में साझा होती हैं; MGNREGA जैसी ‘कोर ऑफ द कोर’ योजनाएँ अपने अलग, अधिक उदार ढंग का अनुसरण करती हैं।"},
  {"id":"eco-planning-budget-203","question":"In the run-up to GST, the ‘revenue neutral rate’ studied by the committee under Arvind Subramanian (2015) meant:","options":["The single rate at which GST would yield the revenue of the taxes it replaced","The lowest GST rate at which no good or service would remain wholly untaxed","The rate at which the Centre and the States would get exactly equal shares of GST","The rate that would leave consumer price inflation unchanged after GST came in"],"answer":0,"explanation":"The revenue neutral rate is the rate that keeps total revenue unchanged after the switch to GST. The committee used it to guide the standard rate, which then had to be set alongside lower and higher slabs.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"GST से पहले अरविंद सुब्रमणियन की अध्यक्षता वाली समिति (2015) द्वारा अध्ययन की गई ‘राजस्व तटस्थ दर’ का क्या अर्थ था?","optionsHi":["वह एकल दर जिस पर GST उन करों का राजस्व दे जिनका वह स्थान ले","सबसे कम GST दर जिस पर कोई वस्तु या सेवा पूरी तरह कर-मुक्त न रहे","वह दर जिस पर केंद्र और राज्यों को GST के बिल्कुल बराबर हिस्से मिलें","वह दर जो GST आने के बाद उपभोक्ता कीमत मुद्रास्फीति को अपरिवर्तित रखे"],"explanationHi":"राजस्व तटस्थ दर वह दर है जो GST में बदलाव के बाद कुल राजस्व को अपरिवर्तित रखती है। समिति ने इसका उपयोग मानक दर के मार्गदर्शन के लिए किया, जिसे फिर निचले और ऊँचे स्लैब के साथ तय करना था।"},
  {"id":"eco-planning-budget-204","question":"The Tax Administration Reform Commission, which reported in 2014 on reforming India’s tax departments, was chaired by:","options":["Vijay Kelkar","Raja Jesudoss Chelliah","Parthasarathi Shome","Arvind Subramanian"],"answer":2,"explanation":"The Commission set up in 2013 under Parthasarathi Shome studied the working of the direct and indirect tax administrations. Kelkar and Chelliah led earlier tax reform panels, and Subramanian the GST rate committee.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"कर प्रशासन सुधार आयोग, जिसने 2014 में भारत के कर विभागों में सुधार पर रिपोर्ट दी, की अध्यक्षता किसने की?","optionsHi":["विजय केलकर","राजा जेसुदास चेलैया","पार्थसारथी शोम","अरविंद सुब्रमणियन"],"explanationHi":"2013 में पार्थसारथी शोम की अध्यक्षता में गठित आयोग ने प्रत्यक्ष और अप्रत्यक्ष कर प्रशासनों के कामकाज का अध्ययन किया। केलकर और चेलैया ने पहले के कर सुधार पैनलों का और सुब्रमणियन ने GST दर समिति का नेतृत्व किया।"},
  {"id":"eco-planning-budget-205","question":"A government’s tax revenue grows by 12% in a year in which nominal GDP grows by 10%. New tax measures account for 4 percentage points of the revenue growth. Its tax buoyancy and tax elasticity are about:","options":["0.8 and 1.2","1.2 and 1.2","1.2 and 0.8","1.6 and 0.8"],"answer":2,"explanation":"Buoyancy uses total revenue growth: 12/10 = 1.2. Elasticity strips out discretionary changes: (12 − 4)/10 = 0.8. So without new measures, revenue would have lagged GDP.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"किसी सरकार का कर राजस्व एक वर्ष में 12% बढ़ता है जबकि सांकेतिक GDP 10% बढ़ती है। राजस्व वृद्धि के 4 प्रतिशत अंक नए कर उपायों के कारण हैं। उसकी कर उछाल और कर लोच लगभग कितनी हैं?","optionsHi":["0.8 और 1.2","1.2 और 1.2","1.2 और 0.8","1.6 और 0.8"],"explanationHi":"उछाल कुल राजस्व वृद्धि का प्रयोग करती है: 12/10 = 1.2। लोच विवेकाधीन परिवर्तनों को हटा देती है: (12 − 4)/10 = 0.8। अतः नए उपायों के बिना राजस्व GDP से पीछे रहता।"},
  {"id":"eco-planning-budget-206","question":"A dealer buys goods from another State for ₹1,00,000 plus 18% IGST and sells them within his own State for ₹1,50,000 plus 18% GST (CGST + SGST). After using input tax credit, how much GST in total must he pay in cash?","options":["₹27,000","₹13,500","₹4,500","₹9,000"],"answer":3,"explanation":"Output tax = 18% of 1,50,000 = ₹27,000; IGST credit of ₹18,000 can be set off against CGST and SGST, leaving ₹9,000. Paying only the CGST share of the margin (₹4,500) misses the SGST half.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक व्यापारी दूसरे राज्य से ₹1,00,000 जमा 18% IGST पर माल खरीदता है और उसे अपने ही राज्य में ₹1,50,000 जमा 18% GST (CGST + SGST) पर बेचता है। इनपुट टैक्स क्रेडिट के उपयोग के बाद उसे कुल कितना GST नकद चुकाना होगा?","optionsHi":["₹27,000","₹13,500","₹4,500","₹9,000"],"explanationHi":"आउटपुट कर = 1,50,000 का 18% = ₹27,000; ₹18,000 का IGST क्रेडिट CGST और SGST के विरुद्ध समायोजित हो सकता है, जिससे ₹9,000 बचता है। मार्जिन पर केवल CGST का हिस्सा (₹4,500) चुकाना SGST का आधा भाग छोड़ देना है।"},
  {"id":"eco-planning-budget-207","question":"The committee set up by the Union Government in 2016 to examine shifting India’s financial year from April–March to another period was headed by:","options":["Bimal Jalan","C. Rangarajan","Arvind Subramanian","Shankar Acharya"],"answer":3,"explanation":"Former Chief Economic Adviser Shankar Acharya headed the committee; Arvind Subramanian was the serving CEA at the time, a common confusion. Changing the year was discussed to match the budget cycle to the farm season, but the April–March year continues.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"भारत के वित्तीय वर्ष को अप्रैल–मार्च से किसी अन्य अवधि में बदलने की जाँच के लिए 2016 में केंद्र सरकार द्वारा गठित समिति की अध्यक्षता किसने की?","optionsHi":["बिमल जालान","सी. रंगराजन","अरविंद सुब्रमणियन","शंकर आचार्य"],"explanationHi":"पूर्व मुख्य आर्थिक सलाहकार शंकर आचार्य ने समिति का नेतृत्व किया; अरविंद सुब्रमणियन उस समय पदस्थ मुख्य आर्थिक सलाहकार थे, जो एक आम भ्रम है। वर्ष बदलने की चर्चा बजट चक्र को कृषि मौसम से मिलाने के लिए हुई थी, पर अप्रैल–मार्च वर्ष जारी है।"},
  {"id":"eco-planning-budget-208","question":"The colonial practice of presenting the Union Budget at 5 p.m. was changed to 11 a.m. with the Budget presented in:","options":["1991","1999","2001","2017"],"answer":1,"explanation":"Yashwant Sinha presented the Budget at 11 a.m. on 27 February 1999, ending a convention timed to suit London. In 2017 the date, not the time, was moved to 1 February.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"केंद्रीय बजट को शाम 5 बजे प्रस्तुत करने की औपनिवेशिक प्रथा बदलकर 11 बजे सुबह की गई, जब बजट किस वर्ष प्रस्तुत हुआ?","optionsHi":["1991","1999","2001","2017"],"explanationHi":"यशवंत सिन्हा ने 27 फरवरी 1999 को सुबह 11 बजे बजट प्रस्तुत किया, जिससे लंदन के समय के अनुकूल बनी परंपरा समाप्त हुई। 2017 में समय नहीं, तारीख को 1 फरवरी किया गया।"},
  {"id":"eco-planning-budget-209","question":"Guarantees given by the Government of India on loans raised by public sector enterprises are best described as:","options":["Part of the fiscal deficit in the year in which they are given","Capital expenditure, since they help public enterprises create assets","Revenue expenditure, since the borrower repays nothing to the government","Contingent liabilities that fall due only if the borrower defaults"],"answer":3,"explanation":"A guarantee does not involve spending when given, so it is not in the deficit, but it is a potential claim on the budget if the borrower fails to pay. That is why guarantees are disclosed and capped under fiscal rules.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"सार्वजनिक क्षेत्र के उद्यमों द्वारा जुटाए गए ऋणों पर भारत सरकार द्वारा दी गई प्रत्याभूतियों का सबसे उपयुक्त वर्णन क्या है?","optionsHi":["जिस वर्ष वे दी जाती हैं, उस वर्ष के राजकोषीय घाटे का भाग","पूंजीगत व्यय, क्योंकि वे सार्वजनिक उद्यमों को परिसंपत्तियाँ बनाने में मदद करती हैं","राजस्व व्यय, क्योंकि उधारकर्ता सरकार को कुछ नहीं चुकाता","आकस्मिक देनदारियाँ, जो केवल तब देय होती हैं जब उधारकर्ता चूक करे"],"explanationHi":"प्रत्याभूति देते समय कोई व्यय नहीं होता, इसलिए वह घाटे में नहीं आती, पर यदि उधारकर्ता भुगतान न करे तो वह बजट पर संभावित दावा है। इसीलिए प्रत्याभूतियाँ प्रकट की जाती हैं और राजकोषीय नियमों के अंतर्गत सीमित की जाती हैं।"},
  {"id":"eco-planning-budget-210","question":"Under Article 285, the property of the Union is exempt from:","options":["All State and local taxes, unless Parliament by law provides otherwise","Union taxes only, while taxes imposed by States and local bodies still apply","Taxes on income only, while taxes on property and goods still apply to it","Taxes of local bodies only, while taxes imposed by State legislatures apply"],"answer":0,"explanation":"Article 285 shields Union property from State and local taxes unless Parliament provides otherwise, so municipalities often get ‘service charges’ instead. Article 289 gives a matching shield to State property from Union taxes.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"अनुच्छेद 285 के अंतर्गत संघ की संपत्ति किससे मुक्त है?","optionsHi":["सभी राज्य और स्थानीय करों से, जब तक संसद कानून द्वारा अन्यथा उपबंध न करे","केवल संघ के करों से, जबकि राज्यों और स्थानीय निकायों द्वारा लगाए कर फिर भी लागू होते हैं","केवल आय पर करों से, जबकि संपत्ति और वस्तुओं पर कर उस पर फिर भी लागू होते हैं","केवल स्थानीय निकायों के करों से, जबकि राज्य विधानमंडलों द्वारा लगाए कर लागू होते हैं"],"explanationHi":"अनुच्छेद 285 संघ की संपत्ति को राज्य और स्थानीय करों से बचाता है, जब तक संसद अन्यथा उपबंध न करे; इसीलिए नगरपालिकाओं को प्रायः ‘सेवा शुल्क’ मिलते हैं। अनुच्छेद 289 राज्य की संपत्ति को संघ के करों से उसी प्रकार की सुरक्षा देता है।"},
  {"id":"eco-planning-budget-211","question":"The proviso to Article 275(1) provides grants from the Consolidated Fund of India to States specifically for:","options":["Meeting the revenue deficits that remain after tax devolution to the States","Compensating States for the revenue they lost when GST was introduced","Disaster relief routed through the State Disaster Response Funds","Tribal welfare schemes and better administration of Scheduled Areas"],"answer":3,"explanation":"Article 275(1) gives statutory grants to States in need, and its proviso adds grants for tribal welfare schemes and for raising the level of administration of Scheduled Areas. GST compensation came under a separate 2017 law.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 275(1) का परंतुक भारत की संचित निधि से राज्यों को विशेष रूप से किस हेतु अनुदान देता है?","optionsHi":["राज्यों को कर हस्तांतरण के बाद बचे राजस्व घाटों की पूर्ति","GST लागू होने पर राज्यों के खोए राजस्व की क्षतिपूर्ति","राज्य आपदा मोचन निधियों के माध्यम से आपदा राहत","जनजातीय कल्याण योजनाएँ और अनुसूचित क्षेत्रों का बेहतर प्रशासन"],"explanationHi":"अनुच्छेद 275(1) सहायता की आवश्यकता वाले राज्यों को सांविधिक अनुदान देता है, और इसका परंतुक जनजातीय कल्याण योजनाओं तथा अनुसूचित क्षेत्रों के प्रशासन का स्तर बढ़ाने हेतु अनुदान जोड़ता है। GST क्षतिपूर्ति 2017 के एक अलग कानून के अंतर्गत थी।"},
  {"id":"eco-planning-budget-212","question":"A ‘soft budget constraint’, a term coined by János Kornai, arises when:","options":["A government sets spending ceilings that it can legally relax during a recession","A household faces a budget line that shifts outward as its income rises","A central bank allows the government to overdraw its account for a few days","A loss-making firm expects a State bailout and so does little to control costs"],"answer":3,"explanation":"Kornai described firms in socialist economies, and later many public enterprises, whose losses were routinely covered by the State. Expecting bailouts weakens discipline, which is a key argument for hard budgets and disinvestment.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"जानोश कोर्नाई द्वारा गढ़ा गया शब्द ‘मृदु बजट बाधा’ (सॉफ्ट बजट कंस्ट्रेंट) कब उत्पन्न होता है?","optionsHi":["जब सरकार व्यय सीमाएँ तय करती है जिन्हें मंदी में वह कानूनन ढीला कर सकती है","जब किसी परिवार की बजट रेखा आय बढ़ने पर बाहर की ओर खिसकती है","जब केंद्रीय बैंक सरकार को कुछ दिनों के लिए अपने खाते से अधिक निकासी की अनुमति देता है","जब घाटे में चल रही फर्म राज्य से बचाव की अपेक्षा करती है और लागत नियंत्रण पर कम ध्यान देती है"],"explanationHi":"कोर्नाई ने समाजवादी अर्थव्यवस्थाओं की, और बाद में अनेक सार्वजनिक उद्यमों की, उन फर्मों का वर्णन किया जिनके घाटे राज्य नियमित रूप से पूरे करता था। बचाव की अपेक्षा अनुशासन कमज़ोर करती है, जो कठोर बजट और विनिवेश के पक्ष में प्रमुख तर्क है।"},
  {"id":"eco-planning-budget-213","question":"A government’s revenue receipts are ₹25 lakh crore and its interest payments equal 40% of revenue receipts. If its fiscal deficit is ₹16 lakh crore, its primary deficit is:","options":["₹10 lakh crore","₹9.6 lakh crore","₹6 lakh crore","₹26 lakh crore"],"answer":2,"explanation":"Interest = 0.4 × 25 = ₹10 lakh crore, so the primary deficit = 16 − 10 = ₹6 lakh crore. Taking 60% of the fiscal deficit (9.6) wrongly applies the interest share to the deficit.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"किसी सरकार की राजस्व प्राप्तियाँ ₹25 लाख करोड़ हैं और ब्याज भुगतान राजस्व प्राप्तियों के 40% के बराबर हैं। यदि उसका राजकोषीय घाटा ₹16 लाख करोड़ है, तो उसका प्राथमिक घाटा है:","optionsHi":["₹10 लाख करोड़","₹9.6 लाख करोड़","₹6 लाख करोड़","₹26 लाख करोड़"],"explanationHi":"ब्याज = 0.4 × 25 = ₹10 लाख करोड़, इसलिए प्राथमिक घाटा = 16 − 10 = ₹6 लाख करोड़। राजकोषीय घाटे का 60% (9.6) लेना गलत ढंग से ब्याज का हिस्सा घाटे पर लगाना है।"},
  {"id":"eco-planning-budget-214","question":"While the Planning Commission existed, the final approval of a draft Five-Year Plan before it was placed in Parliament was given by:","options":["The National Development Council","The Union Council of Ministers","The Finance Commission of India","The Inter-State Council (Art. 263)"],"answer":0,"explanation":"After the Planning Commission and the Union Cabinet had cleared the draft, the National Development Council (set up in 1952, with all Chief Ministers) gave the final approval. This gave States a voice in national planning.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"योजना आयोग के अस्तित्व के दौरान, किसी प्रारूप पंचवर्षीय योजना को संसद में रखे जाने से पहले उसका अंतिम अनुमोदन कौन करता था?","optionsHi":["राष्ट्रीय विकास परिषद","केंद्रीय मंत्रिपरिषद","भारत का वित्त आयोग","अंतर-राज्य परिषद (अनु. 263)"],"explanationHi":"योजना आयोग और केंद्रीय मंत्रिमंडल द्वारा प्रारूप को मंजूरी देने के बाद राष्ट्रीय विकास परिषद (1952 में स्थापित, सभी मुख्यमंत्रियों सहित) अंतिम अनुमोदन देती थी। इससे राज्यों को राष्ट्रीय नियोजन में अपनी बात रखने का अवसर मिला।"},
  {"id":"eco-planning-budget-215","question":"For which of these taxes do the impact and the incidence normally fall on the same person?","options":["Personal income tax","Customs duty on imported cars","GST on a packet of biscuits","Excise duty on cigarettes"],"answer":0,"explanation":"Personal income tax is paid by the person who bears it, so it cannot be shifted. Indirect taxes such as GST, customs and excise are paid by sellers or importers but are largely passed on to buyers.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"इनमें से किस कर के लिए प्रभाव और घटना (इन्सिडेंस) सामान्यतः एक ही व्यक्ति पर पड़ते हैं?","optionsHi":["व्यक्तिगत आयकर","आयातित कारों पर सीमा शुल्क","बिस्कुट के पैकेट पर GST","सिगरेट पर उत्पाद शुल्क"],"explanationHi":"व्यक्तिगत आयकर वही व्यक्ति चुकाता है जो उसका बोझ उठाता है, इसलिए इसे आगे नहीं खिसकाया जा सकता। GST, सीमा शुल्क और उत्पाद शुल्क जैसे अप्रत्यक्ष कर विक्रेता या आयातक चुकाते हैं, पर वे बहुत हद तक क्रेताओं पर डाल दिए जाते हैं।"},
  {"id":"eco-planning-budget-216","question":"The CAG’s audit reports on the accounts of the Union are submitted to:","options":["The Speaker of the Lok Sabha, who refers them to the PAC","The Union Finance Minister, who presents them with the Budget","The President, who causes them to be laid before Parliament","The Chairman of the Public Accounts Committee directly"],"answer":2,"explanation":"Under Article 151, the CAG submits Union audit reports to the President, who has them laid before each House; the Public Accounts Committee then examines them. State reports go to the Governor.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"संघ के लेखों पर CAG की लेखा परीक्षा रिपोर्टें किसे प्रस्तुत की जाती हैं?","optionsHi":["लोकसभा अध्यक्ष को, जो उन्हें PAC को भेजते हैं","केंद्रीय वित्त मंत्री को, जो उन्हें बजट के साथ प्रस्तुत करते हैं","राष्ट्रपति को, जो उन्हें संसद के समक्ष रखवाते हैं","लोक लेखा समिति के अध्यक्ष को सीधे"],"explanationHi":"अनुच्छेद 151 के अंतर्गत CAG संघ की लेखा परीक्षा रिपोर्टें राष्ट्रपति को सौंपता है, जो उन्हें प्रत्येक सदन के समक्ष रखवाते हैं; फिर लोक लेखा समिति उनकी जाँच करती है। राज्यों की रिपोर्टें राज्यपाल को जाती हैं।"},
  {"id":"eco-planning-budget-217","question":"A government’s fiscal deficit is ₹9 lakh crore and its revenue deficit ₹5 lakh crore. Its non-debt capital receipts are ₹1 lakh crore. Its capital expenditure is:","options":["₹4 lakh crore","₹5 lakh crore","₹3 lakh crore","₹14 lakh crore"],"answer":1,"explanation":"Fiscal deficit = revenue deficit + capital expenditure − non-debt capital receipts, so 9 = 5 + CE − 1 and CE = ₹5 lakh crore. Forgetting the non-debt receipts gives ₹4 lakh crore.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"किसी सरकार का राजकोषीय घाटा ₹9 लाख करोड़ और राजस्व घाटा ₹5 लाख करोड़ है। उसकी गैर-ऋण पूंजीगत प्राप्तियाँ ₹1 लाख करोड़ हैं। उसका पूंजीगत व्यय है:","optionsHi":["₹4 लाख करोड़","₹5 लाख करोड़","₹3 लाख करोड़","₹14 लाख करोड़"],"explanationHi":"राजकोषीय घाटा = राजस्व घाटा + पूंजीगत व्यय − गैर-ऋण पूंजीगत प्राप्तियाँ, इसलिए 9 = 5 + CE − 1 और CE = ₹5 लाख करोड़। गैर-ऋण प्राप्तियों को भूल जाने पर ₹4 लाख करोड़ आता है।"},
  {"id":"eco-planning-budget-218","question":"Fiscal consolidation is generally considered of better quality when the deficit is cut mainly by:","options":["Postponing capital expenditure on roads, railways and irrigation projects","Raising revenue and trimming current spending, not capital outlay","Deferring payments to suppliers and shifting borrowing to public enterprises","Selling government assets every year to meet recurring expenditure needs"],"answer":1,"explanation":"Cutting capital spending hurts future growth, and deferrals or off-budget borrowing only hide the deficit. Consolidation that comes from revenue gains and lower current spending lasts and protects growth.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"राजकोषीय समेकन को सामान्यतः बेहतर गुणवत्ता का तब माना जाता है जब घाटा मुख्यतः किसके द्वारा घटाया जाए?","optionsHi":["सड़कों, रेलवे और सिंचाई परियोजनाओं पर पूंजीगत व्यय को टालकर","राजस्व बढ़ाकर और चालू व्यय में कटौती करके, पूंजीगत परिव्यय में नहीं","आपूर्तिकर्ताओं को भुगतान टालकर और उधारी सार्वजनिक उद्यमों पर डालकर","आवर्ती व्यय की ज़रूरतें पूरी करने के लिए हर वर्ष सरकारी परिसंपत्तियाँ बेचकर"],"explanationHi":"पूंजीगत व्यय में कटौती भावी वृद्धि को हानि पहुँचाती है, और भुगतान टालना या ऑफ-बजट उधारी केवल घाटे को छिपाते हैं। राजस्व लाभ और कम चालू व्यय से आया समेकन टिकाऊ होता है और वृद्धि की रक्षा करता है।"},
  {"id":"eco-planning-budget-219","question":"Under Article 279A, the quorum for a meeting of the GST Council is:","options":["One-third of its total members","One-half of its total members","Two-thirds of its total members","Three-fourths of its total members"],"answer":1,"explanation":"Article 279A(7) fixes the quorum at one-half of the total members. Three-fourths is the weighted majority of members present and voting that a decision needs.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"अनुच्छेद 279A के अंतर्गत GST परिषद की बैठक के लिए गणपूर्ति (कोरम) कितनी है?","optionsHi":["कुल सदस्यों का एक-तिहाई","कुल सदस्यों का आधा","कुल सदस्यों का दो-तिहाई","कुल सदस्यों का तीन-चौथाई"],"explanationHi":"अनुच्छेद 279A(7) गणपूर्ति कुल सदस्यों का आधा तय करता है। तीन-चौथाई उपस्थित और मतदान करने वाले सदस्यों के भारित बहुमत की वह सीमा है जो किसी निर्णय के लिए आवश्यक है।"},
  {"id":"eco-planning-budget-220","question":"How many of these statements about the GST Council are correct? I. The Union Minister of State in charge of Revenue or Finance is a member. II. Its Vice-Chairperson is chosen from among the State ministers who are members. III. It may recommend a special rate for a specified period to raise resources during a natural calamity. IV. Its decisions need a majority of at least three-fourths of the weighted votes of members present and voting.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four follow Article 279A: the Union MoS for Revenue or Finance is a member, the Vice-Chairperson is chosen from State ministers, it may recommend a special calamity rate, and decisions need a three-fourths weighted majority.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"GST परिषद के बारे में इनमें से कितने कथन सही हैं? I. राजस्व या वित्त के प्रभारी केंद्रीय राज्य मंत्री इसके सदस्य हैं। II. इसका उपाध्यक्ष सदस्य राज्य मंत्रियों में से चुना जाता है। III. यह प्राकृतिक आपदा के दौरान संसाधन जुटाने के लिए निर्दिष्ट अवधि हेतु विशेष दर की सिफारिश कर सकती है। IV. इसके निर्णयों के लिए उपस्थित और मतदान करने वाले सदस्यों के भारित मतों का कम से कम तीन-चौथाई बहुमत आवश्यक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों अनुच्छेद 279A से निकलते हैं: राजस्व या वित्त के केंद्रीय राज्य मंत्री सदस्य हैं, उपाध्यक्ष राज्य मंत्रियों में से चुना जाता है, यह विशेष आपदा दर की सिफारिश कर सकती है, और निर्णयों के लिए तीन-चौथाई भारित बहुमत चाहिए।"},
  {"id":"eco-planning-budget-221","question":"The nationalisation of 14 major commercial banks in July 1969 took place during which plan period?","options":["The Third Five-Year Plan","The Annual Plans (Plan Holiday)","The Fourth Five-Year Plan","The Fifth Five-Year Plan"],"answer":2,"explanation":"The Fourth Plan began in April 1969, three months before the banks were nationalised on 19 July 1969. The Plan Holiday covered 1966–69, and six more banks were nationalised in 1980, during the Sixth Plan.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"जुलाई 1969 में 14 प्रमुख वाणिज्यिक बैंकों का राष्ट्रीयकरण किस योजना काल में हुआ?","optionsHi":["तीसरी पंचवर्षीय योजना","वार्षिक योजनाएँ (योजना अवकाश)","चौथी पंचवर्षीय योजना","पाँचवीं पंचवर्षीय योजना"],"explanationHi":"चौथी योजना अप्रैल 1969 में शुरू हुई, बैंकों के 19 जुलाई 1969 को राष्ट्रीयकरण से तीन महीने पहले। योजना अवकाश 1966–69 को घेरता है, और 1980 में, छठी योजना के दौरान, छह और बैंकों का राष्ट्रीयकरण हुआ।"},
  {"id":"eco-planning-budget-222","question":"Which Five-Year Plan comfortably beat its modest growth target of about 2.1% a year, helped by good harvests?","options":["The First Plan","The Second Plan","The Third Plan","The Fourth Plan"],"answer":0,"explanation":"The First Plan (1951–56), focused on agriculture and irrigation, achieved growth of about 3.6% against a target of 2.1%. The Third Plan, by contrast, fell badly short because of wars and drought.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"किस पंचवर्षीय योजना ने अच्छी फसलों की मदद से लगभग 2.1% वार्षिक के अपने मामूली वृद्धि लक्ष्य को आराम से पार कर लिया?","optionsHi":["प्रथम योजना","द्वितीय योजना","तीसरी योजना","चौथी योजना"],"explanationHi":"कृषि और सिंचाई पर केंद्रित प्रथम योजना (1951–56) ने 2.1% के लक्ष्य के मुकाबले लगभग 3.6% की वृद्धि हासिल की। इसके विपरीत, तीसरी योजना युद्धों और सूखे के कारण बुरी तरह पीछे रह गई।"},
  {"id":"eco-planning-budget-223","question":"In public finance, ‘fiscal marksmanship’ refers to:","options":["The ability of tax officials to target evaders with data analytics","The accuracy of budget estimates compared with the actual outcomes","The success of a government in meeting its FRBM deficit targets","The precision with which subsidies reach the intended beneficiaries"],"answer":1,"explanation":"Fiscal marksmanship measures how close budget estimates of receipts and spending come to actuals; large gaps weaken the credibility of the budget. Meeting deficit targets and targeting subsidies are different issues.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"लोक वित्त में ‘राजकोषीय निशानेबाज़ी’ (फिस्कल मार्क्समैनशिप) से क्या तात्पर्य है?","optionsHi":["कर अधिकारियों की डेटा विश्लेषण से कर चोरों को निशाना बनाने की क्षमता","बजट अनुमानों की वास्तविक परिणामों की तुलना में सटीकता","FRBM घाटा लक्ष्य पूरे करने में सरकार की सफलता","वह सटीकता जिससे सब्सिडी इच्छित लाभार्थियों तक पहुँचती है"],"explanationHi":"राजकोषीय निशानेबाज़ी मापती है कि प्राप्तियों और व्यय के बजट अनुमान वास्तविक आँकड़ों के कितने निकट आते हैं; बड़े अंतर बजट की विश्वसनीयता कमज़ोर करते हैं। घाटा लक्ष्य पूरे करना और सब्सिडी का लक्ष्यीकरण अलग मुद्दे हैं।"},
  {"id":"eco-planning-budget-224","question":"When the Union Budget for the coming year is presented on 1 February, the figures shown for the financial year that is then ending are:","options":["Actuals","Budget Estimates","Provisional Actuals","Revised Estimates"],"answer":3,"explanation":"Each Budget shows Actuals for the year before last, Budget and Revised Estimates for the current year, and Budget Estimates for the next year. Since the current year is not over, only revised estimates are available for it.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"जब आगामी वर्ष का केंद्रीय बजट 1 फरवरी को प्रस्तुत होता है, तब समाप्त हो रहे वित्तीय वर्ष के लिए दर्शाए गए आँकड़े होते हैं:","optionsHi":["वास्तविक आँकड़े","बजट अनुमान","अनंतिम वास्तविक आँकड़े","संशोधित अनुमान"],"explanationHi":"हर बजट पिछले से पिछले वर्ष के वास्तविक आँकड़े, चालू वर्ष के बजट और संशोधित अनुमान, और अगले वर्ष के बजट अनुमान दर्शाता है। चालू वर्ष समाप्त नहीं हुआ होता, इसलिए उसके लिए केवल संशोधित अनुमान उपलब्ध होते हैं।"},
  {"id":"eco-planning-budget-225","question":"In studies of Indian subsidies, those on elementary education, primary health and sanitation are usually classed as:","options":["Merit subsidies, as their benefits spread beyond the user","Non-merit subsidies, because they go to private consumption","Hidden subsidies, because they are not shown in the budget","Cross-subsidies, because richer users pay for poorer ones"],"answer":0,"explanation":"Merit subsidies support goods with large external benefits that the market would under-supply. Subsidies on goods with mainly private benefits, such as many fuel and power subsidies, are classed as non-merit.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"भारतीय सब्सिडियों के अध्ययनों में प्रारंभिक शिक्षा, प्राथमिक स्वास्थ्य और स्वच्छता पर सब्सिडियाँ सामान्यतः किस श्रेणी की मानी जाती हैं?","optionsHi":["योग्यता (मेरिट) सब्सिडी, क्योंकि उनके लाभ उपयोगकर्ता से आगे तक फैलते हैं","गैर-योग्यता सब्सिडी, क्योंकि वे निजी उपभोग को जाती हैं","छिपी सब्सिडी, क्योंकि वे बजट में नहीं दिखाई जातीं","क्रॉस-सब्सिडी, क्योंकि धनी उपयोगकर्ता गरीबों के लिए भुगतान करते हैं"],"explanationHi":"योग्यता सब्सिडियाँ उन वस्तुओं को सहारा देती हैं जिनके बड़े बाह्य लाभ हैं और जिनकी बाज़ार कम आपूर्ति करेगा। मुख्यतः निजी लाभ वाली वस्तुओं पर सब्सिडियाँ, जैसे अनेक ईंधन और बिजली सब्सिडियाँ, गैर-योग्यता मानी जाती हैं।"},
  {"id":"eco-planning-budget-226","question":"A government taxes tobacco heavily partly because people tend to underestimate its harm to their own health. Here tobacco is being treated as a:","options":["Public good","Inferior good","Demerit good","Giffen good"],"answer":2,"explanation":"Demerit goods are those whose consumption the State discourages because people undervalue the harm to themselves; ‘sin taxes’ follow from this. A Pigouvian tax, by contrast, targets harm done to others.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"कोई सरकार तंबाकू पर भारी कर इसलिए भी लगाती है कि लोग अपने स्वास्थ्य को होने वाली इसकी हानि को कम आँकते हैं। यहाँ तंबाकू को किस रूप में माना जा रहा है?","optionsHi":["सार्वजनिक वस्तु","निम्नस्तरीय वस्तु","अवगुण वस्तु (डिमेरिट गुड)","गिफ़िन वस्तु"],"explanationHi":"अवगुण वस्तुएँ वे हैं जिनके उपभोग को राज्य हतोत्साहित करता है क्योंकि लोग स्वयं को होने वाली हानि का कम मूल्यांकन करते हैं; ‘पाप कर’ इसी से निकलते हैं। इसके विपरीत, पिगूवियन कर दूसरों को होने वाली हानि को लक्षित करता है।"},
  {"id":"eco-planning-budget-227","question":"The ‘free-rider problem’ explains why markets tend to under-provide:","options":["Goods whose prices are fixed by the government below cost","Goods that are rival and excludable, such as food grains","Goods produced by monopolies with very high fixed costs","Goods people can use without paying, like street lights"],"answer":3,"explanation":"When people cannot be excluded, each hopes to benefit from others’ payments, so private sellers cannot cover costs and the good is under-supplied. That is the case for public provision paid for by taxes.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"‘मुफ़्तखोर समस्या’ (फ्री-राइडर प्रॉब्लम) यह समझाती है कि बाज़ार किन वस्तुओं की कम आपूर्ति करते हैं?","optionsHi":["वे वस्तुएँ जिनकी कीमतें सरकार लागत से कम पर तय करती है","वे वस्तुएँ जो प्रतिस्पर्धी और अपवर्जनीय हैं, जैसे खाद्यान्न","वे वस्तुएँ जो बहुत ऊँची स्थिर लागत वाले एकाधिकारियों द्वारा बनाई जाती हैं","वे वस्तुएँ जिन्हें लोग बिना भुगतान किए उपयोग कर सकते हैं, जैसे सड़क की बत्तियाँ"],"explanationHi":"जब लोगों को बाहर नहीं रखा जा सकता, तो हर कोई दूसरों के भुगतान से लाभ की आशा करता है, इसलिए निजी विक्रेता लागत नहीं निकाल पाते और वस्तु की कम आपूर्ति होती है। यही कर से वित्तपोषित सार्वजनिक आपूर्ति का आधार है।"},
  {"id":"eco-planning-budget-228","question":"A toll on a highway, paid only by the vehicles that use it, follows the:","options":["Ability-to-pay principle","Benefit principle","Principle of vertical equity","Principle of tax neutrality"],"answer":1,"explanation":"Under the benefit principle, people pay in proportion to the benefit they get from a public service, as toll payers do. The ability-to-pay principle links tax to income or wealth instead.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"राजमार्ग पर टोल, जो केवल उसका उपयोग करने वाले वाहन चुकाते हैं, किस सिद्धांत का अनुसरण करता है?","optionsHi":["भुगतान-क्षमता सिद्धांत","लाभ सिद्धांत","ऊर्ध्वाधर समता का सिद्धांत","कर तटस्थता का सिद्धांत"],"explanationHi":"लाभ सिद्धांत के अनुसार लोग किसी सार्वजनिक सेवा से मिलने वाले लाभ के अनुपात में भुगतान करते हैं, जैसा टोल देने वाले करते हैं। भुगतान-क्षमता सिद्धांत कर को आय या संपत्ति से जोड़ता है।"},
  {"id":"eco-planning-budget-229","question":"Wealth tax was abolished in India by the Budget of:","options":["2005–06","2010–11","2017–18","2015–16"],"answer":3,"explanation":"The 2015–16 Budget abolished wealth tax, which cost more to collect than it raised, and replaced it with a higher surcharge on the incomes of the very rich.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"भारत में संपत्ति कर किस बजट द्वारा समाप्त किया गया?","optionsHi":["2005–06","2010–11","2017–18","2015–16"],"explanationHi":"2015–16 के बजट ने संपत्ति कर समाप्त किया, जिसकी वसूली लागत उससे होने वाली प्राप्ति से अधिक थी, और उसकी जगह अत्यंत धनी लोगों की आय पर अधिक अधिभार लगाया।"},
  {"id":"eco-planning-budget-230","question":"Arrange the abolition of these taxes in time order: 1. Wealth tax  2. Estate duty  3. Fringe benefit tax  4. Gift tax","options":["2, 4, 3, 1","4, 2, 3, 1","2, 4, 1, 3","2, 3, 4, 1"],"answer":0,"explanation":"Estate duty went in 1985, gift tax in 1998, fringe benefit tax (brought in in 2005) in 2009, and wealth tax with the 2015–16 Budget.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"इन करों की समाप्ति को कालक्रम से व्यवस्थित कीजिए: 1. संपत्ति कर  2. संपदा शुल्क  3. फ्रिंज बेनिफिट कर  4. उपहार कर","optionsHi":["2, 4, 3, 1","4, 2, 3, 1","2, 4, 1, 3","2, 3, 4, 1"],"explanationHi":"संपदा शुल्क 1985 में, उपहार कर 1998 में, फ्रिंज बेनिफिट कर (2005 में लाया गया) 2009 में, और संपत्ति कर 2015–16 के बजट के साथ समाप्त हुए।"},
  {"id":"eco-planning-budget-231","question":"Under the corporate tax reform of 2019, existing domestic companies that give up specified exemptions and incentives may pay income tax at a base rate of:","options":["15%","25%","22%","30%"],"answer":2,"explanation":"Section 115BAA offered a 22% base rate to domestic companies forgoing exemptions; 15% was offered under Section 115BAB to new manufacturing companies, and 25% and 30% were the earlier rates.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"2019 के कॉर्पोरेट कर सुधार के अंतर्गत, निर्दिष्ट छूटें और प्रोत्साहन छोड़ने वाली मौजूदा घरेलू कंपनियाँ किस आधार दर पर आयकर चुका सकती हैं?","optionsHi":["15%","25%","22%","30%"],"explanationHi":"धारा 115BAA ने छूटें छोड़ने वाली घरेलू कंपनियों को 22% आधार दर दी; धारा 115BAB के अंतर्गत नई विनिर्माण कंपनियों को 15% दी गई, और 25% तथा 30% पहले की दरें थीं।"},
  {"id":"eco-planning-budget-232","question":"A hotel in Goa lets a room to a business guest whose company is registered in Delhi. Which GST applies to the room charges?","options":["CGST and SGST of Goa, as the place of supply is the hotel’s location","IGST, because the supplier and the recipient are in different States","CGST and SGST of Delhi, because the recipient is registered there","IGST, split equally between the governments of Goa and Delhi"],"answer":0,"explanation":"For services tied to immovable property, such as accommodation, the place of supply is the location of the property. Since supplier and place of supply are both in Goa, it is an intra-State supply attracting CGST and Goa SGST.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"गोवा का एक होटल किसी व्यावसायिक अतिथि को कमरा किराये पर देता है जिसकी कंपनी दिल्ली में पंजीकृत है। कमरे के शुल्क पर कौन-सा GST लगेगा?","optionsHi":["गोवा का CGST और SGST, क्योंकि आपूर्ति का स्थान होटल का स्थान है","IGST, क्योंकि आपूर्तिकर्ता और प्राप्तकर्ता अलग-अलग राज्यों में हैं","दिल्ली का CGST और SGST, क्योंकि प्राप्तकर्ता वहाँ पंजीकृत है","IGST, जो गोवा और दिल्ली की सरकारों में बराबर बँटेगा"],"explanationHi":"अचल संपत्ति से जुड़ी सेवाओं, जैसे आवास, के लिए आपूर्ति का स्थान संपत्ति का स्थान होता है। चूँकि आपूर्तिकर्ता और आपूर्ति का स्थान दोनों गोवा में हैं, यह अंतः-राज्यीय आपूर्ति है जिस पर CGST और गोवा का SGST लगता है।"},
  {"id":"eco-planning-budget-233","question":"Under GST, imports of goods into India are treated as:","options":["Exempt supplies, as customs duty already applies","Supplies in the course of inter-State trade, attracting IGST","Intra-State supplies, attracting CGST and SGST of the port State","Zero-rated supplies, with a refund of input tax credit"],"answer":1,"explanation":"The Constitution treats imports as inter-State supplies, so IGST is collected along with basic customs duty and its credit flows to the importer; it is zero-rating that applies to exports.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"GST के अंतर्गत भारत में वस्तुओं के आयात को किस रूप में माना जाता है?","optionsHi":["छूट प्राप्त आपूर्तियाँ, क्योंकि सीमा शुल्क पहले से लगता है","अंतर-राज्यीय व्यापार के क्रम में आपूर्तियाँ, जिन पर IGST लगता है","अंतः-राज्यीय आपूर्तियाँ, जिन पर बंदरगाह वाले राज्य का CGST और SGST लगता है","शून्य-दर आपूर्तियाँ, जिनमें इनपुट टैक्स क्रेडिट की वापसी होती है"],"explanationHi":"संविधान आयात को अंतर-राज्यीय आपूर्ति मानता है, इसलिए मूल सीमा शुल्क के साथ IGST वसूला जाता है और उसका क्रेडिट आयातक को मिलता है; शून्य-दर निर्यात पर लागू होती है।"},
  {"id":"eco-planning-budget-234","question":"A government is said to be falling into a ‘debt trap’ when:","options":["It borrows mainly to pay interest on old debt, so its debt snowballs","Its debt is held mostly by foreign investors who can pull out suddenly","It borrows at fixed rates just before market interest rates fall","Its revenue deficit is zero but its fiscal deficit stays positive"],"answer":0,"explanation":"In a debt trap, fresh borrowing goes largely into interest payments, so debt keeps rising faster than revenue and GDP. A zero revenue deficit with a fiscal deficit means borrowing goes to capital spending, a healthier case.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"किसी सरकार के ‘ऋण जाल’ में फँसने की बात तब कही जाती है जब:","optionsHi":["वह मुख्यतः पुराने ऋण पर ब्याज चुकाने के लिए उधार लेती है, जिससे उसका ऋण बर्फ के गोले की तरह बढ़ता है","उसका ऋण अधिकांशतः विदेशी निवेशकों के पास है जो अचानक पैसा निकाल सकते हैं","वह बाज़ार ब्याज दरें गिरने से ठीक पहले स्थिर दरों पर उधार लेती है","उसका राजस्व घाटा शून्य है पर राजकोषीय घाटा धनात्मक बना रहता है"],"explanationHi":"ऋण जाल में नई उधारी का बड़ा भाग ब्याज भुगतान में जाता है, इसलिए ऋण राजस्व और GDP से तेज़ बढ़ता रहता है। राजकोषीय घाटे के साथ शून्य राजस्व घाटे का अर्थ है कि उधारी पूंजीगत व्यय में जाती है, जो अधिक स्वस्थ स्थिति है।"},
  {"id":"eco-planning-budget-235","question":"In the Seventh Schedule, the subject ‘Economic and social planning’ is placed in the:","options":["Union List","State List","Eleventh Schedule only","Concurrent List"],"answer":3,"explanation":"It is Entry 20 of the Concurrent List, so both the Union and the States can plan. The Planning Commission and NITI Aayog were both set up by executive resolution, not by law under this entry.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सातवीं अनुसूची में ‘आर्थिक और सामाजिक योजना’ विषय किस सूची में रखा गया है?","optionsHi":["संघ सूची","राज्य सूची","केवल ग्यारहवीं अनुसूची","समवर्ती सूची"],"explanationHi":"यह समवर्ती सूची की प्रविष्टि 20 है, इसलिए संघ और राज्य दोनों योजना बना सकते हैं। योजना आयोग और नीति आयोग दोनों कार्यकारी संकल्प से बने थे, इस प्रविष्टि के अंतर्गत किसी कानून से नहीं।"},
  {"id":"eco-planning-budget-236","question":"For an individual who also has non-agricultural income, agricultural income under the Income-tax Act is:","options":["Taxed by the Union at the same slab rates as all other income it earns","Exempt, but counted to fix the tax rate on the non-agricultural income","Exempt, and left out completely when the person’s tax is worked out","Taxed by the Union at a lower flat rate than the person’s other income"],"answer":1,"explanation":"Taxing agricultural income is a State subject, so the Union exempts it, but under ‘partial integration’ it is added to compute the rate applicable to the non-agricultural income, which pushes that income into higher slabs.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"जिस व्यक्ति की गैर-कृषि आय भी है, उसके लिए आयकर अधिनियम के अंतर्गत कृषि आय:","optionsHi":["संघ द्वारा उसकी अन्य सभी आय के समान स्लैब दरों पर कर-योग्य है","मुक्त है, पर गैर-कृषि आय पर कर की दर तय करने के लिए गिनी जाती है","मुक्त है, और व्यक्ति का कर निकालते समय पूरी तरह छोड़ दी जाती है","संघ द्वारा उसकी अन्य आय से कम एकसमान दर पर कर-योग्य है"],"explanationHi":"कृषि आय पर कर राज्य का विषय है, इसलिए संघ इसे मुक्त रखता है, पर ‘आंशिक एकीकरण’ के अंतर्गत इसे गैर-कृषि आय पर लागू दर निकालने के लिए जोड़ा जाता है, जिससे वह आय ऊँचे स्लैब में चली जाती है।"},
  {"id":"eco-planning-budget-237","question":"Securities issued under the Market Stabilisation Scheme (MSS), introduced in 2004:","options":["Are sold by the RBI from its own stock to finance the government’s fiscal deficit","Are issued by the State governments to fund schemes that stabilise farm prices","Are issued by banks to the RBI to meet their statutory liquidity ratio needs","Are government securities issued to absorb surplus liquidity, proceeds unspent"],"answer":3,"explanation":"MSS bonds are government securities issued to sterilise liquidity, mainly from capital inflows. The proceeds sit in a separate account with the RBI and do not fund spending, so only the interest cost affects the budget.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"2004 में शुरू की गई बाज़ार स्थिरीकरण योजना (MSS) के अंतर्गत जारी प्रतिभूतियाँ:","optionsHi":["RBI अपने भंडार से सरकार के राजकोषीय घाटे के वित्तपोषण हेतु बेचता है","राज्य सरकारें कृषि मूल्य स्थिर करने वाली योजनाओं के वित्तपोषण हेतु जारी करती हैं","बैंक अपनी सांविधिक तरलता अनुपात की ज़रूरतें पूरी करने के लिए RBI को जारी करते हैं","अतिरिक्त तरलता सोखने के लिए जारी सरकारी प्रतिभूतियाँ हैं, जिनकी आय खर्च नहीं होती"],"explanationHi":"MSS बॉन्ड मुख्यतः पूंजी प्रवाह से उत्पन्न तरलता को निष्प्रभावी करने के लिए जारी सरकारी प्रतिभूतियाँ हैं। आय RBI के पास अलग खाते में रहती है और व्यय को वित्त नहीं देती, इसलिए बजट पर केवल ब्याज की लागत असर डालती है।"},
  {"id":"eco-planning-budget-238","question":"The term ‘Hindu rate of growth’, used for India’s slow growth of about 3.5% a year from the 1950s to the 1970s, was coined by:","options":["Jagdish Bhagwati","Raj Krishna","Amartya Sen","K. N. Raj"],"answer":1,"explanation":"Economist Raj Krishna coined the phrase to describe persistently low growth under the planned, controlled economy. Bhagwati was a leading critic of the licence regime but did not coin the term.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"‘हिंदू वृद्धि दर’ शब्द, जो 1950 के दशक से 1970 के दशक तक भारत की लगभग 3.5% वार्षिक की धीमी वृद्धि के लिए प्रयुक्त हुआ, किसने गढ़ा?","optionsHi":["जगदीश भगवती","राज कृष्ण","अमर्त्य सेन","के. एन. राज"],"explanationHi":"अर्थशास्त्री राज कृष्ण ने नियोजित, नियंत्रित अर्थव्यवस्था में लगातार कम वृद्धि का वर्णन करने के लिए यह वाक्यांश गढ़ा। भगवती लाइसेंस व्यवस्था के प्रमुख आलोचक थे, पर उन्होंने यह शब्द नहीं गढ़ा।"},
  {"id":"eco-planning-budget-239","question":"The Union’s gross tax revenue is ₹35 lakh crore, of which ₹5 lakh crore comes from cesses and surcharges; ignore the cost of collection. If the States’ share of the divisible pool is 41% and one State’s share of that is 4%, the State receives about:","options":["₹57,400 crore","₹1,20,000 crore","₹49,200 crore","₹50,400 crore"],"answer":2,"explanation":"Cesses and surcharges are outside the divisible pool, so the pool is ₹30 lakh crore; 41% of it is ₹12.3 lakh crore and 4% of that is ₹49,200 crore. Using the gross ₹35 lakh crore gives ₹57,400 crore.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"केंद्र का सकल कर राजस्व ₹35 लाख करोड़ है, जिसमें ₹5 लाख करोड़ उपकरों और अधिभारों से आता है; संग्रह की लागत को नज़रअंदाज़ कीजिए। यदि विभाज्य पूल में राज्यों का हिस्सा 41% है और उसमें किसी एक राज्य का हिस्सा 4% है, तो वह राज्य लगभग कितना पाता है?","optionsHi":["₹57,400 करोड़","₹1,20,000 करोड़","₹49,200 करोड़","₹50,400 करोड़"],"explanationHi":"उपकर और अधिभार विभाज्य पूल से बाहर हैं, इसलिए पूल ₹30 लाख करोड़ है; उसका 41% ₹12.3 लाख करोड़ है और उसका 4% ₹49,200 करोड़ है। सकल ₹35 लाख करोड़ लेने पर ₹57,400 करोड़ आता है।"},
  {"id":"eco-planning-budget-240","question":"A per-unit tax of ₹8 is levied on a good. Near the market equilibrium the price elasticity of supply is 1.5 and of demand −0.5. By about how much does the price paid by buyers rise?","options":["₹2","₹4","₹8","₹6"],"answer":3,"explanation":"Buyers’ share of the tax = Es/(Es + |Ed|) = 1.5/2 = 75%, so their price rises by ₹6 and sellers bear ₹2. The less elastic side of the market bears more of the tax.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"किसी वस्तु पर ₹8 प्रति इकाई कर लगाया जाता है। बाज़ार संतुलन के निकट आपूर्ति की कीमत लोच 1.5 और मांग की −0.5 है। क्रेताओं द्वारा चुकाई कीमत लगभग कितनी बढ़ती है?","optionsHi":["₹2","₹4","₹8","₹6"],"explanationHi":"क्रेताओं का कर में हिस्सा = Es/(Es + |Ed|) = 1.5/2 = 75%, इसलिए उनकी कीमत ₹6 बढ़ती है और विक्रेता ₹2 वहन करते हैं। बाज़ार का कम लोचदार पक्ष कर का अधिक बोझ उठाता है।"},
  {"id":"eco-planning-budget-241","question":"A government’s debt is 80% of GDP and the average interest rate on it is 7.5%. If its fiscal deficit is 5% of GDP, its primary balance is:","options":["A primary deficit of 1% of GDP","A primary surplus of 1% of GDP","A primary deficit of 5% of GDP","A primary deficit of 11% of GDP"],"answer":1,"explanation":"Interest = 0.075 × 80 = 6% of GDP, which exceeds the 5% fiscal deficit, so the primary balance is a surplus of 1% of GDP. Its whole deficit is due to past debt.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"किसी सरकार का ऋण GDP का 80% है और उस पर औसत ब्याज दर 7.5% है। यदि उसका राजकोषीय घाटा GDP का 5% है, तो उसका प्राथमिक शेष है:","optionsHi":["GDP का 1% प्राथमिक घाटा","GDP का 1% प्राथमिक अधिशेष","GDP का 5% प्राथमिक घाटा","GDP का 11% प्राथमिक घाटा"],"explanationHi":"ब्याज = 0.075 × 80 = GDP का 6%, जो 5% राजकोषीय घाटे से अधिक है, इसलिए प्राथमिक शेष GDP के 1% का अधिशेष है। उसका पूरा घाटा पिछले ऋण के कारण है।"},
  {"id":"eco-planning-budget-242","question":"The Integrated Rural Development Programme, after pilots in the late 1970s, was extended to all blocks of the country during the:","options":["Fourth Plan","Fifth Plan","Sixth Plan","Eighth Plan"],"answer":2,"explanation":"IRDP was extended nationwide on 2 October 1980, at the start of the Sixth Plan (1980–85), whose central aim was the removal of poverty. In 1999 it was merged into the Swarnjayanti Gram Swarozgar Yojana.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"एकीकृत ग्रामीण विकास कार्यक्रम, 1970 के दशक के अंत में प्रायोगिक चरणों के बाद, देश के सभी खंडों तक किस योजना के दौरान विस्तारित किया गया?","optionsHi":["चौथी योजना","पाँचवीं योजना","छठी योजना","आठवीं योजना"],"explanationHi":"IRDP को 2 अक्टूबर 1980 को, छठी योजना (1980–85) के आरंभ में, पूरे देश में विस्तारित किया गया, जिसका केंद्रीय लक्ष्य गरीबी उन्मूलन था। 1999 में इसे स्वर्णजयंती ग्राम स्वरोजगार योजना में मिला दिया गया।"},
  {"id":"eco-planning-budget-243","question":"Under the ‘rule of lapse’ in government budgeting, money voted for a year that remains unspent on 31 March:","options":["Is carried forward automatically to the same scheme next year","Is transferred to the Contingency Fund of India for later use","Lapses and can be spent later only with fresh authorisation","Is credited to the Public Account as a reserve for that ministry"],"answer":2,"explanation":"Grants are valid only for the year, so unspent balances lapse to the Consolidated Fund. This is one cause of the ‘March rush’ of spending that the Public Accounts Committee has often criticised.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"सरकारी बजटिंग में ‘व्यपगत (लैप्स) के नियम’ के अनुसार, किसी वर्ष के लिए स्वीकृत जो धन 31 मार्च को खर्च नहीं हुआ होता है:","optionsHi":["अगले वर्ष उसी योजना के लिए स्वतः आगे ले जाया जाता है","बाद के उपयोग के लिए भारत की आकस्मिकता निधि में अंतरित हो जाता है","व्यपगत हो जाता है और बाद में केवल नए प्राधिकार से ही खर्च हो सकता है","उस मंत्रालय के लिए आरक्षित निधि के रूप में लोक लेखा में जमा हो जाता है"],"explanationHi":"अनुदान केवल उसी वर्ष के लिए मान्य होते हैं, इसलिए अव्ययित शेष संचित निधि में व्यपगत हो जाते हैं। यही खर्च की ‘मार्च भागदौड़’ का एक कारण है जिसकी लोक लेखा समिति ने अक्सर आलोचना की है।"},
  {"id":"eco-planning-budget-244","question":"Assertion (A): If a government’s revenue deficit is zero, all its borrowing in that year goes into capital expenditure and net lending. Reason (R): The fiscal deficit equals the revenue deficit plus capital expenditure minus non-debt capital receipts.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"With a zero revenue deficit, the fiscal deficit equals capital spending (including loans) not covered by non-debt receipts, so borrowing is used only to build assets. This is the logic of the ‘golden rule’.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"अभिकथन (A): यदि किसी सरकार का राजस्व घाटा शून्य है, तो उस वर्ष की उसकी सारी उधारी पूंजीगत व्यय और निवल उधार में जाती है। कारण (R): राजकोषीय घाटा राजस्व घाटे जमा पूंजीगत व्यय घटा गैर-ऋण पूंजीगत प्राप्तियों के बराबर होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"शून्य राजस्व घाटे के साथ राजकोषीय घाटा उस पूंजीगत व्यय (ऋणों सहित) के बराबर होता है जो गैर-ऋण प्राप्तियों से पूरा नहीं होता, इसलिए उधारी केवल परिसंपत्तियाँ बनाने में लगती है। यही ‘स्वर्णिम नियम’ का तर्क है।"},
  {"id":"eco-planning-budget-245","question":"Match the Second Plan steel plant with the country that helped build it: A. Bhilai  B. Rourkela  C. Durgapur; 1. United Kingdom  2. Soviet Union  3. West Germany","options":["A-2, B-3, C-1","A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2"],"answer":0,"explanation":"Bhilai was built with Soviet help, Rourkela with West German help and Durgapur with British help, reflecting the Second Plan’s push for basic and heavy industry in the public sector.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"द्वितीय योजना के इस्पात संयंत्र का उसके निर्माण में सहायता करने वाले देश से मिलान कीजिए: A. भिलाई  B. राउरकेला  C. दुर्गापुर; 1. यूनाइटेड किंगडम  2. सोवियत संघ  3. पश्चिम जर्मनी","optionsHi":["A-2, B-3, C-1","A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2"],"explanationHi":"भिलाई का निर्माण सोवियत सहायता से, राउरकेला का पश्चिम जर्मन सहायता से और दुर्गापुर का ब्रिटिश सहायता से हुआ, जो द्वितीय योजना के सार्वजनिक क्षेत्र में बुनियादी और भारी उद्योग पर बल को दर्शाता है।"},
  {"id":"eco-planning-budget-246","question":"Government borrowing is least likely to crowd out private investment when:","options":["The economy is at full employment and the central bank holds money supply fixed","Private investment spending is highly sensitive to changes in the rate of interest","The government borrows heavily from domestic banks at the peak of a boom","The economy has idle capacity and the central bank keeps rates steady"],"answer":3,"explanation":"Crowding out works through higher interest rates and scarce resources. With idle capacity and accommodative monetary policy, extra spending raises output and may even ‘crowd in’ investment.","difficulty":"hard","source":"RBI Grade B","questionHi":"सरकारी उधारी निजी निवेश को सबसे कम कब विस्थापित करती है?","optionsHi":["जब अर्थव्यवस्था पूर्ण रोज़गार पर हो और केंद्रीय बैंक मुद्रा आपूर्ति स्थिर रखे","जब निजी निवेश व्यय ब्याज दर के परिवर्तनों के प्रति अत्यधिक संवेदनशील हो","जब सरकार तेज़ी के शिखर पर घरेलू बैंकों से भारी उधार ले","जब अर्थव्यवस्था में निष्क्रिय क्षमता हो और केंद्रीय बैंक दरें स्थिर रखे"],"explanationHi":"भीड़-बाह्यकरण ऊँची ब्याज दरों और दुर्लभ संसाधनों के माध्यम से काम करता है। निष्क्रिय क्षमता और सहायक मौद्रिक नीति के साथ अतिरिक्त व्यय उत्पादन बढ़ाता है और निवेश को ‘आकर्षित’ भी कर सकता है।"},
  {"id":"eco-planning-budget-247","question":"Statutory grants-in-aid to States under Article 275 are:","options":["Voted each year by the Lok Sabha as part of the demands for grants","Charged on the Consolidated Fund of India","Paid from the Contingency Fund of India","Given at the discretion of the Union Finance Ministry"],"answer":1,"explanation":"Article 275(1) charges these grants on the Consolidated Fund of India, so they are not voted, and they are made on the Finance Commission’s recommendation. Discretionary grants come under Article 282.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 275 के अंतर्गत राज्यों को सांविधिक सहायता अनुदान:","optionsHi":["अनुदान मांगों के भाग के रूप में हर वर्ष लोकसभा द्वारा मतदान से स्वीकृत होते हैं","भारत की संचित निधि पर भारित हैं","भारत की आकस्मिकता निधि से दिए जाते हैं","केंद्रीय वित्त मंत्रालय के विवेक पर दिए जाते हैं"],"explanationHi":"अनुच्छेद 275(1) इन अनुदानों को भारत की संचित निधि पर भारित करता है, इसलिए इन पर मतदान नहीं होता, और ये वित्त आयोग की सिफारिश पर दिए जाते हैं। विवेकाधीन अनुदान अनुच्छेद 282 के अंतर्गत आते हैं।"},
  {"id":"eco-planning-budget-248","question":"Which of these is a ‘blocked credit’, i.e. input tax credit that cannot be claimed, under the GST law?","options":["GST paid on raw materials used in manufacturing","GST paid on computers bought for the office","GST paid on club membership for an employee","GST paid on freight to deliver goods to buyers"],"answer":2,"explanation":"Section 17(5) of the CGST Act blocks credit on items of personal consumption such as club membership, food and beverages and most motor vehicles. Inputs, capital goods and input services used for business qualify.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"इनमें से कौन GST कानून के अंतर्गत ‘अवरुद्ध क्रेडिट’ है, अर्थात् ऐसा इनपुट टैक्स क्रेडिट जिसका दावा नहीं किया जा सकता?","optionsHi":["विनिर्माण में प्रयुक्त कच्चे माल पर चुकाया GST","कार्यालय के लिए खरीदे कंप्यूटरों पर चुकाया GST","किसी कर्मचारी की क्लब सदस्यता पर चुकाया GST","क्रेताओं तक माल पहुँचाने के भाड़े पर चुकाया GST"],"explanationHi":"CGST अधिनियम की धारा 17(5) क्लब सदस्यता, खान-पान और अधिकांश मोटर वाहनों जैसी व्यक्तिगत उपभोग की मदों पर क्रेडिट अवरुद्ध करती है। व्यवसाय में प्रयुक्त इनपुट, पूंजीगत वस्तुएँ और इनपुट सेवाएँ क्रेडिट के पात्र हैं।"},
  {"id":"eco-planning-budget-249","question":"Which of the following is a non-tax revenue receipt of the Union Government?","options":["Corporation tax collected from companies on their profits","Customs duty collected on imports of gold and silver","Proceeds from selling part of the government’s stake in a PSU","Dividends from PSUs and the surplus transferred by the RBI"],"answer":3,"explanation":"Non-tax revenue includes dividends and profits, interest receipts and fees. Corporation tax and customs are tax revenue, and disinvestment proceeds are non-debt capital receipts, not revenue.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"निम्नलिखित में से कौन केंद्र सरकार की गैर-कर राजस्व प्राप्ति है?","optionsHi":["कंपनियों से उनके लाभ पर वसूला गया निगम कर","सोने और चाँदी के आयात पर वसूला गया सीमा शुल्क","किसी PSU में सरकार की हिस्सेदारी का कुछ भाग बेचने से प्राप्तियाँ","PSU से लाभांश और RBI द्वारा अंतरित अधिशेष"],"explanationHi":"गैर-कर राजस्व में लाभांश और लाभ, ब्याज प्राप्तियाँ और शुल्क शामिल हैं। निगम कर और सीमा शुल्क कर राजस्व हैं, और विनिवेश की प्राप्तियाँ गैर-ऋण पूंजीगत प्राप्तियाँ हैं, राजस्व नहीं।"},
  {"id":"eco-planning-budget-250","question":"An income-tax ‘surcharge’ is best described as:","options":["An extra tax on the tax payable, mainly on higher incomes","A tax levied for a specified purpose such as health and education","A penalty charged for filing the income-tax return after the due date","A tax collected at source by banks on large cash withdrawals"],"answer":0,"explanation":"A surcharge is a percentage of the tax already payable, used to raise the burden on high earners; a cess is earmarked for a stated purpose. Neither forms part of the divisible pool shared with States.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"आयकर ‘अधिभार’ (सरचार्ज) का सबसे उपयुक्त वर्णन क्या है?","optionsHi":["देय कर पर लगने वाला अतिरिक्त कर, मुख्यतः ऊँची आय पर","किसी निर्दिष्ट प्रयोजन, जैसे स्वास्थ्य और शिक्षा, के लिए लगाया गया कर","आयकर रिटर्न देय तिथि के बाद दाखिल करने पर लगाया गया दंड","बड़े नकद आहरण पर बैंकों द्वारा स्रोत पर वसूला गया कर"],"explanationHi":"अधिभार पहले से देय कर का प्रतिशत है, जो अधिक कमाने वालों पर बोझ बढ़ाने के लिए प्रयुक्त होता है; उपकर किसी बताए गए प्रयोजन के लिए निर्धारित होता है। इनमें से कोई भी राज्यों के साथ साझा होने वाले विभाज्य पूल का भाग नहीं है।"},
];

export default questions;
